            </div>

        </article>

        <!-- 3 -->

        <article class="cc-directoras__card">

            <iframe
                src="https://www.youtube.com/embed/FPSUgcGZDcE"
                title="Laura Citarella entrevistada por Rut Marega"
                allowfullscreen>
            </iframe>

            <h3>Laura Citarella entrevistada por Rut Marega</h3>

            <div class="cc-directoras__datos">

                <div>
                    <strong>Participan</strong>
                    <span>Laura Citarella (Directora) · Rut Marega (Periodista especializada en cine y cultura)</span>
                </div>

                <div>
                    <strong>Realización</strong>
                    <span>Dirección: Betania Cappato · Montaje: Baltazar Albrecht</span>
                </div>

                <div>
                    <strong>Lugar</strong>
                    <span>Estación Belgrano · Santa Fe</span>
                </div>

            </div>

        </article>

        <!-- 4 -->

        <article class="cc-directoras__card">

            <iframe
                src="https://www.youtube.com/embed/ZuMfT6lk0Bs"
                title="Julia Kratje presenta a Lucrecia Martel"
                allowfullscreen>
            </iframe>

            <h3>Julia Kratje presenta a Lucrecia Martel</h3>

            <div class="cc-directoras__datos">

                <div>
                    <strong>Presentación</strong>
