[{"id":"bdc1b46","elType":"section","settings":{"margin":{"unit":"px","top":"0","right":0,"bottom":"50","left":0,"isLinked":false}},"elements":[{"id":"5c76294","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"a4f8b44","elType":"widget","settings":{"html":"<section class="cc-ariel100">

    <div class="cc-ariel100__contenedor">

        <div class="cc-ariel100__imagen">
            <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2021/08/600x400_arielramirez.jpg" alt="100 años de Ariel Ramírez">
        </div>

        <div class="cc-ariel100__contenido">

            <span class="cc-ariel100__etiqueta">
                Archivo de la Imagen Documental Santafesina
            </span>

            <h2>
                100 años · 100 imágenes
            </h2>

            <p>
                El sábado <strong>4 de septiembre de 2021</strong>, día en que se cumplen
                <strong>100 años del nacimiento de Ariel Ramírez</strong>, Capital Cultural
                presenta una selección de <strong>100 fotografías documentales</strong>,
                parte del patrimonio del Museo del Teatro Municipal "1° de Mayo".
            </p>

            <p>
                Las imágenes, registro de la vida y obra del compositor en la ciudad,
                fueron liberadas en el marco del <strong>Archivo de la Imagen
                Documental Santafesina</strong>, impulsado por la Municipalidad de
                Santa Fe.
            </p>

            <p>
                El proyecto fue realizado en colaboración con
                <strong>Wikimedia</strong>, plataforma de contenidos educativos libres,
                con el asesoramiento del Archivo General de la Nación y del
                investigador <strong>Luis Príamo</strong>.
            </p>

            <div class="cc-ariel100__botones">

                <a href="https://commons.wikimedia.org/w/index.php?search=Municipio+Santa+Fe++Ariel+Ram%C3%ADrez+&title=Special:MediaSearch&go=Go&type=image"
                   target="_blank"
                   rel="noopener">
                    Ver imágenes liberadas
                </a>

            </div>

        </div>

    </div>

</section>

