    color:#00A67A;
    padding:7px 14px;
    border-radius:4px;
    font-size:13px;
    font-weight:700;
    margin-bottom:18px;
    text-transform:uppercase;
    letter-spacing:.05em;
}

.cc-ariel100__contenido h2{
    font-size:20px;
