    {"n":"El toro de Santia Dassie","t":"ar","lat":-31.569392,"lng":-60.730083,"u":"/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/el-toro-de-santia-dassie/","d":"Av. Blas Parera 9699","f":"/capitalcultural/wp-content/uploads/2022/10/FOTO-DE-PORTADA-1-Fotografia-de-la-obra-El-Toro.png","m":"/capitalcultural/wp-content/uploads/2022/10/FOTO-DE-PORTADA-1-Fotografia-de-la-obra-El-Toro.png"},
    {"n":"Monumento a José Gorostiaga","t":"ar","lat":-31.605745,"lng":-60.720204,"u":"/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/monumento-a-jose-gorostiaga/","d":"Av. Blas Parera, San Pantaleón","f":"/capitalcultural/wp-content/uploads/2022/10/FOTO-DE-PORTADA-1-Monumento-al-Dr.-Jose-Benjamin-Gorostiaga-por-Raquel-Minetti-576x1024.jpeg","m":"/capitalcultural/wp-content/uploads/2022/10/FOTO-DE-PORTADA-1-Monumento-al-Dr.-Jose-Benjamin-Gorostiaga-por-Raquel-Minetti-576x1024.jpeg","o":"50% 0%"},
    {"n":"La Madre de José Sedlacek","t":"ar","lat":-31.616022,"lng":-60.718101,"u":"/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/la-madre-de-jose-sedlacek/","d":"Cementerio Municipal","f":"/capitalcultural/wp-content/uploads/2022/10/3-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-frente-del-museo-2017-1024x768.jpg","m":"/capitalcultural/wp-content/uploads/2022/10/3-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-frente-del-museo-2017-768x576.jpg"},
    {"n":"Dolorosa de José Sedlacek","t":"ar","lat":-31.616016,"lng":-60.718062,"u":"/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/dolorosa-de-jose-sedlacek/","d":"Cementerio Municipal","f":"/capitalcultural/wp-content/uploads/2022/10/2-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-activacion-2017-1-1024x576.jpg","m":"/capitalcultural/wp-content/uploads/2022/10/2-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-activacion-2017-1-768x432.jpg"},
    {"n":"El ángel de Federico Fabiani","t":"ar","lat":-31.616054,"lng":-60.718124,"u":"/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/el-angel-de-federico-fabiani/","d":"Cementerio Municipal","f":"/capitalcultural/wp-content/uploads/2022/10/2-archivo-digital-MMAV-noche-de-los-museos-cementerio-municipal-2018-1024x682.jpg","m":"/capitalcultural/wp-content/uploads/2022/10/2-archivo-digital-MMAV-noche-de-los-museos-cementerio-municipal-2018-768x512.jpg"},
    {"n":"Fuente: Dama con cántaro","t":"ar","lat":-31.638361,"lng":-60.718746,"u":"/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/fuente-dama-con-cantaro/","d":"Av. Presidente Perón 3000","f":"/capitalcultural/wp-content/uploads/2022/10/dama.jpg","m":"/capitalcultural/wp-content/uploads/2022/10/dama-400x400.jpg"}]

  var TIPOS = { ar: 'Patrimonio artístico', aq: 'Patrimonio arquitectónico' }
  var ORIGEN = 'https://www.santafeciudad.gov.ar'
  var VISOR = 'https://www.google.com/maps/d/viewer?mid=1W9w8u394ieHgF8afTNaJ6BP58MZAR0k'

  var MAPLIBRE = {
    js: 'https://unpkg.com/maplibre-gl@5.24.0/dist/maplibre-gl.js',
    jsSri: 'sha384-5+cfbwT0iiub6VsQAdn6yz16nr6sDiQoHx6tm4O8OVYXHYOxcffFmCJBL0dgdvGp',
    css: 'https://unpkg.com/maplibre-gl@5.24.0/dist/maplibre-gl.css',
    cssSri: 'sha384-uTttxo/aOKbdE5RlD/SPzSDoDmNvGlUYPjONi2MN/b7c9HPSvW07OIuyP7uL6jxK'
  }
  var ESTILO_MAPA = 'https://tiles.openfreemap.org/styles/positron'

  var PALETA_MAPA = {
    fondo: '#f4f4f3', manzana: '#ededeb', verde: '#e4ebe7', agua: '#cfe8f7',
    edificio: '#e2e2df', edificioBorde: '#d5d5d2', calle: '#ffffff', avenida: '#ffffff',
    autopista: '#ffffff', borde: '#d3d3d0', limite: 'rgba(0,39,81,.25)',
    texto: '#606060', textoAgua: '#3d7aa6', halo: '#ffffff'
  }

  var TEXTOS_MAPA = {
    'AttributionControl.ToggleAttribution': 'Mostrar créditos del mapa',
    'Map.Title': 'Mapa del patrimonio cultural público',
    'Marker.Title': 'Punto del mapa',
    'NavigationControl.ZoomIn': 'Acercar',
    'NavigationControl.ZoomOut': 'Alejar',
    'CooperativeGesturesHandler.WindowsHelpText': 'Usá Ctrl + la rueda del mouse para acercar el mapa',
    'CooperativeGesturesHandler.MacHelpText': 'Usá ⌘ + la rueda del mouse para acercar el mapa',
    'CooperativeGesturesHandler.MobileHelpText': 'Usá dos dedos para mover el mapa'
  }

  var CRUZ = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>'

  var raiz = document.getElementById('pp')
  var modal = raiz && raiz.querySelector('[data-pp-modal]')
  if (!modal || raiz.dataset.ppInit === '1') return
  raiz.dataset.ppInit = '1'

  function esc (s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
    })
  }

  var LUGARES = (function () {
    var porClave = {}, lista = []
    PUNTOS.forEach(function (p) {
      var k = p.lat + ',' + p.lng
      if (!porClave[k]) lista.push(porClave[k] = { id: lista.length, lat: p.lat, lng: p.lng, obras: [] })
      porClave[k].obras.push(p)
    })
    lista.forEach(function (l) {
      l.tipos = l.obras.reduce(function (t, o) { if (t.indexOf(o.t) < 0) t.push(o.t); return t }, [])
    })
    return lista
  })()

  function cargarMapLibre () {
    if (window.maplibregl) return Promise.resolve(window.maplibregl)
    if (window.PP_MAPLIBRE) return window.PP_MAPLIBRE
    if (!document.querySelector('link[data-pp-maplibre]')) {
      var hoja = document.createElement('link')
      hoja.rel = 'stylesheet'
      hoja.href = MAPLIBRE.css
      hoja.integrity = MAPLIBRE.cssSri
      hoja.crossOrigin = 'anonymous'
      hoja.setAttribute('data-pp-maplibre', '')
      document.head.appendChild(hoja)
    }
    var carga = window.PP_MAPLIBRE = new Promise(function (ok, mal) {
      var s = document.createElement('script')
      s.src = MAPLIBRE.js
      s.integrity = MAPLIBRE.jsSri
      s.crossOrigin = 'anonymous'
      s.async = true
      s.onload = function () { window.maplibregl ? ok(window.maplibregl) : mal(new Error('MapLibre cargó pero no quedó disponible')) }
      s.onerror = function () { mal(new Error('No se pudo cargar MapLibre')) }
      document.head.appendChild(s)
    })
    carga.catch(function () { window.PP_MAPLIBRE = null })
    return carga
  }

  function cargarEstilo () {
    return fetch(ESTILO_MAPA).then(function (r) {
      if (!r.ok) throw new Error('Estilo HTTP ' + r.status)
      return r.json()
    }).then(tematizarMapa)
  }

  function tematizarMapa (estilo) {
    var P = PALETA_MAPA
    estilo.layers = estilo.layers.filter(function (l) {
      return l.type !== 'raster' && l.type !== 'hillshade' && !/shield/.test(l.id)
    })
    estilo.layers.forEach(function (l) {
      var id = l.id
      var p = l.paint = l.paint || {}
      if (l.type === 'background') {
        p['background-color'] = P.fondo
      } else if (l.type === 'fill') {
        p['fill-color'] = /water/.test(id) ? P.agua
          : /building/.test(id) ? P.edificio
            : /park|wood|grass|landcover/.test(id) ? P.verde
              : /pier|aeroway/.test(id) ? P.fondo
                : P.manzana
        if (/building/.test(id)) p['fill-outline-color'] = P.edificioBorde
      } else if (l.type === 'line') {
        p['line-color'] = /water/.test(id) ? P.agua
          : /boundary/.test(id) ? P.limite
            : /casing/.test(id) ? P.borde
              : /dashline|pier/.test(id) ? P.fondo
                : /motorway/.test(id) ? P.autopista
                  : /major/.test(id) ? P.avenida
                    : P.calle
      } else if (l.type === 'symbol') {
        var agua = /water/.test(id)
        p['text-color'] = agua ? P.textoAgua : P.texto
        p['text-halo-color'] = agua ? P.agua : P.halo
        p['text-halo-width'] = 1.2
        p['text-halo-blur'] = 0
      }
    })
    return estilo
  }

  function marcador (l) {
    var b = document.createElement('button')
    var n = l.obras.length
    b.type = 'button'
    b.setAttribute('data-lugar', l.id)
    b.setAttribute('aria-haspopup', 'dialog')
    if (n > 1) {
      b.className = 'pp-punto pp-punto--grupo'
      b.setAttribute('aria-label', n + ' obras en ' + (l.obras[0].d || 'este lugar') + '. Ver listado')
      b.innerHTML = '<span class="pp-punto__n">' + n + '</span>'
    } else {
      var o = l.obras[0]
      b.className = 'pp-punto'
      b.setAttribute('aria-label', o.n + '. ' + TIPOS[o.t] + '. Ver datos')
      b.innerHTML = '<span class="pp-muestra"></span>'
    }
    return b
  }

  function cabecera (tipoHtml, titulo) {
    return '<div class="pp-modal__cabecera"><div>' + tipoHtml +
      '<h2 class="pp-modal__titulo" id="pp-modal-titulo">' + esc(titulo) + '</h2></div>' +
      '<button type="button" class="pp-modal__cerrar" data-cerrar aria-label="Cerrar">' + CRUZ + '</button></div>'
  }

  function comoLlegar (l) {
    return '<a class="pp-btn pp-btn--linea" href="https://www.google.com/maps/dir/?api=1&amp;destination=' +
      l.lat + ',' + l.lng + '" target="_blank" rel="noopener">Cómo llegar</a>'
  }

  function subirEncuadre (pos) {
    var p = pos.split(' ')
    return p[0] + ' ' + Math.max(0, parseFloat(p[1]) - 18) + '%'
  }

  function contenidoLugar (l) {
    var h = '<div class="pp-modal__cuerpo">'
    if (l.obras.length > 1) {
      h += cabecera('<p class="pp-modal__tipo">' + l.obras.length + ' obras en este lugar</p>', l.obras[0].d || 'Mismo lugar') +
        '<div class="pp-modal__contenido"><ul class="pp-modal__lista">'
      l.obras.forEach(function (o) {
        var mini = o.m || o.f
        h += '<li><a href="' + esc(o.u) + '">' +
          (mini ? '<img class="pp-modal__mini" src="' + esc(ORIGEN + mini) + '" alt="" width="56" height="56" loading="lazy"' +
            (o.o ? ' style="object-position: ' + esc(o.o) + '"' : '') + '>' : '<span class="pp-muestra"></span>') +
          '<span><span class="pp-sr">' + TIPOS[o.t] + ': </span>' + esc(o.n) + '</span></a></li>'
      })
      return h + '</ul></div><div class="pp-modal__pie">' + comoLlegar(l) + '</div></div>'
    }
    var o = l.obras[0]
    h += cabecera('<p class="pp-modal__tipo"><span class="pp-muestra"></span>' + TIPOS[o.t] + '</p>', o.n)
    if (o.f) {
      h += '<img class="pp-modal__foto" src="' + esc(ORIGEN + o.f) + '" alt="" width="768" height="480"' +
        (o.o ? ' style="object-position: ' + esc(subirEncuadre(o.o)) + '"' : '') + '>'
    }
    if (o.d || o.p) {
      h += '<div class="pp-modal__contenido"><dl class="pp-modal__datos">'
      if (o.d) h += '<div><dt>Dirección</dt><dd>' + esc(o.d) + '</dd></div>'
      if (o.p) h += '<div><dt>Protección</dt><dd>' + esc(o.p) + ' histórico</dd></div>'
      h += '</dl></div>'
    }
    return h + '<div class="pp-modal__pie"><a class="pp-btn pp-btn--primario" href="' + esc(o.u) + '">' +
      '<i class="pp-barra"></i>Ver la ficha</a>' + comoLlegar(l) + '</div></div>'
  }

  var ultimoFoco = null
  function abrirLugar (l, disparador) {
    ultimoFoco = disparador
    modal.innerHTML = contenidoLugar(l)
    if (!modal.open) modal.showModal()
    var primero = modal.querySelector('.pp-modal__pie a, .pp-modal__lista a')
    if (primero) primero.focus()
  }
  modal.addEventListener('click', function (ev) {
    if (ev.target === modal || ev.target.closest('[data-cerrar]')) modal.close()
  })
  modal.addEventListener('close', function () {
    if (modal.open) return
    modal.innerHTML = ''
    if (ultimoFoco && document.contains(ultimoFoco)) ultimoFoco.focus()
    ultimoFoco = null
  })

  function pieMapa () {
    var cuenta = { ar: 0, aq: 0 }
    PUNTOS.forEach(function (p) { cuenta[p.t]++ })
    return '<div class="pp-mapa__pie"><div class="pp-mapa__filtros" role="group" aria-label="Mostrar en el mapa">' +
      ['ar', 'aq'].map(function (t) {
        return '<button type="button" class="pp-filtro" data-pp-filtro="' + t + '" aria-pressed="true">' +
          '<span class="pp-muestra"></span>' + (t === 'ar' ? 'Artístico' : 'Arquitectónico') +
          ' <span class="pp-filtro__n">' + cuenta[t] + '</span></button>'
      }).join('') +
      '</div></div>'
  }

  function iniciarMapa (caja) {
    caja.innerHTML = '<div class="pp-mapa__lienzo" data-pp-lienzo></div>' + pieMapa()
    var lienzo = caja.querySelector('[data-pp-lienzo]')
    var activos = { ar: true, aq: true }
    var botones = []

    lienzo.addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-lugar]')
      if (b) abrirLugar(LUGARES[b.getAttribute('data-lugar')], b)
    })

    caja.querySelector('.pp-mapa__filtros').addEventListener('click', function (ev) {
      var f = ev.target.closest('[data-pp-filtro]')
      if (!f) return
      var t = f.getAttribute('data-pp-filtro')
      activos[t] = !activos[t]
      f.setAttribute('aria-pressed', String(activos[t]))
      botones.forEach(function (b) {
        b.hidden = !LUGARES[b.getAttribute('data-lugar')].tipos.some(function (x) { return activos[x] })
      })
    })

    function sinMapa (err) {
      lienzo.innerHTML = '<div class="pp-mapa__aviso"><p>No pudimos cargar el mapa.</p>' +
        '<p><a href="' + VISOR + '" target="_blank" rel="noopener">Abrilo en Google Maps</a></p></div>'
      if (window.console) console.error('[Patrimonio]', err)
    }

    function montar () {
      Promise.all([cargarMapLibre(), cargarEstilo()]).then(function (r) {
        var ml = r[0]
        var limites = new ml.LngLatBounds()
        LUGARES.forEach(function (l) { limites.extend([l.lng, l.lat]) })
        var quieto = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches
        var mapa = new ml.Map({
          container: lienzo,
          style: r[1],
          bounds: limites,
          fitBoundsOptions: { padding: 36, maxZoom: 15 },
          cooperativeGestures: true,
          dragRotate: false,
          pitchWithRotate: false,
          touchPitch: false,
          fadeDuration: quieto ? 0 : 300,
          attributionControl: { compact: true },
          locale: TEXTOS_MAPA
        })
        mapa.touchZoomRotate.disableRotation()
        mapa.keyboard.disableRotation()
        mapa.addControl(new ml.NavigationControl({ showCompass: false }), 'top-right')
        mapa.once('idle', function () {
          var c = lienzo.querySelector('.maplibregl-ctrl-attrib.maplibregl-compact')
          if (c) c.classList.remove('maplibregl-compact-show')
        })
        LUGARES.forEach(function (l) {
          var b = marcador(l)
          botones.push(b)
          new ml.Marker({ element: b, anchor: 'center' }).setLngLat([l.lng, l.lat]).addTo(mapa)
        })
      }).catch(sinMapa)
    }

    if (!('IntersectionObserver' in window)) return montar()
    var vigia = new IntersectionObserver(function (e) {
      if (!e.some(function (x) { return x.isIntersecting })) return
      vigia.disconnect()
      montar()
    }, { rootMargin: '300px 0px' })
    vigia.observe(lienzo)
  }

  raiz.querySelectorAll('[data-pp-mapa]').forEach(iniciarMapa)
})()
</script>
"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false}]

{"timeout":1792682423,"value":{"content":"		<section class="elementor-section elementor-top-section elementor-element elementor-element-2b803cf elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="2b803cf" data-element_type="section" data-e-type="section">
						<div class="elementor-container elementor-column-gap-default">
					<div class="elementor-column elementor-col-100 elementor-top-column elementor-element elementor-element-fdfb960" data-id="fdfb960" data-element_type="column" data-e-type="column">
			<div class="elementor-widget-wrap elementor-element-populated">
						<div class="elementor-element elementor-element-8314911 elementor-widget elementor-widget-html" data-id="8314911" data-element_type="widget" data-e-type="widget" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<style>
  .elementor-widget-wrap:has(> .elementor-widget-html #pp),
  .elementor-widget-html:has(#pp) > .elementor-widget-container { padding: 0; margin: 0; }
  .ast-container > .elementor:has(#pp) { flex: 1 1 100%; min-width: 0; }

  #pp {
    --azul: #002751;
    --celeste: #00aaff;
    --rojo: #e63312;
    --gris-20: #dadad9;
    --gris-75: #606060;
    --linea: rgba(0, 39, 81, .12);
    --inclinacion: -15deg;
    --r-lg: 26px;
    --r-md: 18px;
    --curva: cubic-bezier(.16, 1, .3, 1);
    --ancho: 1120px;
    --gutter: clamp(16px, 4vw, 32px);
    color: var(--azul);
    font: 400 16px/1.6 "Encode Sans", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    -webkit-font-smoothing: antialiased;
  }
  #pp *, #pp *::before, #pp *::after { box-sizing: border-box; }
  #pp :is(h1, h2, p, ul, dl, dd) { margin: 0; padding: 0; }
  #pp ul { list-style: none; }
  #pp img { display: block; max-width: 100%; border-radius: 0; }
  #pp [hidden] { display: none !important; }
  #pp .pp-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  #pp :is(h1, h2) { color: inherit; font-family: inherit; text-transform: none; letter-spacing: -.015em; }

  #pp :is(a, button):focus-visible { outline: 0; box-shadow: 0 0 0 2px #fff, 0 0 0 5px var(--rojo); }

  #pp .pp-barra {
    display: inline-block; flex: none;
    width: .2em; height: .78em; margin-right: .38em;
    background: var(--rojo);
    transform: skewX(var(--inclinacion));
  }

  #pp .pp-b { padding-block: clamp(32px, 5vw, 64px) 50px; }

  #pp .pp-limite { max-width: var(--ancho); margin-inline: auto; padding-inline: var(--gutter); }
  #pp .pp-grilla {
    display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr);
    gap: clamp(24px, 4vw, 56px); align-items: stretch;
  }
  #pp .pp-texto { display: grid; gap: 1.1rem; }
  #pp .pp-ceja { font-size: .8rem; font-weight: 600; letter-spacing: .09em; text-transform: uppercase; color: var(--gris-75); }
  #pp .pp-lead {
    display: flex; align-items: baseline;
    font-size: clamp(1.35rem, 2.4vw, 1.75rem); font-weight: 700; line-height: 1.25; letter-spacing: -.01em;
  }
  #pp .pp-lead .pp-barra { translate: 0 .1em; }

  #pp .pp-ctas { display: grid; gap: .85rem; margin-top: 1rem; }
  #pp .pp-fila {
    position: relative; isolation: isolate;
    display: grid; grid-template-columns: 96px minmax(0, 1fr) auto; align-items: center; gap: 1rem;
    padding: .65rem 1.1rem .65rem .65rem; border-radius: var(--r-md);
    background: linear-gradient(160deg, rgba(255, 255, 255, .72), rgba(255, 255, 255, .46));
    -webkit-backdrop-filter: blur(20px) saturate(170%);
            backdrop-filter: blur(20px) saturate(170%);
    box-shadow:
      0 1px 1px rgba(0, 39, 81, .04),
      0 16px 36px -14px rgba(0, 39, 81, .26),
      inset 0 1px 0 rgba(255, 255, 255, .9);
    color: var(--azul); text-decoration: none;
    transition: transform .3s var(--curva);
  }
  #pp .pp-fila:hover { color: var(--azul); }
  #pp .pp-fila img { width: 96px; height: 76px; object-fit: cover; border-radius: 12px; }
  #pp .pp-fila__titulo { display: block; font-size: 1.12rem; font-weight: 700; line-height: 1.2; }
  #pp .pp-fila__texto { display: block; margin-top: .2rem; font-size: .92rem; line-height: 1.4; color: var(--gris-75); }
  #pp .pp-fila__flecha {
    display: grid; place-items: center; width: 40px; height: 40px; border-radius: 10px;
    background: var(--azul); color: #fff;
  }
  #pp .pp-fila__flecha svg { width: 18px; height: 18px; transition: transform .3s var(--curva); }
  @media (hover: hover) {
    #pp .pp-fila:hover { transform: translateX(4px); }
    #pp .pp-fila:hover .pp-fila__flecha svg { transform: translateX(3px); }
  }

  #pp .pp-btn {
    position: relative; overflow: hidden; isolation: isolate;
    display: inline-flex; align-items: center; justify-content: center; gap: .55em;
    min-height: 44px; padding: 0 20px; border: 0; border-radius: 10px;
    font-family: inherit; font-size: 15px; font-weight: 600; line-height: 1;
    text-decoration: none; cursor: pointer;
    transition: background .2s ease;
  }
  #pp .pp-btn::after {
    content: ""; position: absolute; top: 0; left: -75%; width: 38%; height: 100%;
    background: linear-gradient(105deg, transparent, rgba(255, 255, 255, .3), transparent);
    transform: skewX(var(--inclinacion));
    transition: left .6s var(--curva); pointer-events: none;
  }
  @media (hover: hover) { #pp .pp-btn:hover::after { left: 135%; } }
  #pp .pp-btn .pp-barra { height: 1.05em; margin: 0; }
  #pp .pp-btn--primario, #pp .pp-btn--primario:hover { background: var(--azul); color: #fff; }
  #pp .pp-btn--linea, #pp .pp-btn--linea:hover { background: transparent; color: var(--azul); box-shadow: inset 0 0 0 1.5px var(--azul); }
  @media (hover: hover) { #pp .pp-btn--linea:hover { background: rgba(0, 39, 81, .06); } }

  #pp .pp-mapa {
    display: flex; flex-direction: column;
