    gap: .6rem 1rem; padding: .75rem 1rem;
    border-top: 1px solid var(--linea);
    font-size: .9rem;
  }
  #pp .pp-mapa__filtros { display: flex; flex-wrap: wrap; gap: .5rem; }
  #pp .pp-filtro, #pp .pp-filtro:hover, #pp .pp-filtro:focus {
    display: inline-flex; align-items: center; gap: .55rem;
    min-height: 40px; margin: 0; padding: 0 .9rem;
    border: 1px solid rgba(0, 39, 81, .22); border-radius: 999px;
    background: rgba(0, 39, 81, .04); color: var(--azul);
    font-family: inherit; font-size: .9rem; font-weight: 600; line-height: 1; text-transform: none;
    cursor: pointer;
  }
  #pp .pp-filtro[aria-pressed="false"] { background: transparent; color: var(--gris-75); text-decoration: line-through; }
  #pp .pp-filtro[aria-pressed="false"] .pp-muestra { opacity: .35; }
  #pp .pp-filtro__n { font-weight: 400; color: var(--gris-75); }

  #pp .pp-muestra { display: block; flex: none; width: 12px; height: 12px; border-radius: 50%; background: var(--rojo); box-shadow: 0 0 0 2px #fff; }

  #pp .pp-punto, #pp .pp-punto:hover, #pp .pp-punto:focus {
    display: grid; place-items: center;
    width: 30px; height: 30px; min-height: 0; margin: 0; padding: 0;
    border: 0; border-radius: 50%; background: transparent; cursor: pointer;
  }
  #pp .pp-punto .pp-muestra { transition: transform .15s ease; }
  #pp .pp-punto:hover .pp-muestra, #pp .pp-punto:focus-visible .pp-muestra { transform: scale(1.45); }
  #pp .pp-punto--grupo { z-index: 1; }
  #pp .pp-punto__n {
    display: grid; place-items: center; min-width: 26px; height: 26px; padding: 0 6px;
    border-radius: 999px; background: #fff; color: var(--azul);
    font-family: inherit; font-size: .8rem; font-weight: 700; line-height: 1;
    box-shadow: 0 0 0 3px var(--rojo), 0 4px 10px rgba(0, 0, 0, .35);
    transition: transform .15s ease;
  }
  #pp .pp-punto--grupo:hover .pp-punto__n, #pp .pp-punto--grupo:focus-visible .pp-punto__n { transform: scale(1.12); }

  #pp .maplibregl-ctrl-group {
    overflow: hidden; border: 1px solid var(--linea); border-radius: 10px;
    background: #fff; box-shadow: 0 6px 18px rgba(0, 39, 81, .16);
  }
  #pp .maplibregl-ctrl-group button, #pp .maplibregl-ctrl-group button:focus {
    display: block; width: 38px; height: 38px; min-height: 0; margin: 0; padding: 0;
