  var LUGARES = (function () {
    var porClave = {}, lista = []
    PUNTOS.forEach(function (p) {
      var k = p.lat + ',' + p.lng
      if (!porClave[k]) lista.push(porClave[k] = { id: lista.length, lat: p.lat, lng: p.lng, obras: [] })
      porClave[k].obras.push(p)
    })
    lista.forEach(function (l) {
      l.tipos = l.obras.reduce(function (t, o) { if (t.indexOf(o.t) < 0) t.push(o.t); return t }, [])
    })
    return lista
  })()

  function cargarMapLibre () {
    if (window.maplibregl) return Promise.resolve(window.maplibregl)
    if (window.PP_MAPLIBRE) return window.PP_MAPLIBRE
    if (!document.querySelector('link[data-pp-maplibre]')) {
      var hoja = document.createElement('link')
      hoja.rel = 'stylesheet'
      hoja.href = MAPLIBRE.css
      hoja.integrity = MAPLIBRE.cssSri
      hoja.crossOrigin = 'anonymous'
      hoja.setAttribute('data-pp-maplibre', '')
      document.head.appendChild(hoja)
    }
    var carga = window.PP_MAPLIBRE = new Promise(function (ok, mal) {
      var s = document.createElement('script')
      s.src = MAPLIBRE.js
      s.integrity = MAPLIBRE.jsSri
      s.crossOrigin = 'anonymous'
      s.async = true
      s.onload = function () { window.maplibregl ? ok(window.maplibregl) : mal(new Error('MapLibre cargó pero no quedó disponible')) }
      s.onerror = function () { mal(new Error('No se pudo cargar MapLibre')) }
      document.head.appendChild(s)
    })
    carga.catch(function () { window.PP_MAPLIBRE = null })
    return carga
  }

  function cargarEstilo () {
    return fetch(ESTILO_MAPA).then(function (r) {
      if (!r.ok) throw new Error('Estilo HTTP ' + r.status)
      return r.json()
    }).then(tematizarMapa)
  }

  function tematizarMapa (estilo) {
    var P = PALETA_MAPA
    estilo.layers = estilo.layers.filter(function (l) {
      return l.type !== 'raster' && l.type !== 'hillshade' && !/shield/.test(l.id)
    })
    estilo.layers.forEach(function (l) {
      var id = l.id
      var p = l.paint = l.paint || {}
      if (l.type === 'background') {
        p['background-color'] = P.fondo
      } else if (l.type === 'fill') {
        p['fill-color'] = /water/.test(id) ? P.agua
          : /building/.test(id) ? P.edificio
            : /park|wood|grass|landcover/.test(id) ? P.verde
              : /pier|aeroway/.test(id) ? P.fondo
                : P.manzana
        if (/building/.test(id)) p['fill-outline-color'] = P.edificioBorde
      } else if (l.type === 'line') {
        p['line-color'] = /water/.test(id) ? P.agua
          : /boundary/.test(id) ? P.limite
            : /casing/.test(id) ? P.borde
              : /dashline|pier/.test(id) ? P.fondo
                : /motorway/.test(id) ? P.autopista
                  : /major/.test(id) ? P.avenida
                    : P.calle
      } else if (l.type === 'symbol') {
        var agua = /water/.test(id)
        p['text-color'] = agua ? P.textoAgua : P.texto
        p['text-halo-color'] = agua ? P.agua : P.halo
        p['text-halo-width'] = 1.2
        p['text-halo-blur'] = 0
      }
    })
    return estilo
  }

  function marcador (l) {
    var b = document.createElement('button')
    var n = l.obras.length
    b.type = 'button'
    b.setAttribute('data-lugar', l.id)
    b.setAttribute('aria-haspopup', 'dialog')
    if (n > 1) {
      b.className = 'pp-punto pp-punto--grupo'
      b.setAttribute('aria-label', n + ' obras en ' + (l.obras[0].d || 'este lugar') + '. Ver listado')
      b.innerHTML = '<span class="pp-punto__n">' + n + '</span>'
    } else {
      var o = l.obras[0]
      b.className = 'pp-punto'
      b.setAttribute('aria-label', o.n + '. ' + TIPOS[o.t] + '. Ver datos')
      b.innerHTML = '<span class="pp-muestra"></span>'
    }
    return b
  }

  function cabecera (tipoHtml, titulo) {
    return '<div class="pp-modal__cabecera"><div>' + tipoHtml +
      '<h2 class="pp-modal__titulo" id="pp-modal-titulo">' + esc(titulo) + '</h2></div>' +
      '<button type="button" class="pp-modal__cerrar" data-cerrar aria-label="Cerrar">' + CRUZ + '</button></div>'
  }

  function comoLlegar (l) {
    return '<a class="pp-btn pp-btn--linea" href="https://www.google.com/maps/dir/?api=1&amp;destination=' +
      l.lat + ',' + l.lng + '" target="_blank" rel="noopener">Cómo llegar</a>'
  }

  function subirEncuadre (pos) {
    var p = pos.split(' ')
    return p[0] + ' ' + Math.max(0, parseFloat(p[1]) - 18) + '%'
  }

  function contenidoLugar (l) {
    var h = '<div class="pp-modal__cuerpo">'
    if (l.obras.length > 1) {
      h += cabecera('<p class="pp-modal__tipo">' + l.obras.length + ' obras en este lugar</p>', l.obras[0].d || 'Mismo lugar') +
        '<div class="pp-modal__contenido"><ul class="pp-modal__lista">'
      l.obras.forEach(function (o) {
        var mini = o.m || o.f
        h += '<li><a href="' + esc(o.u) + '">' +
          (mini ? '<img class="pp-modal__mini" src="' + esc(ORIGEN + mini) + '" alt="" width="56" height="56" loading="lazy"' +
            (o.o ? ' style="object-position: ' + esc(o.o) + '"' : '') + '>' : '<span class="pp-muestra"></span>') +
          '<span><span class="pp-sr">' + TIPOS[o.t] + ': </span>' + esc(o.n) + '</span></a></li>'
      })
      return h + '</ul></div><div class="pp-modal__pie">' + comoLlegar(l) + '</div></div>'
    }
    var o = l.obras[0]
    h += cabecera('<p class="pp-modal__tipo"><span class="pp-muestra"></span>' + TIPOS[o.t] + '</p>', o.n)
    if (o.f) {
      h += '<img class="pp-modal__foto" src="' + esc(ORIGEN + o.f) + '" alt="" width="768" height="480"' +
        (o.o ? ' style="object-position: ' + esc(subirEncuadre(o.o)) + '"' : '') + '>'
    }
    if (o.d || o.p) {
      h += '<div class="pp-modal__contenido"><dl class="pp-modal__datos">'
      if (o.d) h += '<div><dt>Dirección</dt><dd>' + esc(o.d) + '</dd></div>'
      if (o.p) h += '<div><dt>Protección</dt><dd>' + esc(o.p) + ' histórico</dd></div>'
      h += '</dl></div>'
    }
    return h + '<div class="pp-modal__pie"><a class="pp-btn pp-btn--primario" href="' + esc(o.u) + '">' +
      '<i class="pp-barra"></i>Ver la ficha</a>' + comoLlegar(l) + '</div></div>'
  }

  var ultimoFoco = null
  function abrirLugar (l, disparador) {
    ultimoFoco = disparador
    modal.innerHTML = contenidoLugar(l)
    if (!modal.open) modal.showModal()
    var primero = modal.querySelector('.pp-modal__pie a, .pp-modal__lista a')
    if (primero) primero.focus()
  }
  modal.addEventListener('click', function (ev) {
    if (ev.target === modal || ev.target.closest('[data-cerrar]')) modal.close()
  })
  modal.addEventListener('close', function () {
    if (modal.open) return
    modal.innerHTML = ''
    if (ultimoFoco && document.contains(ultimoFoco)) ultimoFoco.focus()
    ultimoFoco = null
  })

  function pieMapa () {
    var cuenta = { ar: 0, aq: 0 }
    PUNTOS.forEach(function (p) { cuenta[p.t]++ })
    return '<div class="pp-mapa__pie"><div class="pp-mapa__filtros" role="group" aria-label="Mostrar en el mapa">' +
      ['ar', 'aq'].map(function (t) {
        return '<button type="button" class="pp-filtro" data-pp-filtro="' + t + '" aria-pressed="true">' +
          '<span class="pp-muestra"></span>' + (t === 'ar' ? 'Artístico' : 'Arquitectónico') +
          ' <span class="pp-filtro__n">' + cuenta[t] + '</span></button>'
      }).join('') +
      '</div></div>'
  }

  function iniciarMapa (caja) {
    caja.innerHTML = '<div class="pp-mapa__lienzo" data-pp-lienzo></div>' + pieMapa()
    var lienzo = caja.querySelector('[data-pp-lienzo]')
    var activos = { ar: true, aq: true }
    var botones = []

    lienzo.addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-lugar]')
      if (b) abrirLugar(LUGARES[b.getAttribute('data-lugar')], b)
    })

    caja.querySelector('.pp-mapa__filtros').addEventListener('click', function (ev) {
      var f = ev.target.closest('[data-pp-filtro]')
      if (!f) return
      var t = f.getAttribute('data-pp-filtro')
      activos[t] = !activos[t]
      f.setAttribute('aria-pressed', String(activos[t]))
      botones.forEach(function (b) {
        b.hidden = !LUGARES[b.getAttribute('data-lugar')].tipos.some(function (x) { return activos[x] })
      })
    })

    function sinMapa (err) {
      lienzo.innerHTML = '<div class="pp-mapa__aviso"><p>No pudimos cargar el mapa.</p>' +
        '<p><a href="' + VISOR + '" target="_blank" rel="noopener">Abrilo en Google Maps</a></p></div>'
      if (window.console) console.error('[Patrimonio]', err)
    }

    function montar () {
      Promise.all([cargarMapLibre(), cargarEstilo()]).then(function (r) {
        var ml = r[0]
        var limites = new ml.LngLatBounds()
        LUGARES.forEach(function (l) { limites.extend([l.lng, l.lat]) })
        var quieto = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches
        var mapa = new ml.Map({
          container: lienzo,
          style: r[1],
          bounds: limites,
          fitBoundsOptions: { padding: 36, maxZoom: 15 },
          cooperativeGestures: true,
          dragRotate: false,
          pitchWithRotate: false,
          touchPitch: false,
          fadeDuration: quieto ? 0 : 300,
          attributionControl: { compact: true },
          locale: TEXTOS_MAPA
        })
        mapa.touchZoomRotate.disableRotation()
        mapa.keyboard.disableRotation()
        mapa.addControl(new ml.NavigationControl({ showCompass: false }), 'top-right')
        mapa.once('idle', function () {
          var c = lienzo.querySelector('.maplibregl-ctrl-attrib.maplibregl-compact')
          if (c) c.classList.remove('maplibregl-compact-show')
        })
        LUGARES.forEach(function (l) {
          var b = marcador(l)
          botones.push(b)
          new ml.Marker({ element: b, anchor: 'center' }).setLngLat([l.lng, l.lat]).addTo(mapa)
        })
      }).catch(sinMapa)
    }

    if (!('IntersectionObserver' in window)) return montar()
    var vigia = new IntersectionObserver(function (e) {
      if (!e.some(function (x) { return x.isIntersecting })) return
      vigia.disconnect()
      montar()
    }, { rootMargin: '300px 0px' })
    vigia.observe(lienzo)
  }

  raiz.querySelectorAll('[data-pp-mapa]').forEach(iniciarMapa)
})()
</script>
