  #pq {
    --azul: #002751;
    --rojo: #e63312;
    --gris-20: #dadad9;
    --gris-75: #606060;
    --inclinacion: -15deg;
    --curva: cubic-bezier(.16, 1, .3, 1);
    color: var(--azul);
    font: 400 16px/1.6 "Encode Sans", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    -webkit-font-smoothing: antialiased;
    max-width: 1120px; margin-inline: auto;
    padding: clamp(32px, 5vw, 64px) clamp(16px, 4vw, 32px) 50px;
  }
  #pq *, #pq *::before, #pq *::after { box-sizing: border-box; }
  #pq :is(h2, p, ul) { margin: 0; padding: 0; }
  #pq ul { list-style: none; }

  #pq .pq-grupo + .pq-grupo { margin-top: clamp(40px, 6vw, 72px); }
  #pq .pq-titulo {
    display: flex; align-items: baseline; flex-wrap: wrap; gap: 0 .6rem;
    margin-bottom: clamp(18px, 3vw, 28px);
    color: inherit; font-family: inherit; text-transform: none;
    font-size: clamp(1.4rem, 2.6vw, 1.9rem); font-weight: 700; line-height: 1.15; letter-spacing: -.01em;
  }
  #pq .pq-titulo::before {
    content: ""; flex: none; align-self: center;
    width: .2em; height: .78em; margin-right: .2em;
    background: var(--rojo); transform: skewX(var(--inclinacion));
  }
  #pq .pq-titulo small { font-size: .95rem; font-weight: 600; color: var(--gris-75); letter-spacing: 0; }

  #pq .pq-grilla {
    display: grid; gap: clamp(14px, 2vw, 22px);
    grid-template-columns: repeat(auto-fill, minmax(min(100%, 220px), 1fr));
  }

  #pq .pq-card {
    position: relative; isolation: isolate;
    display: flex; flex-direction: column; height: 100%;
    overflow: hidden; border-radius: 18px;
    background: linear-gradient(160deg, rgba(255, 255, 255, .78), rgba(255, 255, 255, .56));
    -webkit-backdrop-filter: blur(16px) saturate(160%);
            backdrop-filter: blur(16px) saturate(160%);
    box-shadow:
      0 1px 1px rgba(0, 39, 81, .04),
      0 14px 30px -16px rgba(0, 39, 81, .3),
      inset 0 1px 0 rgba(255, 255, 255, .9);
    color: var(--azul); text-decoration: none;
    transition: transform .3s var(--curva), box-shadow .3s var(--curva);
  }
  #pq .pq-card:hover { color: var(--azul); }
  #pq .pq-card img {
    display: block; width: 100%; height: auto; max-width: none; aspect-ratio: 1;
    object-fit: cover; border-radius: 0; background: var(--gris-20);
  }
  #pq .pq-card__cuerpo { display: grid; gap: .3rem; padding: .85rem 1rem 1.05rem; }
  #pq .pq-card__titulo { font-size: 1.02rem; font-weight: 700; line-height: 1.25; }
  #pq .pq-card__lugar { font-size: .88rem; line-height: 1.35; color: var(--gris-75); }
  @media (hover: hover) {
    #pq .pq-card:hover {
      transform: translateY(-3px);
      box-shadow: 0 1px 1px rgba(0, 39, 81, .04), 0 22px 40px -18px rgba(0, 39, 81, .4), inset 0 1px 0 rgba(255, 255, 255, .9);
    }
  }
  #pq .pq-card:focus-visible { outline: 0; box-shadow: 0 0 0 2px #fff, 0 0 0 5px var(--rojo); }

  @media (max-width: 640px) {
    #pq .pq-grilla { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    #pq .pq-card { border-radius: 14px; }
    #pq .pq-card__cuerpo { padding: .7rem .75rem .85rem; }
    #pq .pq-card__titulo { font-size: .92rem; }
    #pq .pq-card__lugar { font-size: .8rem; }
  }

  @supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    #pq .pq-card { background: rgba(255, 255, 255, .95); }
  }
  @media (prefers-reduced-transparency: reduce) {
    #pq .pq-card { background: #fff; -webkit-backdrop-filter: none; backdrop-filter: none; }
  }
  @media (prefers-reduced-motion: reduce) {
    #pq *, #pq *::before, #pq *::after { transition: none !important; }
  }
</style>

