  #pq ul { list-style: none; }

  #pq .pq-grupo + .pq-grupo { margin-top: clamp(40px, 6vw, 72px); }
  #pq .pq-titulo {
    display: flex; align-items: baseline; flex-wrap: wrap; gap: 0 .6rem;
    margin-bottom: clamp(18px, 3vw, 28px);
