  }
  #pq .pq-card:focus-visible { outline: 0; box-shadow: 0 0 0 2px #fff, 0 0 0 5px var(--rojo); }

  @media (max-width: 640px) {
    #pq .pq-grilla { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    #pq .pq-card { border-radius: 14px; }
