[{"id":"c011789","elType":"section","settings":[],"elements":[{"id":"e98af92","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"61e49ae","elType":"widget","settings":{"html":"<style>
  .elementor-widget-wrap:has(> .elementor-widget-html #pf),
  .elementor-widget-html:has(#pf) > .elementor-widget-container { padding: 0; margin: 0; }
  .ast-container > .elementor:has(#pf) { flex: 1 1 100%; min-width: 0; }

  #pf {
    --azul: #002751; --celeste: #00aaff; --rojo: #e63312;
    --gris-20: #dadad9; --gris-75: #606060;
    --inclinacion: -15deg; --curva: cubic-bezier(.16, 1, .3, 1);
    max-width: 1120px; margin-inline: auto;
    padding: clamp(28px, 5vw, 56px) clamp(16px, 4vw, 32px) 50px;
    color: var(--azul);
    font: 400 16px/1.65 "Encode Sans", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    -webkit-font-smoothing: antialiased;
  }
  #pf *, #pf *::before, #pf *::after { box-sizing: border-box; }
  #pf :is(h2, p, ul, figure) { margin: 0; padding: 0; }
  #pf ul { list-style: none; }
  #pf img { display: block; max-width: 100%; height: auto; border-radius: 0; }
  #pf .pf-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  #pf :is(a, button):focus-visible { outline: 0; box-shadow: 0 0 0 2px #fff, 0 0 0 5px var(--rojo); }

  #pf .pf-barra {
    display: inline-block; flex: none; width: .2em; height: .78em;
    background: var(--rojo); transform: skewX(var(--inclinacion));
  }

  #pf .pf-cabecera {
    display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: clamp(24px, 4vw, 56px); align-items: start;
  }
  #pf .pf-texto { display: grid; gap: 1rem; }
  #pf .pf-ceja, #pf .pf-ceja:hover {
    justify-self: start;
    font-size: .8rem; font-weight: 600; letter-spacing: .09em; text-transform: uppercase;
    color: var(--gris-75); text-decoration: none;
  }
  #pf .pf-ceja:hover { text-decoration: underline; text-decoration-color: var(--rojo); text-underline-offset: 4px; }
  #pf .pf-lugar { display: flex; align-items: center; gap: .45rem; font-weight: 600; }
  #pf .pf-lugar svg { flex: none; width: 18px; height: 18px; color: var(--rojo); }
  #pf .pf-proteccion {
    justify-self: start; padding: .3rem .7rem; border-radius: 999px;
    background: rgba(0, 39, 81, .07); color: var(--azul);
    font-size: .78rem; font-weight: 600; letter-spacing: .06em; text-transform: uppercase;
  }
  #pf .pf-cuerpo { display: grid; gap: .9rem; font-size: 1.05rem; }
  #pf .pf-cuerpo a { color: var(--azul); text-decoration-color: var(--rojo); text-underline-offset: 3px; }

  #pf .pf-acciones { display: flex; flex-wrap: wrap; gap: .6rem; margin-top: .4rem; }
  #pf .pf-btn, #pf .pf-btn:hover, #pf .pf-btn:focus {
    position: relative; overflow: hidden;
    display: inline-flex; align-items: center; gap: .6em;
    min-height: 44px; padding: 0 18px; border: 0; border-radius: 10px;
    background: var(--azul); color: #fff;
    font-family: inherit; font-size: 15px; font-weight: 600; line-height: 1; text-decoration: none;
  }
  #pf .pf-btn::after {
    content: ""; position: absolute; top: 0; left: -75%; width: 38%; height: 100%;
    background: linear-gradient(105deg, transparent, rgba(255, 255, 255, .3), transparent);
    transform: skewX(var(--inclinacion)); transition: left .6s var(--curva); pointer-events: none;
  }
  @media (hover: hover) { #pf .pf-btn:hover::after { left: 135%; } }
  #pf .pf-btn .pf-barra { height: 1.05em; }
  #pf .pf-btn__tipo {
    padding: .25em .45em; border-radius: 5px; background: rgba(255, 255, 255, .16);
    font-size: .72rem; letter-spacing: .06em;
  }

  #pf .pf-principal { overflow: hidden; border-radius: 22px; background: var(--gris-20);
    box-shadow: 0 1px 1px rgba(0, 39, 81, .04), 0 18px 40px -20px rgba(0, 39, 81, .45); }
  #pf .pf-principal a { display: block; }
  #pf .pf-principal img { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; }

  #pf .pf-galeria { margin-top: clamp(36px, 6vw, 64px); }
  #pf .pf-galeria__titulo {
    display: flex; align-items: baseline; flex-wrap: wrap; gap: 0 .6rem; margin-bottom: clamp(16px, 2.5vw, 24px);
    color: inherit; font-family: inherit; text-transform: none;
    font-size: clamp(1.3rem, 2.4vw, 1.7rem); font-weight: 700; line-height: 1.15; letter-spacing: -.01em;
  }
  #pf .pf-galeria__titulo small { font-size: .95rem; font-weight: 600; color: var(--gris-75); letter-spacing: 0; }
  #pf .pf-grilla { display: grid; gap: clamp(14px, 2vw, 22px); grid-template-columns: repeat(auto-fill, minmax(min(100%, 220px), 1fr)); }
  #pf .pf-grilla figure {
    height: 100%; overflow: hidden; border-radius: 16px;
    background: linear-gradient(160deg, rgba(255, 255, 255, .78), rgba(255, 255, 255, .56));
    -webkit-backdrop-filter: blur(16px) saturate(160%); backdrop-filter: blur(16px) saturate(160%);
    box-shadow: 0 1px 1px rgba(0, 39, 81, .04), 0 14px 30px -16px rgba(0, 39, 81, .3), inset 0 1px 0 rgba(255, 255, 255, .9);
    transition: transform .3s var(--curva), box-shadow .3s var(--curva);
  }
  #pf .pf-grilla a { display: block; }
  #pf .pf-grilla img { width: 100%; aspect-ratio: 1; object-fit: cover; background: var(--gris-20); }
  #pf .pf-grilla figcaption { padding: .65rem .85rem .8rem; font-size: .84rem; line-height: 1.4; color: var(--gris-75); }
  @media (hover: hover) {
    #pf .pf-grilla figure:hover { transform: translateY(-3px); box-shadow: 0 1px 1px rgba(0, 39, 81, .04), 0 22px 40px -18px rgba(0, 39, 81, .4), inset 0 1px 0 rgba(255, 255, 255, .9); }
  }

  #pf .pf-visor {
    width: 100vw; max-width: 100vw; height: 100dvh; max-height: 100dvh; margin: 0; padding: 0; border: 0;
    background: transparent; color: #fff; overflow: hidden;
  }
  #pf .pf-visor::backdrop { background: rgba(0, 18, 38, .9); }
  #pf .pf-visor[open] { display: grid; place-items: center; }
  #pf .pf-visor__figura { display: grid; justify-items: center; gap: .75rem; max-width: min(1100px, 100vw - 120px); }
  #pf .pf-visor__figura img { max-width: 100%; max-height: calc(100dvh - 140px); width: auto; height: auto; border-radius: 8px; }
  #pf .pf-visor__figura figcaption { max-width: 70ch; text-align: center; font-size: .92rem; color: #dbe3ee; }
