      <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/26-PUENTE.jpg" data-pf-foto data-pf-epigrafe="Puente colgante “Ing. Marcial Candioti”"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/26-PUENTE-768x570.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/26-PUENTE-768x570.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/26-PUENTE.jpg 867w" sizes="(max-width: 860px) 100vw, 540px" alt="Puente colgante “Ing. Marcial Candioti”" width="768" height="570" fetchpriority="high"></a>
