{"timeout":1792676632,"value":{"content":"		<section class="elementor-section elementor-top-section elementor-element elementor-element-2c3f30d elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="2c3f30d" data-element_type="section" data-e-type="section">
						<div class="elementor-container elementor-column-gap-default">
					<div class="elementor-column elementor-col-100 elementor-top-column elementor-element elementor-element-2b2e385" data-id="2b2e385" data-element_type="column" data-e-type="column">
			<div class="elementor-widget-wrap elementor-element-populated">
						<div class="elementor-element elementor-element-2100e2e elementor-widget elementor-widget-html" data-id="2100e2e" data-element_type="widget" data-e-type="widget" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<style>
  /* El widget no suma márgenes propios */
  .elementor-widget-wrap:has(> .elementor-widget-html #pa),
  .elementor-widget-html:has(#pa) > .elementor-widget-container { padding: 0; margin: 0; }
  /* La plantilla de Redux pone el contenido en un .ast-container flex: sin esto, la
     página se encoge al ancho de su contenido en lugar de ocupar el contenedor */
  .ast-container > .elementor:has(#pa) { flex: 1 1 100%; min-width: 0; }

  #pa {
    --azul: #002751;
    --rojo: #e63312;
    --gris-20: #dadad9;
    --gris-75: #606060;
    --inclinacion: -15deg;
    --curva: cubic-bezier(.16, 1, .3, 1);
    color: var(--azul);
    font: 400 16px/1.6 "Encode Sans", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    -webkit-font-smoothing: antialiased;
    max-width: 1120px; margin-inline: auto;
    padding: clamp(32px, 5vw, 64px) clamp(16px, 4vw, 32px) 50px;
  }
  #pa *, #pa *::before, #pa *::after { box-sizing: border-box; }
  #pa :is(h2, p, ul) { margin: 0; padding: 0; }
  #pa ul { list-style: none; }

  #pa .pa-grupo + .pa-grupo { margin-top: clamp(40px, 6vw, 72px); }
  #pa .pa-titulo {
    display: flex; align-items: baseline; flex-wrap: wrap; gap: 0 .6rem;
    margin-bottom: clamp(18px, 3vw, 28px);
    color: inherit; font-family: inherit; text-transform: none;
    font-size: clamp(1.4rem, 2.6vw, 1.9rem); font-weight: 700; line-height: 1.15; letter-spacing: -.01em;
  }
  #pa .pa-titulo::before {
    content: ""; flex: none; align-self: center;
    width: .2em; height: .78em; margin-right: .2em; /* + el gap: aire entre la barra y el texto */
    background: var(--rojo); transform: skewX(var(--inclinacion));
  }
  #pa .pa-titulo small { font-size: .95rem; font-weight: 600; color: var(--gris-75); letter-spacing: 0; }

  #pa .pa-grilla {
    display: grid; gap: clamp(14px, 2vw, 22px);
    grid-template-columns: repeat(auto-fill, minmax(min(100%, 220px), 1fr));
  }

  /* ───── Tarjeta: toda es el enlace a la ficha ───── */
  #pa .pa-card {
    position: relative; isolation: isolate;
    display: flex; flex-direction: column; height: 100%;
    overflow: hidden; border-radius: 18px;
    background: linear-gradient(160deg, rgba(255, 255, 255, .78), rgba(255, 255, 255, .56));
    -webkit-backdrop-filter: blur(16px) saturate(160%);
            backdrop-filter: blur(16px) saturate(160%);
    box-shadow:
      0 1px 1px rgba(0, 39, 81, .04),
      0 14px 30px -16px rgba(0, 39, 81, .3),
      inset 0 1px 0 rgba(255, 255, 255, .9);
    color: var(--azul); text-decoration: none;
    transition: transform .3s var(--curva), box-shadow .3s var(--curva);
  }
  #pa .pa-card:hover { color: var(--azul); }
  #pa .pa-card img {
    display: block; width: 100%; height: auto; max-width: none; aspect-ratio: 1;
    object-fit: cover; border-radius: 0; background: var(--gris-20);
  }
  #pa .pa-card__cuerpo { display: grid; gap: .3rem; padding: .85rem 1rem 1.05rem; }
  #pa .pa-card__titulo { font-size: 1.02rem; font-weight: 700; line-height: 1.25; }
  #pa .pa-card__lugar { font-size: .88rem; line-height: 1.35; color: var(--gris-75); }
  @media (hover: hover) {
    #pa .pa-card:hover {
      transform: translateY(-3px);
      box-shadow: 0 1px 1px rgba(0, 39, 81, .04), 0 22px 40px -18px rgba(0, 39, 81, .4), inset 0 1px 0 rgba(255, 255, 255, .9);
    }
  }
  /* Foco: anillo rojo sobre halo blanco */
  #pa .pa-card:focus-visible { outline: 0; box-shadow: 0 0 0 2px #fff, 0 0 0 5px var(--rojo); }

  /* ───── Mobile: dos columnas ───── */
  @media (max-width: 640px) {
    #pa .pa-grilla { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    #pa .pa-card { border-radius: 14px; }
    #pa .pa-card__cuerpo { padding: .7rem .75rem .85rem; }
    #pa .pa-card__titulo { font-size: .92rem; }
    #pa .pa-card__lugar { font-size: .8rem; }
  }

  /* ───── Accesibilidad ───── */
  @supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    #pa .pa-card { background: rgba(255, 255, 255, .95); }
  }
