<div id="pf">
  <div class="pf-cabecera">
    <div class="pf-texto">
      <a class="pf-ceja" href="/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/">Patrimonio Artístico</a>
      <p class="pf-lugar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 21s-7-6.1-7-11.5A7 7 0 0 1 19 9.5C19 14.9 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/></svg><span>Plaza Colón</span></p>
      <div class="pf-cuerpo">
        <p>Ésta obra tallada en piedra fue realizada en 1941 por el reconocido escultor José Sedlacek (<em>1900-1981</em>), se pueden encontrar obras del autor que están fuertemente relacionadas con la historia de la ciudad. Este monumento en particular fue adquirido y emplazado durante la intendencia de Francisco Bobbio sin la autorización de la Cámara de Diputados generando así un conflicto entre las instituciones. Representa a la figura de Cristóbal Colón quien fue un navegante, virrey y gobernador al servicio de la Corona de Castilla, conocido por sus expediciones por América, llegando por primera vez a la isla Guanahani, en las Bahamas, el 12 de octubre de 1492.</p>
      </div>
    </div>
    <figure class="pf-principal">
      <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/colon.jpg" data-pf-foto data-pf-epigrafe="Monumento a Cristóbal Colón"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/colon.jpg" sizes="(max-width: 860px) 100vw, 540px" alt="Monumento a Cristóbal Colón" width="600" height="600" fetchpriority="high"></a>
    </figure>
  </div>

  <section class="pf-galeria" aria-labelledby="pf-galeria-titulo">
    <h2 class="pf-galeria__titulo" id="pf-galeria-titulo">Galería <small>3 imágenes</small></h2>
    <ul class="pf-grilla">
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-MMAV-Cortesia-de-A.-Sedlacek-artista-y-taller-1941.jpg" data-pf-foto data-pf-epigrafe="Archivo MMAV · Cortesía de A. Sedlacek · artista y taller · 1941"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-MMAV-Cortesia-de-A.-Sedlacek-artista-y-taller-1941.jpg" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo MMAV · Cortesía de A. Sedlacek · artista y taller · 1941" width="7620" height="11961" loading="lazy"></a>
        <figcaption>Archivo MMAV · Cortesía de A. Sedlacek · artista y taller · 1941</figcaption>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-hemeroteca-digital-prov.-Diario-El-Litoral-1941.jpg" data-pf-foto data-pf-epigrafe="Archivo hemeroteca digital prov. · Diario El Litoral · 1941"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-hemeroteca-digital-prov.-Diario-El-Litoral-1941.jpg" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo hemeroteca digital prov. · Diario El Litoral · 1941" width="613" height="1756" loading="lazy"></a>
        <figcaption>Archivo hemeroteca digital prov. · Diario El Litoral · 1941</figcaption>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-MMAV-Cortesia-de-A.-Sedlacek-artista-y-obra-1941-aprox..jpg" data-pf-foto data-pf-epigrafe="Archivo MMAV · Cortesía de A. Sedlacek · artista y obra · 1941 aprox"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-MMAV-Cortesia-de-A.-Sedlacek-artista-y-obra-1941-aprox.-768x1207.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-MMAV-Cortesia-de-A.-Sedlacek-artista-y-obra-1941-aprox.-768x1207.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-MMAV-Cortesia-de-A.-Sedlacek-artista-y-obra-1941-aprox..jpg 1040w" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo MMAV · Cortesía de A. Sedlacek · artista y obra · 1941 aprox" width="768" height="1207" loading="lazy"></a>
        <figcaption>Archivo MMAV · Cortesía de A. Sedlacek · artista y obra · 1941 aprox</figcaption>
      </figure></li>
    </ul>
  </section>

  <dialog class="pf-visor" aria-label="Imagen ampliada">
    <button type="button" class="pf-visor__cerrar" data-pf-cerrar aria-label="Cerrar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
    <button type="button" class="pf-visor__nav pf-visor__nav--prev" data-pf-prev aria-label="Imagen anterior"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 12H5M11 6l-6 6 6 6"/></svg></button>
    <figure class="pf-visor__figura"><img alt=""><figcaption></figcaption></figure>
    <button type="button" class="pf-visor__nav pf-visor__nav--next" data-pf-next aria-label="Imagen siguiente"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button>
    <p class="pf-visor__cuenta" aria-live="polite"></p>
  </dialog>
</div>

<script>
(function () {
  'use strict'
  var raiz = document.getElementById('pf')
  var visor = raiz && raiz.querySelector('.pf-visor')
  if (!visor || !visor.showModal || raiz.dataset.pfInit) return
  raiz.dataset.pfInit = '1'

  var fotos = Array.prototype.slice.call(raiz.querySelectorAll('[data-pf-foto]'))
  var img = visor.querySelector('img')
  var epigrafe = visor.querySelector('figcaption')
  var cuenta = visor.querySelector('.pf-visor__cuenta')
  var prev = visor.querySelector('[data-pf-prev]')
  var next = visor.querySelector('[data-pf-next]')
  var actual = 0
  var origen = null

  function mostrar (i) {
    actual = (i + fotos.length) % fotos.length
    var a = fotos[actual]
    var miniatura = a.querySelector('img')
    img.src = a.href
    img.alt = miniatura ? miniatura.alt : ''
    epigrafe.textContent = a.getAttribute('data-pf-epigrafe') || ''
    cuenta.textContent = (actual + 1) + ' de ' + fotos.length
  }

  prev.hidden = next.hidden = fotos.length < 2

  fotos.forEach(function (a, i) {
    a.addEventListener('click', function (ev) {
      if (ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.button !== 0) return
      ev.preventDefault()
      origen = a
      mostrar(i)
      visor.showModal()
    })
  })

  prev.addEventListener('click', function () { mostrar(actual - 1) })
  next.addEventListener('click', function () { mostrar(actual + 1) })
  visor.addEventListener('click', function (ev) {
    if (ev.target === visor || ev.target.closest('[data-pf-cerrar]')) visor.close()
  })
  visor.addEventListener('keydown', function (ev) {
    if (ev.key === 'ArrowLeft' && fotos.length > 1) mostrar(actual - 1)
    if (ev.key === 'ArrowRight' && fotos.length > 1) mostrar(actual + 1)
  })
  visor.addEventListener('close', function () {
    img.removeAttribute('src')
    if (origen) origen.focus()
  })
})()
</script>
