<div id="pf">
  <div class="pf-cabecera">
    <div class="pf-texto">
      <a class="pf-ceja" href="/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/">Patrimonio Artístico</a>
      <p class="pf-lugar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 21s-7-6.1-7-11.5A7 7 0 0 1 19 9.5C19 14.9 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/></svg><span>Av. Siete Jefes 3601</span></p>
      <div class="pf-cuerpo">
        <p>Esta escultura ecuestre de bronce representa al Brigadier General Estanislao López (1786-1838) caudillo, militar y gobernador de Santa Fe, fuertemente relacionado con la idea del federalismo. El monumento realizado por Oliva-Navarro (1888-1951) e inaugurado en 1942, se compone de una figura con su brazo derecho extendido en una actitud serena pero dominante y paneles en relieve que muestran aspectos de la acción gubernamental del caudillo, en la guerra y la paz, se recuerda las montoneras y sus gauchos, el trabajo simbolizado por una yunta de bueyes, la presencia aborigen y la educación a través de una mujer y un grupo de alumnos. Se pueden encontrar otras obras del artista en el cementerio municipal.</p>
      </div>
    </div>
    <figure class="pf-principal">
      <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/brigadier.jpg" data-pf-foto data-pf-epigrafe="Monumento a Estanislao López"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/brigadier.jpg" sizes="(max-width: 860px) 100vw, 540px" alt="Monumento a Estanislao López" width="600" height="600" fetchpriority="high"></a>
    </figure>
  </div>

  <section class="pf-galeria" aria-labelledby="pf-galeria-titulo">
    <h2 class="pf-galeria__titulo" id="pf-galeria-titulo">Galería <small>3 imágenes</small></h2>
    <ul class="pf-grilla">
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-hemeroteca-digital-prov.-Diario-El-Litoral-monumento-al-Brigadier-1942.jpg" data-pf-foto data-pf-epigrafe="Archivo hemeroteca digital prov. · Diario El Litoral · monumento al Brigadier · 1942"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-hemeroteca-digital-prov.-Diario-El-Litoral-monumento-al-Brigadier-1942-768x1563.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-hemeroteca-digital-prov.-Diario-El-Litoral-monumento-al-Brigadier-1942-768x1563.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-hemeroteca-digital-prov.-Diario-El-Litoral-monumento-al-Brigadier-1942.jpg 788w" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo hemeroteca digital prov. · Diario El Litoral · monumento al Brigadier · 1942" width="768" height="1563" loading="lazy"></a>
        <figcaption>Archivo hemeroteca digital prov. · Diario El Litoral · monumento al Brigadier · 1942</figcaption>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-Museo-de-la-Ciudad-SF-fotografia-del-busto-de-la-escultura-al-Brigadier-1932-scaled.jpg" data-pf-foto data-pf-epigrafe="Archivo Museo de la Ciudad SF · fotografía del busto de la escultura al Brigadier · 1932"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-Museo-de-la-Ciudad-SF-fotografia-del-busto-de-la-escultura-al-Brigadier-1932-768x1088.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-Museo-de-la-Ciudad-SF-fotografia-del-busto-de-la-escultura-al-Brigadier-1932-768x1088.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-Museo-de-la-Ciudad-SF-fotografia-del-busto-de-la-escultura-al-Brigadier-1932-scaled.jpg 1806w" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo Museo de la Ciudad SF · fotografía del busto de la escultura al Brigadier · 1932" width="768" height="1088" loading="lazy"></a>
        <figcaption>Archivo Museo de la Ciudad SF · fotografía del busto de la escultura al Brigadier · 1932</figcaption>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-MMAV-boceto-del-monumento-por-el-artista-Cesar-Fernandez-Navarro.-1024x777.jpeg" data-pf-foto data-pf-epigrafe="Archivo MMAV · boceto del monumento por el artista Cesar Fernández Navarro"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-MMAV-boceto-del-monumento-por-el-artista-Cesar-Fernandez-Navarro.-768x583.jpeg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-MMAV-boceto-del-monumento-por-el-artista-Cesar-Fernandez-Navarro.-768x583.jpeg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-MMAV-boceto-del-monumento-por-el-artista-Cesar-Fernandez-Navarro.-1024x777.jpeg 1024w" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo MMAV · boceto del monumento por el artista Cesar Fernández Navarro" width="768" height="583" loading="lazy"></a>
        <figcaption>Archivo MMAV · boceto del monumento por el artista Cesar Fernández Navarro</figcaption>
      </figure></li>
    </ul>
  </section>

  <dialog class="pf-visor" aria-label="Imagen ampliada">
    <button type="button" class="pf-visor__cerrar" data-pf-cerrar aria-label="Cerrar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
    <button type="button" class="pf-visor__nav pf-visor__nav--prev" data-pf-prev aria-label="Imagen anterior"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 12H5M11 6l-6 6 6 6"/></svg></button>
    <figure class="pf-visor__figura"><img alt=""><figcaption></figcaption></figure>
    <button type="button" class="pf-visor__nav pf-visor__nav--next" data-pf-next aria-label="Imagen siguiente"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button>
    <p class="pf-visor__cuenta" aria-live="polite"></p>
  </dialog>
</div>

<script>
(function () {
  'use strict'
  var raiz = document.getElementById('pf')
  var visor = raiz && raiz.querySelector('.pf-visor')
  if (!visor || !visor.showModal || raiz.dataset.pfInit) return
  raiz.dataset.pfInit = '1'

  var fotos = Array.prototype.slice.call(raiz.querySelectorAll('[data-pf-foto]'))
  var img = visor.querySelector('img')
  var epigrafe = visor.querySelector('figcaption')
  var cuenta = visor.querySelector('.pf-visor__cuenta')
  var prev = visor.querySelector('[data-pf-prev]')
  var next = visor.querySelector('[data-pf-next]')
  var actual = 0
  var origen = null

  function mostrar (i) {
    actual = (i + fotos.length) % fotos.length
    var a = fotos[actual]
    var miniatura = a.querySelector('img')
    img.src = a.href
    img.alt = miniatura ? miniatura.alt : ''
    epigrafe.textContent = a.getAttribute('data-pf-epigrafe') || ''
    cuenta.textContent = (actual + 1) + ' de ' + fotos.length
  }

  prev.hidden = next.hidden = fotos.length < 2

  fotos.forEach(function (a, i) {
    a.addEventListener('click', function (ev) {
      if (ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.button !== 0) return
      ev.preventDefault()
      origen = a
      mostrar(i)
      visor.showModal()
    })
  })

  prev.addEventListener('click', function () { mostrar(actual - 1) })
  next.addEventListener('click', function () { mostrar(actual + 1) })
  visor.addEventListener('click', function (ev) {
    if (ev.target === visor || ev.target.closest('[data-pf-cerrar]')) visor.close()
  })
  visor.addEventListener('keydown', function (ev) {
    if (ev.key === 'ArrowLeft' && fotos.length > 1) mostrar(actual - 1)
    if (ev.key === 'ArrowRight' && fotos.length > 1) mostrar(actual + 1)
  })
  visor.addEventListener('close', function () {
    img.removeAttribute('src')
    if (origen) origen.focus()
  })
})()
</script>
				</div>
				</div>
					</div>
		</div>
					</div>
		</section>
