        <figcaption>Archivo diario El Litoral · Fuente · Parque Oroño · 1940 · 50 aprox</figcaption>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-imagen-de-catalogo-Fundidora-Val-dOsne-conjunto-escultorico.jpg" data-pf-foto data-pf-epigrafe="Imagen de catálogo · Fundidora Val d’Osne · conjunto escultórico"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-imagen-de-catalogo-Fundidora-Val-dOsne-conjunto-escultorico.jpg" sizes="(max-width: 640px) 46vw, 260px" alt="Imagen de catálogo · Fundidora Val d’Osne · conjunto escultórico" width="561" height="800" loading="lazy"></a>
        <figcaption>Imagen de catálogo · Fundidora Val d’Osne · conjunto escultórico</figcaption>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-Museo-de-la-Ciudad-SF-Fuente-en-el-rosedal-de-Guadalupe-1970.jpg" data-pf-foto data-pf-epigrafe="Archivo Museo de la Ciudad SF · Fuente en el rosedal de Guadalupe · 1970"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-Museo-de-la-Ciudad-SF-Fuente-en-el-rosedal-de-Guadalupe-1970-768x773.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-Museo-de-la-Ciudad-SF-Fuente-en-el-rosedal-de-Guadalupe-1970-768x773.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-Museo-de-la-Ciudad-SF-Fuente-en-el-rosedal-de-Guadalupe-1970.jpg 920w" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo Museo de la Ciudad SF · Fuente en el rosedal de Guadalupe · 1970" width="768" height="773" loading="lazy"></a>
        <figcaption>Archivo Museo de la Ciudad SF · Fuente en el rosedal de Guadalupe · 1970</figcaption>
