    <h2 class="pf-galeria__titulo" id="pf-galeria-titulo">Galería <small>1 imagen</small></h2>
    <ul class="pf-grilla">
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-MMAV-Pintura-Muerte-de-Don-Juan-de-Garay-obra-de-Garcia-Banon.-1024x763.jpg" data-pf-foto data-pf-epigrafe="Archivo MMAV · Pintura · Muerte de Don Juan de Garay obra de García Bañon"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-MMAV-Pintura-Muerte-de-Don-Juan-de-Garay-obra-de-Garcia-Banon.-768x573.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-MMAV-Pintura-Muerte-de-Don-Juan-de-Garay-obra-de-Garcia-Banon.-768x573.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-MMAV-Pintura-Muerte-de-Don-Juan-de-Garay-obra-de-Garcia-Banon.-1024x763.jpg 1024w" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo MMAV · Pintura · Muerte de Don Juan de Garay obra de García Bañon" width="768" height="573" loading="lazy"></a>
