<div id="pf">
  <div class="pf-cabecera">
    <div class="pf-texto">
      <a class="pf-ceja" href="/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/">Patrimonio Artístico</a>
      <p class="pf-lugar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 21s-7-6.1-7-11.5A7 7 0 0 1 19 9.5C19 14.9 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/></svg><span>Av. Blas Parera 9699</span></p>
      <div class="pf-cuerpo">
        <p>El toro de Blas Parera se convirtió en un ícono del norte de Santa Fe. El animal es una referencia ineludible para quienes transitan por la zona. Algunas de las expresiones utilizadas suelen ser “Del toro hacia adentro; antes o pasando “el toro”. El mismo fue realizado por Dassie, oriundo de la localidad de Roldan, en el año 1968 en chapa de 4 mm con la idea de hacer un tanque de agua distinto. No se sabe cómo llegó la obra a Santa Fe, pero se presume que en esa esquina funcionaba una curtiembre y por eso la instalación de este animal.</p>
      </div>
    </div>
    <figure class="pf-principal">
      <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/FOTO-DE-PORTADA-1-Fotografia-de-la-obra-El-Toro.png" data-pf-foto data-pf-epigrafe="El toro de Santia Dassie"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/FOTO-DE-PORTADA-1-Fotografia-de-la-obra-El-Toro.png" sizes="(max-width: 860px) 100vw, 540px" alt="El toro de Santia Dassie" width="610" height="391" fetchpriority="high"></a>
    </figure>
  </div>

  <section class="pf-galeria" aria-labelledby="pf-galeria-titulo">
    <h2 class="pf-galeria__titulo" id="pf-galeria-titulo">Galería <small>2 imágenes</small></h2>
    <ul class="pf-grilla">
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-Fotografia-del-autor-Santiago-Dassie-en-el-centro.jpg" data-pf-foto data-pf-epigrafe="Fotografía del autor · Santiago Dassie · en el centro"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-Fotografia-del-autor-Santiago-Dassie-en-el-centro.jpg" sizes="(max-width: 640px) 46vw, 260px" alt="Fotografía del autor · Santiago Dassie · en el centro" width="540" height="960" loading="lazy"></a>
        <figcaption>Fotografía del autor · Santiago Dassie · en el centro</figcaption>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-Imagen-digital-de-la-ubicacion-de-la-obra-El-Toro-1024x471.jpg" data-pf-foto data-pf-epigrafe="Imagen digital de la ubicación de la obra El Toro"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-Imagen-digital-de-la-ubicacion-de-la-obra-El-Toro-768x353.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-Imagen-digital-de-la-ubicacion-de-la-obra-El-Toro-768x353.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-Imagen-digital-de-la-ubicacion-de-la-obra-El-Toro-1024x471.jpg 1024w" sizes="(max-width: 640px) 46vw, 260px" alt="Imagen digital de la ubicación de la obra El Toro" width="768" height="353" loading="lazy"></a>
        <figcaption>Imagen digital de la ubicación de la obra El Toro</figcaption>
      </figure></li>
    </ul>
  </section>

  <dialog class="pf-visor" aria-label="Imagen ampliada">
    <button type="button" class="pf-visor__cerrar" data-pf-cerrar aria-label="Cerrar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
    <button type="button" class="pf-visor__nav pf-visor__nav--prev" data-pf-prev aria-label="Imagen anterior"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 12H5M11 6l-6 6 6 6"/></svg></button>
    <figure class="pf-visor__figura"><img alt=""><figcaption></figcaption></figure>
    <button type="button" class="pf-visor__nav pf-visor__nav--next" data-pf-next aria-label="Imagen siguiente"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button>
    <p class="pf-visor__cuenta" aria-live="polite"></p>
  </dialog>
</div>

<script>
(function () {
  'use strict'
  var raiz = document.getElementById('pf')
  var visor = raiz && raiz.querySelector('.pf-visor')
  if (!visor || !visor.showModal || raiz.dataset.pfInit) return
  raiz.dataset.pfInit = '1'

  var fotos = Array.prototype.slice.call(raiz.querySelectorAll('[data-pf-foto]'))
  var img = visor.querySelector('img')
  var epigrafe = visor.querySelector('figcaption')
  var cuenta = visor.querySelector('.pf-visor__cuenta')
  var prev = visor.querySelector('[data-pf-prev]')
  var next = visor.querySelector('[data-pf-next]')
  var actual = 0
  var origen = null

  function mostrar (i) {
    actual = (i + fotos.length) % fotos.length
    var a = fotos[actual]
    var miniatura = a.querySelector('img')
    img.src = a.href
    img.alt = miniatura ? miniatura.alt : ''
    epigrafe.textContent = a.getAttribute('data-pf-epigrafe') || ''
    cuenta.textContent = (actual + 1) + ' de ' + fotos.length
  }

  prev.hidden = next.hidden = fotos.length < 2

  fotos.forEach(function (a, i) {
    a.addEventListener('click', function (ev) {
      if (ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.button !== 0) return
      ev.preventDefault()
      origen = a
      mostrar(i)
      visor.showModal()
    })
  })

  prev.addEventListener('click', function () { mostrar(actual - 1) })
  next.addEventListener('click', function () { mostrar(actual + 1) })
  visor.addEventListener('click', function (ev) {
    if (ev.target === visor || ev.target.closest('[data-pf-cerrar]')) visor.close()
  })
  visor.addEventListener('keydown', function (ev) {
    if (ev.key === 'ArrowLeft' && fotos.length > 1) mostrar(actual - 1)
    if (ev.key === 'ArrowRight' && fotos.length > 1) mostrar(actual + 1)
  })
  visor.addEventListener('close', function () {
    img.removeAttribute('src')
    if (origen) origen.focus()
  })
})()
</script>
