    padding: .25em .45em; border-radius: 5px; background: rgba(255, 255, 255, .16);
    font-size: .72rem; letter-spacing: .06em;
  }

  #pf .pf-principal { overflow: hidden; border-radius: 22px; background: var(--gris-20);
    box-shadow: 0 1px 1px rgba(0, 39, 81, .04), 0 18px 40px -20px rgba(0, 39, 81, .45); }
  #pf .pf-principal a { display: block; }
  #pf .pf-principal img { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; }

  #pf .pf-galeria { margin-top: clamp(36px, 6vw, 64px); }
  #pf .pf-galeria__titulo {
    display: flex; align-items: baseline; flex-wrap: wrap; gap: 0 .6rem; margin-bottom: clamp(16px, 2.5vw, 24px);
    color: inherit; font-family: inherit; text-transform: none;
    font-size: clamp(1.3rem, 2.4vw, 1.7rem); font-weight: 700; line-height: 1.15; letter-spacing: -.01em;
  }
  #pf .pf-galeria__titulo small { font-size: .95rem; font-weight: 600; color: var(--gris-75); letter-spacing: 0; }
  #pf .pf-grilla { display: grid; gap: clamp(14px, 2vw, 22px); grid-template-columns: repeat(auto-fill, minmax(min(100%, 220px), 1fr)); }
  #pf .pf-grilla figure {
    height: 100%; overflow: hidden; border-radius: 16px;
    background: linear-gradient(160deg, rgba(255, 255, 255, .78), rgba(255, 255, 255, .56));
    -webkit-backdrop-filter: blur(16px) saturate(160%); backdrop-filter: blur(16px) saturate(160%);
    box-shadow: 0 1px 1px rgba(0, 39, 81, .04), 0 14px 30px -16px rgba(0, 39, 81, .3), inset 0 1px 0 rgba(255, 255, 255, .9);
    transition: transform .3s var(--curva), box-shadow .3s var(--curva);
  }
  #pf .pf-grilla a { display: block; }
  #pf .pf-grilla img { width: 100%; aspect-ratio: 1; object-fit: cover; background: var(--gris-20); }
  #pf .pf-grilla figcaption { padding: .65rem .85rem .8rem; font-size: .84rem; line-height: 1.4; color: var(--gris-75); }
  @media (hover: hover) {
    #pf .pf-grilla figure:hover { transform: translateY(-3px); box-shadow: 0 1px 1px rgba(0, 39, 81, .04), 0 22px 40px -18px rgba(0, 39, 81, .4), inset 0 1px 0 rgba(255, 255, 255, .9); }
  }

  #pf .pf-visor {
    width: 100vw; max-width: 100vw; height: 100dvh; max-height: 100dvh; margin: 0; padding: 0; border: 0;
    background: transparent; color: #fff; overflow: hidden;
  }
  #pf .pf-visor::backdrop { background: rgba(0, 18, 38, .9); }
  #pf .pf-visor[open] { display: grid; place-items: center; }
  #pf .pf-visor__figura { display: grid; justify-items: center; gap: .75rem; max-width: min(1100px, 100vw - 120px); }
  #pf .pf-visor__figura img { max-width: 100%; max-height: calc(100dvh - 140px); width: auto; height: auto; border-radius: 8px; }
  #pf .pf-visor__figura figcaption { max-width: 70ch; text-align: center; font-size: .92rem; color: #dbe3ee; }
  #pf .pf-visor__figura figcaption:empty { display: none; }
  #pf .pf-visor__cuenta { position: absolute; top: 18px; left: 20px; font-size: .9rem; color: #dbe3ee; }
  #pf .pf-visor button, #pf .pf-visor button:hover, #pf .pf-visor button:focus {
    position: absolute; display: grid; place-items: center;
    width: 48px; height: 48px; min-height: 0; margin: 0; padding: 0;
    border: 1px solid rgba(255, 255, 255, .35); border-radius: 12px;
    background: rgba(255, 255, 255, .08); color: #fff; cursor: pointer;
  }
  #pf .pf-visor button:hover { background: rgba(255, 255, 255, .18); }
  #pf .pf-visor button svg { width: 22px; height: 22px; }
  #pf .pf-visor__cerrar { top: 14px; right: 14px; }
  #pf .pf-visor__nav { top: 50%; translate: 0 -50%; }
  #pf .pf-visor__nav--prev { left: 14px; }
  #pf .pf-visor__nav--next { right: 14px; }
  #pf .pf-visor__nav[hidden] { display: none; }

  @media (max-width: 860px) {
    #pf .pf-cabecera { grid-template-columns: minmax(0, 1fr); }
    #pf .pf-principal { order: -1; }
  }
  @media (max-width: 640px) {
    #pf .pf-grilla { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    #pf .pf-grilla figcaption { padding: .55rem .65rem .7rem; font-size: .78rem; }
    #pf .pf-visor__figura { max-width: calc(100vw - 24px); }
    #pf .pf-visor__nav { top: auto; bottom: 16px; translate: none; }
    #pf .pf-visor__figura img { max-height: calc(100dvh - 190px); }
  }

  @supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    #pf .pf-grilla figure { background: rgba(255, 255, 255, .95); }
  }
  @media (prefers-reduced-transparency: reduce) {
    #pf .pf-grilla figure { background: #fff; -webkit-backdrop-filter: none; backdrop-filter: none; }
  }
  @media (prefers-reduced-motion: reduce) {
    #pf *, #pf *::before, #pf *::after { transition: none !important; }
  }
</style>

<div id="pf">
  <div class="pf-cabecera">
    <div class="pf-texto">
      <a class="pf-ceja" href="/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/">Patrimonio Artístico</a>
      <p class="pf-lugar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 21s-7-6.1-7-11.5A7 7 0 0 1 19 9.5C19 14.9 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/></svg><span>Cementerio Municipal</span></p>
      <div class="pf-cuerpo">
        <p>Esta escultura vaciada en bronce pertenece al Mausoleo de la Familia Gibello que se encuentra en el <strong>Cementerio Municipal de nuestra ciudad</strong>. El artista José Sedlacek (<em>1900-1981</em>) crea, alrededor de 1937, esta obra a escala monumental con el fin de perpetuar el sentir del dolor que produce la pérdida de un ser amado y a la vez custodiar dicha sepultura. En 2017 se presentó en la muestra “Homenaje a José Sedlacek. Entre lo público y lo privado, obra reunida” realizada en el <strong>Museo Municipal “Sor Josefa Díaz y Clucellas” </strong> como parte del arte funerario que el artista desarrolló en aquella época, desde entonces se exhibe al ingreso del cementerio.</p>
      </div>
      <div class="pf-acciones">
        <a class="pf-btn" href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/Fragmento-del-catalogo-del-cementerio-municipal-de-2018.pdf" target="_blank" rel="noopener"><i class="pf-barra"></i>Más información <span class="pf-btn__tipo">PDF</span><span class="pf-sr"> (se abre en otra pestaña)</span></a>
      </div>
    </div>
    <figure class="pf-principal">
      <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-activacion-2017-1-1024x576.jpg" data-pf-foto data-pf-epigrafe="Dolorosa de José Sedlacek"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-activacion-2017-1-768x432.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-activacion-2017-1-768x432.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/2-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-activacion-2017-1-1024x576.jpg 1024w" sizes="(max-width: 860px) 100vw, 540px" alt="Dolorosa de José Sedlacek" width="768" height="432" fetchpriority="high"></a>
    </figure>
  </div>

  <section class="pf-galeria" aria-labelledby="pf-galeria-titulo">
    <h2 class="pf-galeria__titulo" id="pf-galeria-titulo">Galería <small>2 imágenes</small></h2>
    <ul class="pf-grilla">
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-2017-1024x230.jpg" data-pf-foto data-pf-epigrafe="Archivo digital MMAV · muestra “Homenaje a José Sedlacek. Entre lo público y lo privado, obra reunida” · 2017"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-2017-768x172.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-2017-768x172.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/1-archivo-digital-MMAV-muestra-Homenaje-a-Jose-Sedlacek.-Entre-lo-publico-y-lo-privado-obra-reunida-2017-1024x230.jpg 1024w" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo digital MMAV · muestra “Homenaje a José Sedlacek. Entre lo público y lo privado, obra reunida” · 2017" width="768" height="172" loading="lazy"></a>
        <figcaption>Archivo digital MMAV · muestra “Homenaje a José Sedlacek. Entre lo público y lo privado, obra reunida” · 2017</figcaption>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-digital-MMAV-Obra-del-mismo-autor-en-el-cementerio-municipal-1941-aprox.-scaled.jpg" data-pf-foto data-pf-epigrafe="Archivo digital MMAV Obra del mismo autor en el cementerio municipal · 1941 aprox"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-digital-MMAV-Obra-del-mismo-autor-en-el-cementerio-municipal-1941-aprox.-768x1088.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-digital-MMAV-Obra-del-mismo-autor-en-el-cementerio-municipal-1941-aprox.-768x1088.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2022/10/3-archivo-digital-MMAV-Obra-del-mismo-autor-en-el-cementerio-municipal-1941-aprox.-scaled.jpg 1808w" sizes="(max-width: 640px) 46vw, 260px" alt="Archivo digital MMAV Obra del mismo autor en el cementerio municipal · 1941 aprox" width="768" height="1088" loading="lazy"></a>
        <figcaption>Archivo digital MMAV Obra del mismo autor en el cementerio municipal · 1941 aprox</figcaption>
      </figure></li>
    </ul>
  </section>

  <dialog class="pf-visor" aria-label="Imagen ampliada">
    <button type="button" class="pf-visor__cerrar" data-pf-cerrar aria-label="Cerrar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
    <button type="button" class="pf-visor__nav pf-visor__nav--prev" data-pf-prev aria-label="Imagen anterior"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 12H5M11 6l-6 6 6 6"/></svg></button>
    <figure class="pf-visor__figura"><img alt=""><figcaption></figcaption></figure>
    <button type="button" class="pf-visor__nav pf-visor__nav--next" data-pf-next aria-label="Imagen siguiente"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button>
    <p class="pf-visor__cuenta" aria-live="polite"></p>
  </dialog>
</div>

<script>
(function () {
  'use strict'
  var raiz = document.getElementById('pf')
  var visor = raiz && raiz.querySelector('.pf-visor')
  if (!visor || !visor.showModal || raiz.dataset.pfInit) return
  raiz.dataset.pfInit = '1'

  var fotos = Array.prototype.slice.call(raiz.querySelectorAll('[data-pf-foto]'))
  var img = visor.querySelector('img')
  var epigrafe = visor.querySelector('figcaption')
  var cuenta = visor.querySelector('.pf-visor__cuenta')
  var prev = visor.querySelector('[data-pf-prev]')
  var next = visor.querySelector('[data-pf-next]')
  var actual = 0
  var origen = null

  function mostrar (i) {
    actual = (i + fotos.length) % fotos.length
    var a = fotos[actual]
    var miniatura = a.querySelector('img')
    img.src = a.href
    img.alt = miniatura ? miniatura.alt : ''
    epigrafe.textContent = a.getAttribute('data-pf-epigrafe') || ''
    cuenta.textContent = (actual + 1) + ' de ' + fotos.length
  }

  prev.hidden = next.hidden = fotos.length < 2

  fotos.forEach(function (a, i) {
    a.addEventListener('click', function (ev) {
      if (ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.button !== 0) return
      ev.preventDefault()
      origen = a
      mostrar(i)
      visor.showModal()
    })
  })

  prev.addEventListener('click', function () { mostrar(actual - 1) })
  next.addEventListener('click', function () { mostrar(actual + 1) })
  visor.addEventListener('click', function (ev) {
    if (ev.target === visor || ev.target.closest('[data-pf-cerrar]')) visor.close()
  })
  visor.addEventListener('keydown', function (ev) {
    if (ev.key === 'ArrowLeft' && fotos.length > 1) mostrar(actual - 1)
    if (ev.key === 'ArrowRight' && fotos.length > 1) mostrar(actual + 1)
  })
  visor.addEventListener('close', function () {
    img.removeAttribute('src')
    if (origen) origen.focus()
  })
})()
</script>
"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false}]

