/* GRID */
.editorial-grid{
  display:grid;
  grid-template-columns:repeat(5,5fr);
  gap:18px;
}

/* CARD */
.editorial-card{
  position:relative;
  display:flex;
  flex-direction:column;
  justify-content:space-between;

  padding:14px;

  text-decoration:none;

  background:#F3F5F7;
  overflow:hidden;

  border-radius:4px;
}

/* TOP */
.editorial-top{
  display:flex;
  justify-content:space-between;
  align-items:flex-start;
  margin-bottom:14px;
  position:relative;
  z-index:2;
}

.editorial-year,
.editorial-number{
  font-size:12px;
  font-weight:700;
  color:#002751;
}

/* WRAPPER DEL TÍTULO (CLAVE) */
.editorial-content{
  position:relative;
  z-index:2;
  padding-left:18px; /* espacio para la barra */
}

/* BARRA */
.editorial-content::before{
  content:"";
  position:absolute;

  left:0;
  top:2px;

  width:2px;
  height:100%;

  background:#00c08b;

  transform:rotate(15deg) scaleY(0);
  transform-origin:center;

  opacity:0;

  transition:
  transform .6s cubic-bezier(.19,1,.22,1),
  opacity .3s ease;
}

/* HOVER BARRA */
.editorial-card:hover .editorial-content::before{
  transform:rotate(15deg) scaleY(1);
  opacity:1;
}

/* TITLE */
.editorial-title{
  font-size:15px;
  line-height:1.45;
  font-weight:700;
  color:#002751;
  transition:transform .35s ease;
}

/* BUTTON */
.editorial-btn{
  margin-top:18px;
  font-size:10px;
  font-weight:700;
  letter-spacing:.4px;
  text-transform:uppercase;
  color:#002751 !important;
  width:max-content;
}

/* HOVER TEXT SHIFT */
.editorial-card:hover .editorial-title{
  transform:translateX(10px);
}



/* RESPONSIVE */
@media(max-width:1024px){
  .editorial-grid{
    grid-template-columns:repeat(2,1fr);
  }
}

@media(max-width:768px){
  .editorial-grid{
    grid-template-columns:1fr;
  }
}
</style>


