      <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-29-at-11.33.24-1024x768.jpeg" data-pf-foto data-pf-epigrafe="Alianza Francesa – “Ex casa del director del FFCC Francés”"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-29-at-11.33.24-768x576.jpeg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-29-at-11.33.24-768x576.jpeg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-29-at-11.33.24-1024x768.jpeg 1024w" sizes="(max-width: 860px) 100vw, 540px" alt="Alianza Francesa – “Ex casa del director del FFCC Francés”" width="768" height="576" fetchpriority="high"></a>
    </figure>
