/* RESET */
.masferia-programa *{
box-sizing:border-box;
}

/* CONTENEDOR */

.masferia-programa{
max-width:900px;
margin:60px auto;
padding:0 10px;
font-family:'Encode Sans', sans-serif;
color:#33434B;
}

/* HEADER */

.masferia-programa-header{
display:flex;
flex-direction:column;
align-items:center;
justify-content:center;
text-align:center;
margin-bottom:40px;
}

/* TITULO */

.masferia-programa h2{
font-size:28px;
font-weight:700;
color:#E6007E;
margin:0;
line-height:1.2;
}

/* BOTÓN DOSSIER */

.programa-dossier{
display:inline-flex;
align-items:center;
justify-content:center;
gap:5px;

margin-top:18px;
padding:10px 18px;

border:1px solid #33434B;
border-radius:4px;

background:#ffffff;
color:#33434B;

font-family:'Encode Sans', sans-serif;
font-size:13px;
font-weight:600;
letter-spacing:.2px;
text-decoration:none;

transition:all .3s ease;
}

.programa-dossier:hover{
background:#ffffff;
border-color:#33434B;
transform:translateY(-1px);
}

.programa-dossier svg{
width:16px;
height:16px;
flex-shrink:0;
}

/* ACORDEON */

.programa-dia{
border-top:1px solid #e5e5e5;
}

.programa-dia:last-child{
border-bottom:1px solid #e5e5e5;
}

/* BOTON DIA */

.programa-dia-btn{
width:100%;
background:transparent;
border:none;
padding:22px 0;
display:flex;
justify-content:space-between;
align-items:center;
cursor:pointer;
font-family:'Encode Sans', sans-serif;
text-align:left;
transition:background .3s ease;
}

.programa-dia-btn:hover{
background:#ffffff;
}

/* TITULO DIA */

.programa-dia-titulo{
font-size:18px;
font-weight:600;
color:#E6007E;
letter-spacing:.2px;
}

/* ICONO */

.programa-icono{
font-size:22px;
line-height:1;
color:#E6007E;
transition:transform .3s ease;
flex-shrink:0;
}

.programa-dia.activo .programa-icono{
transform:rotate(45deg);
}

/* CONTENIDO */

.programa-contenido{
max-height:0;
overflow:hidden;
transition:max-height .5s ease;
}

.programa-dia.activo .programa-contenido{
max-height:4000px;
}

/* ITEM */

.programa-item{
padding:22px 0;
border-top:1px solid #f1f1f1;
}

/* HORARIO */

.programa-hora{
font-size:13px;
font-weight:600;
letter-spacing:.3px;
text-transform:uppercase;
color:#E6007E;
margin-bottom:8px;
}

/* TITULO ACTIVIDAD */

.programa-titulo{
font-size:18px;
line-height:26px;
font-weight:600;
color:#33434B;
margin-bottom:8px;
}

/* TEXTO */

.programa-texto{
font-size:14px;
line-height:24px;
color:#33434B;
margin-bottom:10px;
}

/* LUGAR */

.programa-lugar{
font-size:14px;
line-height:22px;
color:#33434B;
opacity:.85;
}

/* LOGOS */

.programa-logos{
display:flex;
flex-wrap:wrap;
gap:12px;
align-items:center;
margin-top:16px;
}

.programa-logos img{
height:32px;
width:auto;
display:block;
object-fit:contain;
opacity:.9;
}

/* ACORDEON ACTIVO */

.programa-dia.activo .programa-dia-btn{
background:#ffffff;
}

/* =========================
TABLET
========================= */

@media(max-width:1024px){

.masferia-programa{
padding:0 20px;
}

}

/* =========================
MOBILE
========================= */

@media(max-width:768px){

.masferia-programa{
padding:0 16px;
margin:40px auto;
}

.masferia-programa-header{
margin-bottom:30px;
}

.masferia-programa h2{
font-size:24px;
line-height:30px;
}

.programa-dossier{
font-size:12px;
padding:9px 16px;
}

.programa-dossier svg{
width:15px;
height:15px;
}

.programa-dia-btn{
padding:18px 0;
align-items:flex-start;
gap:10px;
}

.programa-dia-titulo{
font-size:16px;
line-height:22px;
padding-right:10px;
}

.programa-icono{
font-size:20px;
margin-top:-1px;
}

.programa-item{
padding:18px 0;
}

.programa-hora{
font-size:12px;
line-height:18px;
}

.programa-titulo{
font-size:16px;
line-height:24px;
}

.programa-texto,
.programa-lugar{
font-size:13px;
line-height:22px;
}

.programa-logos{
gap:10px;
}

.programa-logos img{
height:24px;
max-width:100%;
}

}

/* MOBILE CHICO */

@media(max-width:480px){

.masferia-programa{
padding:0 14px;
}

.programa-dia-titulo{
font-size:15px;
line-height:21px;
}

.programa-titulo{
font-size:15px;
line-height:22px;
}

.programa-texto,
.programa-lugar{
font-size:13px;
line-height:21px;
}

.programa-logos img{
height:22px;
}

}

</style>


