}

/* IMAGEN */

.masferia-lightbox-thumb{
width:75%;
cursor:pointer;
transition:transform .3s ease, opacity .3s ease;
display:block;
}

.masferia-lightbox-thumb:hover{
transform:scale(1.01);
opacity:.95;
}

/* LIGHTBOX */

.masferia-lightbox{
position:fixed;
inset:0;
background:rgba(255,255,255,.96);
display:flex;
justify-content:center;
align-items:center;
padding:40px;
z-index:99999;

opacity:0;
visibility:hidden;
transition:all .3s ease;
}

/* ACTIVO */

.masferia-lightbox.activo{
opacity:1;
visibility:visible;
}

/* IMAGEN GRANDE */

.masferia-lightbox img{
max-width:95vw;
max-height:92vh;
width:auto;
height:auto;
object-fit:contain;
display:block;
}

/* CERRAR */

.masferia-lightbox-cerrar{
position:absolute;
top:20px;
right:24px;
font-size:34px;
line-height:1;
color:#33434B;
cursor:pointer;
font-family:'Encode Sans', sans-serif;
transition:opacity .3s ease;
}

.masferia-lightbox-cerrar:hover{
opacity:.6;
}

/* MOBILE */

@media(max-width:768px){

