}

}

</style>


<div class="masferia-lightbox-wrap">

<img 
class="masferia-lightbox-thumb"
src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/05/Mesa-de-trabajo-1-8.png"
alt="+Feria 2026">

</div>


<div class="masferia-lightbox" id="masferiaLightbox">

<span class="masferia-lightbox-cerrar">&times;</span>

<img 
src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/05/Mesa-de-trabajo-1-8.png"
alt="+Feria 2026">

</div>


<script>

const thumb = document.querySelector('.masferia-lightbox-thumb');
const lightbox = document.getElementById('masferiaLightbox');
const cerrar = document.querySelector('.masferia-lightbox-cerrar');

thumb.addEventListener('click', ()=>{
lightbox.classList.add('activo');
document.body.style.overflow='hidden';
});

cerrar.addEventListener('click', cerrarLightbox);

lightbox.addEventListener('click', (e)=>{
if(e.target === lightbox){
cerrarLightbox();
}
});

function cerrarLightbox(){
lightbox.classList.remove('activo');
document.body.style.overflow='';
}

document.addEventListener('keydown', (e)=>{
if(e.key === 'Escape'){
cerrarLightbox();
}
});

</script>","_margin":{"unit":"px","top":"-80","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false},{"id":"df18f84","elType":"section","settings":{"content_position":"middle","margin":{"unit":"px","top":"40","right":0,"bottom":"0","left":0,"isLinked":false},"margin_mobile":{"unit":"px","top":"20","right":0,"bottom":"0","left":0,"isLinked":false}},"elements":[{"id":"737682e","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"343d52c","elType":"widget","settings":{"editor":"<p style="font-size: 14px; line-height: 20px; text-align: left;">Del 15 al 17 de mayo en los Altos de la Estación Belgrano vas a poder disfrutar la sexta edición de <strong>+Feria Arte Contemporáneo</strong> de Santa Fe. Un encuentro dedicado a la exhibición y comercialización de obras de arte, acompañado por un programa abierto de actividades que celebran el arte contemporáneo en la ciudad.
