/* CONTENEDOR GENERAL */
.bloques-feria {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  gap: 40px;
  flex-wrap: wrap;
}

/* BLOQUE */
.bloque-feria {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between; /* 🔥 tip pro */
  text-align: center;
  width: 240px;
  height: 220px; /* 🔥 altura uniforme */
}

/* ICONO */
.icono-feria {
  height: 90px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.pattern-svg {
  width: 80px;
  max-height: 80px;
  overflow: visible;
}

/* TEXTO */
.bloque-feria-texto {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.bloque-feria-texto h3 {
  font-size: 15px;
  font-weight: 500;
  margin: 0;
}

.bloque-feria-texto p {
  font-size: 13px;
  line-height: 18px;
  margin: 0;
  max-width: 220px;
}

@media (max-width: 768px) {

  .bloque-feria {
    justify-content: flex-start; /* 🔥 clave */
    height: auto; /* 🔥 elimina el espacio forzado */
    gap: 24px; /* controla el espacio real */
  }

  .icono-feria {
    height: auto; /* 🔥 elimina caja rígida */
  }

  .pattern-svg {
    width: 70px;
    max-height: 70px;
  }

}

/* ========================= */
/* LEGADO */
/* ========================= */

.legado .grupo {
  transform-origin: center;
  animation: grupoLegado 10s cubic-bezier(0.65,0,0.35,1) infinite;
}

.legado .negra {
  animation: negraLegado 10s ease-out infinite;
}

.legado .magenta {
  animation: magentaLegado 10s ease-out infinite;
}

@keyframes negraLegado {
  0% {opacity:0; transform:translateX(-120px);}
  25% {opacity:1; transform:translateX(0);}
  100% {transform:translateX(0);}
}

@keyframes magentaLegado {
  0% {opacity:0; transform:translateX(120px);}
  25% {opacity:1; transform:translateX(0);}
  100% {transform:translateX(0);}
}

@keyframes grupoLegado {
  0% {opacity:0; transform:scale(0.95);}
  25% {opacity:1; transform:scale(1);}
  35% {transform:rotate(4deg);}
  45% {transform:rotate(0);}
  70% {transform:scale(1);}
  85% {transform:scale(1.02);}
  100% {transform:scale(1);}
}

/* ========================= */
/* PULSO */
/* ========================= */

.pulso .grupo {
  transform-origin: center;
  animation: grupoPulso 3.2s ease-in-out infinite;
}

.pulso .negra {
  animation: negraPulso 3.2s ease-out infinite;
}

.pulso .magenta {
  animation: magentaPulso 3.2s ease-out infinite;
}

@keyframes negraPulso {
  0% {opacity:0; transform:translateX(-140px);}
  20% {opacity:1; transform:translateX(5px);}
  30% {transform:translateX(0);}
  100% {transform:translateX(0);}
}

@keyframes magentaPulso {
  0% {opacity:0; transform:translateX(140px);}
  20% {opacity:1; transform:translateX(-5px);}
  30% {transform:translateX(0);}
  100% {transform:translateX(0);}
}

@keyframes grupoPulso {
  0% {opacity:0; transform:scale(0.9);}
  20% {opacity:1; transform:scale(1);}
  30% {transform:scale(1.08);}
  40% {transform:scale(1);}
  55% {transform:scale(1.05);}
  65% {transform:scale(1);}
  75% {transform:translateY(-2px);}
  85% {transform:translateY(0);}
  100% {transform:scale(1);}
}

/* ========================= */
/* VISIÓN */
/* ========================= */

.vision .grupo {
  transform-origin: center;
  animation: grupoVision 5.5s ease-in-out infinite;
}

.vision .negra {
  animation: negraVision 5.5s ease-out infinite;
}

.vision .magenta {
  animation: magentaVision 5.5s ease-out infinite;
}

@keyframes negraVision {
  0% {opacity:0; transform:translateY(80px);}
  25% {opacity:1; transform:translateY(0);}
  100% {transform:translateY(0);}
}

@keyframes magentaVision {
  0% {opacity:0; transform:translateY(-80px);}
  25% {opacity:1; transform:translateY(0);}
  100% {transform:translateY(0);}
}

@keyframes grupoVision {
  0% {opacity:0; transform:scale(0.9) translateY(10px);}
  25% {opacity:1; transform:scale(1) translateY(0);}
  40% {transform:scale(1.06);}
  55% {transform:scale(1);}
  70% {transform:translateY(-6px);}
  85% {transform:translateY(0);}
  100% {transform:scale(1);}
}

</style>


