<script>

const thumb = document.querySelector('.masferia-lightbox-thumb');
const lightbox = document.getElementById('masferiaLightbox');
const cerrar = document.querySelector('.masferia-lightbox-cerrar');

thumb.addEventListener('click', ()=>{
lightbox.classList.add('activo');
document.body.style.overflow='hidden';
});

cerrar.addEventListener('click', cerrarLightbox);

lightbox.addEventListener('click', (e)=>{
if(e.target === lightbox){
cerrarLightbox();
}
});

function cerrarLightbox(){
lightbox.classList.remove('activo');
document.body.style.overflow='';
}

document.addEventListener('keydown', (e)=>{
if(e.key === 'Escape'){
cerrarLightbox();
}
});

</script>				</div>
