    <h2 class="pf-galeria__titulo" id="pf-galeria-titulo">Galería <small>2 imágenes</small></h2>
    <ul class="pf-grilla">
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/Copia-de-IMG-20230420-WA0035-1024x808.jpg" data-pf-foto data-pf-epigrafe=""><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/Copia-de-IMG-20230420-WA0035-768x606.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/Copia-de-IMG-20230420-WA0035-768x606.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/Copia-de-IMG-20230420-WA0035-1024x808.jpg 1024w" sizes="(max-width: 640px) 46vw, 260px" alt="Lex Legum: imagen 1" width="768" height="606" loading="lazy"></a>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/Copia-de-IMG_20230404_115809557-scaled.jpg" data-pf-foto data-pf-epigrafe=""><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/Copia-de-IMG_20230404_115809557-768x1365.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/Copia-de-IMG_20230404_115809557-768x1365.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/Copia-de-IMG_20230404_115809557-scaled.jpg 1440w" sizes="(max-width: 640px) 46vw, 260px" alt="Lex Legum: imagen 2" width="768" height="1365" loading="lazy"></a>
      </figure></li>
