<div id="pf">
  <div class="pf-cabecera">
    <div class="pf-texto">
      <a class="pf-ceja" href="/capitalcultural/huellas-de-mi-ciudad/patrimonio-publico/artistico/">Patrimonio Artístico · Murales de César López Claro</a>
      <p class="pf-lugar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 21s-7-6.1-7-11.5A7 7 0 0 1 19 9.5C19 14.9 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/></svg><span>FADU · UNL</span></p>
      <div class="pf-cuerpo">
        <p>Se trata de un mural-móvil donado por el artista a la Universidad Nacional del Litoral, el mismo se encuentra exhibido en el Salón de Actos de la Facultad de Arquitectura Diseño y Urbanismo. Se trata de una pintura sobre lienzo (realizada en 1995) mide 5 m de largo por 3 m de alto. López Claro recrea una escena que evoca el hacinamiento, las torturas y los asesinatos cometidos a los jóvenes estudiantes de La Plata que reclamaban por el boleto estudiantil, y que fueron detenidos ilegalmente la noche del16 de septiembre de 1976 por la última dictadura militar Argentina (1976-1983).</p>
      </div>
    </div>
    <figure class="pf-principal">
      <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1783-1024x683.jpg" data-pf-foto data-pf-epigrafe="La noche de los lápices"><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1783-768x512.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1783-768x512.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1783-1024x683.jpg 1024w" sizes="(max-width: 860px) 100vw, 540px" alt="La noche de los lápices" width="768" height="512" fetchpriority="high"></a>
    </figure>
  </div>

  <section class="pf-galeria" aria-labelledby="pf-galeria-titulo">
    <h2 class="pf-galeria__titulo" id="pf-galeria-titulo">Galería <small>4 imágenes</small></h2>
    <ul class="pf-grilla">
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1795-1024x683.jpg" data-pf-foto data-pf-epigrafe=""><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1795-768x512.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1795-768x512.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1795-1024x683.jpg 1024w" sizes="(max-width: 640px) 46vw, 260px" alt="La noche de los lápices: imagen 1" width="768" height="512" loading="lazy"></a>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1794-1024x683.jpg" data-pf-foto data-pf-epigrafe=""><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1794-768x512.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1794-768x512.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1794-1024x683.jpg 1024w" sizes="(max-width: 640px) 46vw, 260px" alt="La noche de los lápices: imagen 2" width="768" height="512" loading="lazy"></a>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1791-1024x683.jpg" data-pf-foto data-pf-epigrafe=""><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1791-768x512.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1791-768x512.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1791-1024x683.jpg 1024w" sizes="(max-width: 640px) 46vw, 260px" alt="La noche de los lápices: imagen 3" width="768" height="512" loading="lazy"></a>
      </figure></li>
      <li><figure>
        <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1786-1024x683.jpg" data-pf-foto data-pf-epigrafe=""><img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1786-768x512.jpg" srcset="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1786-768x512.jpg 768w, https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2023/11/IMG_1786-1024x683.jpg 1024w" sizes="(max-width: 640px) 46vw, 260px" alt="La noche de los lápices: imagen 4" width="768" height="512" loading="lazy"></a>
      </figure></li>
    </ul>
  </section>

  <dialog class="pf-visor" aria-label="Imagen ampliada">
    <button type="button" class="pf-visor__cerrar" data-pf-cerrar aria-label="Cerrar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
    <button type="button" class="pf-visor__nav pf-visor__nav--prev" data-pf-prev aria-label="Imagen anterior"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 12H5M11 6l-6 6 6 6"/></svg></button>
    <figure class="pf-visor__figura"><img alt=""><figcaption></figcaption></figure>
    <button type="button" class="pf-visor__nav pf-visor__nav--next" data-pf-next aria-label="Imagen siguiente"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button>
    <p class="pf-visor__cuenta" aria-live="polite"></p>
  </dialog>
</div>

<script>
(function () {
  'use strict'
  var raiz = document.getElementById('pf')
  var visor = raiz && raiz.querySelector('.pf-visor')
  if (!visor || !visor.showModal || raiz.dataset.pfInit) return
  raiz.dataset.pfInit = '1'

  var fotos = Array.prototype.slice.call(raiz.querySelectorAll('[data-pf-foto]'))
  var img = visor.querySelector('img')
  var epigrafe = visor.querySelector('figcaption')
  var cuenta = visor.querySelector('.pf-visor__cuenta')
  var prev = visor.querySelector('[data-pf-prev]')
  var next = visor.querySelector('[data-pf-next]')
  var actual = 0
  var origen = null

  function mostrar (i) {
    actual = (i + fotos.length) % fotos.length
    var a = fotos[actual]
    var miniatura = a.querySelector('img')
    img.src = a.href
    img.alt = miniatura ? miniatura.alt : ''
    epigrafe.textContent = a.getAttribute('data-pf-epigrafe') || ''
    cuenta.textContent = (actual + 1) + ' de ' + fotos.length
  }

  prev.hidden = next.hidden = fotos.length < 2

  fotos.forEach(function (a, i) {
    a.addEventListener('click', function (ev) {
      if (ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.button !== 0) return
      ev.preventDefault()
      origen = a
      mostrar(i)
      visor.showModal()
    })
  })

  prev.addEventListener('click', function () { mostrar(actual - 1) })
  next.addEventListener('click', function () { mostrar(actual + 1) })
  visor.addEventListener('click', function (ev) {
    if (ev.target === visor || ev.target.closest('[data-pf-cerrar]')) visor.close()
  })
  visor.addEventListener('keydown', function (ev) {
    if (ev.key === 'ArrowLeft' && fotos.length > 1) mostrar(actual - 1)
    if (ev.key === 'ArrowRight' && fotos.length > 1) mostrar(actual + 1)
  })
  visor.addEventListener('close', function () {
    img.removeAttribute('src')
    if (origen) origen.focus()
  })
})()
</script>
"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false}]

