[{"id":"f3e2098","elType":"section","settings":{"margin":{"unit":"px","top":"0","right":0,"bottom":"50","left":0,"isLinked":false}},"elements":[{"id":"01d979b","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"782c8f8","elType":"widget","settings":{"html":"<section class="cc-zapata">

    <div class="cc-zapata__contenedor">

        <div class="cc-zapata__contenido">

            <h2>
                Homenaje a Zapata Gollán<br>
                <small>(La última entrevista)</small>
            </h2>

            <p>
                En el marco de los <strong>450 años de la fundación de Santa Fe</strong>,
                y con motivo de un nuevo aniversario del nacimiento de
                <strong>Agustín Zapata Gollán</strong>, el Archivo de la Imagen
                Documental Santafesina presenta este valioso documento audiovisual.
            </p>

            <p>
                El material recupera un fragmento del programa
                <strong>"La Tierra y su gente"</strong>, emitido en 2001, que rescata
                la última entrevista realizada por <strong>Jorge Álvarez</strong> a
                Agustín Zapata Gollán en 1985, durante los festejos por sus
                90 años de vida.
            </p>

            <p>
                La emisión original fue presentada por la Asociación Amigos de
                Santa Fe La Vieja y la Subsecretaría de Cultura de la Provincia
                de Santa Fe, con producción de Latinoamericana de Televisión.
                Archivo Jorge Álvarez.
            </p>

            <div class="cc-zapata__datos">

                <div>
                    <strong>Duración</strong>
                    <span>49 minutos</span>
                </div>

                <div>
                    <strong>Formato</strong>
                    <span>Color · U-Matic</span>
                </div>

                <div>
                    <strong>Trabajo realizado</strong>
                    <span>Digitalización y subtitulado por el Archivo de la Imagen Documental Santafesina.</span>
                </div>

                <div>
                    <strong>Edición de sonido</strong>
                    <span>Mediateca · Municipalidad de Santa Fe.</span>
                </div>

            </div>

        </div>

        <div class="cc-zapata__video">

            <iframe
                src="https://www.youtube.com/embed/gKkHW6P02NQ"
                title="Homenaje a Zapata Gollán"
                allowfullscreen>
            </iframe>

            <a class="cc-zapata__boton"
               href="https://www.youtube.com/watch?v=gKkHW6P02NQ"
               target="_blank"
               rel="noopener">
                Ver en YouTube
            </a>

        </div>

    </div>

</section>

