f3751","elType":"widget","settings":{"editor":"<p style="font-size: 13px; line-height: 20px; color: #ffffff;">Este Parque-Biblioteca se proyecta como una intervención que integra aspectos culturales, ambientales y de inclusión social-urbana. La planificación recupera un predio abandonado, potencia las condiciones paisajísticas de un parque natural excepcional y ofrece un nuevo espacio público a la comunidad, promoviendo la convivencia armoniosa con el río y el entorno costero.</p>","_padding":{"unit":"px","top":"0","right":"40","bottom":"0","left":"040","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"a2669d5","elType":"widget","settings":{"text":"Conocé más","link":{"url":"https://www.museodelaconstitucion.org/el-parque.php","is_external":"on","nofollow":"","custom_attributes":""},"align":"center","typography_typography":"custom","typography_font_size":{"unit":"px","size":15,"sizes":[]},"__globals__":{"hover_color":"globals/colors?id=astglobalcolor0","button_background_hover_color":"globals/colors?id=6dca99a0"}},"elements":[],"widgetType":"button"}],"isInner":false},{"id":"45b039e","elType":"column","settings":{"_column_size":33,"_inline_size":null,"content_position":"top","background_background":"classic","background_image":{"url":"https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2024/04/MG_6224-copia.jpg","id":23061,"size":"","alt":"","source":"library"},"background_position":"center center","background_attachment":"fixed","background_overlay_background":"classic","background_overlay_opacity":{"unit":"px","size":0.7,"sizes":[]},"margin":{"unit":"px","top":"0","right":"5","bottom":"0","left":"0","isLinked":false},"padding":{"unit":"px","top":"200","right":"0","bottom":"200","left":"0","isLinked":false},"__globals__":{"background_overlay_color":"globals/colors?id=astglobalcolor8"},"margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"10","left":"0","isLinked":false},"padding_mobile":{"unit":"px","top":"100","right":"0","