 }

 var ESTILO_MAPA = 'https://tiles.openfreemap.org/styles/positron'

 var PALETA_MAPA = {
 fondo: '#182b4c',
 manzana: '#1b3157',
 verde: '#213a60',
 agua: '#101d33',
 edificio: '#2b436d',
 edificioBorde: '#344d79',
 calle: '#385078',
 avenida: '#465f86',
 autopista: '#536c94',
 borde: '#2b4166',
 limite: 'rgba(246,128,198,.35)',
 texto: '#cbd3e2',
 textoAgua: '#8b97b0',
 halo: '#182b4c'
 }

 var TEXTOS_MAPA = {
 'AttributionControl.ToggleAttribution': 'Mostrar créditos del mapa',
 'Map.Title': 'Mapa de bares adheridos y Food Parks',
 'Marker.Title': 'Punto del mapa',
 'NavigationControl.ZoomIn': 'Acercar',
 'NavigationControl.ZoomOut': 'Alejar',
 'CooperativeGesturesHandler.WindowsHelpText': 'Usá Ctrl + la rueda del mouse para acercar el mapa',
 'CooperativeGesturesHandler.MacHelpText': 'Usá ⌘ + la rueda del mouse para acercar el mapa',
 'CooperativeGesturesHandler.MobileHelpText': 'Usá dos dedos para mover el mapa'
 }

 function cargarMapLibre () {
 if (window.maplibregl) return Promise.resolve(window.maplibregl)
 if (window.NDLM_MAPLIBRE) return window.NDLM_MAPLIBRE

 if (!document.querySelector('link[data-ndlm-maplibre]')) {
 var hoja = document.createElement('link')
 hoja.rel = 'stylesheet'
 hoja.href = MAPLIBRE.css
 hoja.integrity = MAPLIBRE.cssSri
 hoja.crossOrigin = 'anonymous'
 hoja.setAttribute('data-ndlm-maplibre', '')
 document.head.appendChild(hoja)
 }

 var carga = window.NDLM_MAPLIBRE = new Promise(function (ok, mal) {
 var s = document.createElement('script')
 s.src = MAPLIBRE.js
 s.integrity = MAPLIBRE.jsSri
 s.crossOrigin = 'anonymous'
 s.async = true
 s.onload = function () {
 window.maplibregl ? ok(window.maplibregl) : mal(new Error('MapLibre cargo pero no quedo disponible'))
 }
 s.onerror = function () { mal(new Error('No se pudo cargar MapLibre')) }
 document.head.appendChild(s)
 })

 carga.catch(function () { window.NDLM_MAPLIBRE = null })
 return carga
 }

 function plegarCreditos (mapa) {
 mapa.once('idle', function () {
 var c = mapa.getContainer().querySelector('.maplibregl-ctrl-attrib.maplibregl-compact')
 if (c) c.classList.remove('maplibregl-compact-show')
 })
 }

 function tematizarMapa (estilo) {
 var P = PALETA_MAPA
 estilo.layers = estilo.layers.filter(function (l) {

 return l.type !== 'raster' && l.type !== 'hillshade' && !/shield/.test(l.id)
 })
 estilo.layers.forEach(function (l) {
 var id = l.id
 var p = l.paint = l.paint || {}
 if (l.type === 'background') {
 p['background-color'] = P.fondo
 } else if (l.type === 'fill') {
 p['fill-color'] = /water/.test(id) ? P.agua
 : /building/.test(id) ? P.edificio
 : /park|wood|grass|landcover/.test(id) ? P.verde
 : /pier|aeroway/.test(id) ? P.fondo
 : P.manzana
 if (/building/.test(id)) p['fill-outline-color'] = P.edificioBorde
 } else if (l.type === 'line') {
 p['line-color'] = /water/.test(id) ? P.agua
 : /boundary/.test(id) ? P.limite
 : /casing/.test(id) ? P.borde
 : /dashline|pier/.test(id) ? P.fondo
 : /motorway/.test(id) ? P.autopista
 : /major/.test(id) ? P.avenida
 : P.calle
 } else if (l.type === 'symbol') {
 var agua = /water/.test(id)
 p['text-color'] = agua ? P.textoAgua : P.texto
 p['text-halo-color'] = agua ? P.agua : P.halo
 p['text-halo-width'] = 1.2
 p['text-halo-blur'] = 0
 }
 })
 return estilo
 }

 function pinGastro (g) {
 var b = document.createElement('button')
 b.type = 'button'
 b.className = 'ndlm-pin' + (g.foodpark ? ' ndlm-pin--foodpark' : '')
