				<div class="elementor-element elementor-element-9007d63 elementor-widget elementor-widget-html" data-id="9007d63" data-element_type="widget" data-e-type="widget" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<section class="ndlm ndlm-seccion" id="ndlm-cronistas">
 <div class="ndlm-limite">
 <h2 class="ndlm-titulo ndlm-barra"><span>Cronistas NDM/26</span></h2>
 <p class="ndlm-cronistas__lema">Que no te la cuenten</p>
 <div class="ndlm-cronistas__intro">
 <p class="ndlm-bajada">
 Durante la 12.ª Noche de los Museos de Santa Fe te invitamos a ser cronista de la
 noche y registrar, a través de tus fotografías, momentos, escenas, personas,
 espacios y situaciones que den cuenta de cómo se vivió el evento.
 </p>
 <p class="ndlm-bajada">
 Podés enviar hasta 3 fotografías tomadas durante la Noche. Entre las imágenes
 recibidas que cumplan con los requisitos se realizará una selección que formará
 parte de un dossier digital de la 12.ª Noche de los Museos, que será difundido a
 través de los canales de comunicación de la Municipalidad de Santa Fe.
 </p>
 </div>

 <div class="ndlm-cronistas__grilla">
 <article class="ndlm-panel ndlm-cronistas__panel ndlm-cronistas__panel--participar">
 <h3 class="ndlm-titulo-3 ndlm-cronistas__titulo">¿Cómo participar?</h3>
 <p class="ndlm-panel__texto">Registrate en el formulario online y enviá tus fotografías.</p>
 <p class="ndlm-cronistas__accion">
 <a class="ndlm-boton ndlm-boton--rosa ndlm-boton--grande" href="https://docs.google.com/forms/d/e/1FAIpQLSeLPqCyBu56nQebPjH-LeUD4M85ZH06P52x42zKzXAXbLPcUw/viewform?usp=dialog" target="_blank" rel="noopener">Ir al formulario<span class="ndlm-oculto-visual"> de Cronistas NDM/26 (se abre en otra pestaña)</span></a>
 </p>
 <p class="ndlm-cronistas__rotulo">Al enviar tus fotografías, indicá:</p>
 <ul>
 <li><span>Nombre, apellido y DNI.</span></li>
 <li><span>Lugar, espacio cultural, museo o sitio registrado.</span></li>
 <li><span>Breve referencia de la fotografía.</span></li>
 </ul>
 </article>

 <article class="ndlm-panel ndlm-cronistas__panel">
 <h3 class="ndlm-titulo-3 ndlm-cronistas__titulo">Las fotografías deberán</h3>
 <ul>
 <li><span>Haber sido tomadas durante la 12.ª Noche de los Museos, el sábado 24 de octubre de 2026.</span></li>
 <li><span>Ser de autoría de quien realiza el envío.</span></li>
 <li><span>No ser ofensivas, discriminatorias ni vulnerar derechos de terceros.</span></li>
 <li><span>Respetar la privacidad y dignidad de las personas retratadas.</span></li>
 </ul>
 </article>

 <article class="ndlm-panel ndlm-cronistas__panel">
 <h3 class="ndlm-titulo-3 ndlm-cronistas__titulo">Autorización de uso</h3>
 <p class="ndlm-panel__texto">
 El envío de la fotografía implica autorizar a la Municipalidad de Santa Fe, de
 manera gratuita y no exclusiva, a reproducirla, comunicarla y difundirla en el
 marco de la Noche de los Museos y de las acciones de comunicación, promoción y
 documentación vinculadas con el evento, mencionando la autoría.
 </p>
 <p class="ndlm-panel__texto">
 La participación no implica la cesión de los derechos de autor sobre la
 fotografía, que continúan perteneciendo a su autor/a.
 </p>
 </article>
 </div>
 </div>
</section>				</div>
				</div>
				<div class="elementor-element elementor-element-c651912 elementor-widget elementor-widget-html" data-id="c651912" data-element_type="widget" data-e-type="widget" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<div class="ndlm-bloque-mudo" hidden></div>
<script>(function () {
 'use strict'

 var CAJAS = '.ndlm-limite'

 var REPARTE = '.ndlm-cuadricula'

 var TOPE = 5

 var PLIEGUE = 0.9

 function arrancaFuera (el) {
 var alto = window.innerHeight || document.documentElement.clientHeight
 return el.getBoundingClientRect().top > alto * PLIEGUE
 }

 function piezasDe (caja) {
 var piezas = []
 Array.prototype.forEach.call(caja.children, function (hijo) {
 if (hijo.matches && hijo.matches(REPARTE) && hijo.children.length) {
 piezas.push.apply(piezas, Array.prototype.slice.call(hijo.children))
 } else {
 piezas.push(hijo)
 }
 })
 return piezas
 }

 function entradas () {
 if (!('IntersectionObserver' in window)) return
 if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return

 var marcadas = []
 document.querySelectorAll(CAJAS).forEach(function (caja) {
 piezasDe(caja).forEach(function (pieza, i) {

 if (pieza.classList.contains('ndlm-entrada')) return
 if (!arrancaFuera(pieza)) return
 pieza.classList.add('ndlm-entrada')
 pieza.style.setProperty('--ndlm-orden', Math.min(i, TOPE))
 marcadas.push(pieza)
 })
 })

 if (!marcadas.length) return

 document.documentElement.classList.add('ndlm-anima')

 var pendientes = marcadas.slice()

 function mostrar (pieza) {
 pieza.classList.add('ndlm-entrada--visible')
 vigia.unobserve(pieza)
 var i = pendientes.indexOf(pieza)
 if (i >= 0) pendientes.splice(i, 1)
 if (!pendientes.length) {

 vigia.disconnect()
 window.removeEventListener('scroll', alMoverse)
 window.removeEventListener('resize', alMoverse)
 }
 }

 var vigia = new IntersectionObserver(function (vistas) {
 vistas.forEach(function (v) { if (v.isIntersecting) mostrar(v.target) })
 }, { rootMargin: '0px 0px -6% 0px', threshold: 0.03 })

 var pedido = 0
 function barrer () {
 pedido = 0
 var alto = window.innerHeight || document.documentElement.clientHeight
 pendientes.slice().forEach(function (pieza) {
 if (pieza.getBoundingClientRect().top < alto) mostrar(pieza)
 })
 }
 function alMoverse () {
 if (pedido) return
 pedido = requestAnimationFrame(barrer)
 }
 window.addEventListener('scroll', alMoverse, { passive: true })
 window.addEventListener('resize', alMoverse, { passive: true })

 marcadas.forEach(function (pieza) { vigia.observe(pieza) })
 }

 window.NDLM = window.NDLM || {}
 window.NDLM.entradas = entradas

 if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', entradas)
 else entradas()

 if (window.jQuery) window.jQuery(window).on('elementor/frontend/init', entradas)
 window.addEventListener('elementor/frontend/init', entradas)

})();

