 function esc (s) {
 return String(s == null ? '' : s)
 .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
 .replace(/"/g, '&quot;').replace(/'/g, '&#39;')
 }

 function claveOrden (s) { return String(s || '').replace(/^[^\p{L}\p{N}]+/u, '') }

 function sinTildes (s) {
 return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
 }

 function icono (d, clase) {
 return '<svg class="' + (clase || '') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
 'stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' +
 '<path d="' + d + '"/></svg>'
 }

 function iconoAcc (e, clase) {
 if (e && e.pictograma) {
 return '<svg class="ndlm-pictograma ' + (clase || '') + '" viewBox="' + e.pictograma.vb + '" ' +
 'aria-hidden="true" focusable="false">' + e.pictograma.svg + '</svg>'
 }
 return e && e.icono ? icono(e.icono, clase) : ''
 }

