<!-- Uso: <svg class="docs-card-icon"><use href="#icon-calendar"></use></svg> dentro de cada tarjeta -->"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false},{"id":"8c08870","elType":"section","settings":{"margin":{"unit":"px","top":"0","right":0,"bottom":"0","left":0,"isLinked":true}},"elements":[{"id":"f811e80","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"b5cffa3","elType":"widget","settings":{"html":"<style>
.hero-disena{
  --barra:0px;
  box-sizing:border-box; /* que el padding de mobile entre dentro del 100svh */
  position:relative; /* imprescindible: ancla la capa ::before de la foto a este
                        bloque. Sin esto la capa se ancla a la página y la foto
                        termina de fondo de todo el documento. */
  margin-left:calc(50% - 50vw + var(--barra) / 2);
  margin-right:calc(50% - 50vw + var(--barra) / 2);
  height:100vh;
  min-height:520px;
  display:flex;
  align-items:center;
  justify-content:center;
  overflow:hidden;
  background:#000; /* mientras carga la foto */
}

/* Foto + velo oscuro, en una sola capa detrás del contenido */
.hero-disena::before{
  content:'';
  position:absolute;
  inset:0;
  background:
    linear-gradient(180deg, rgba(0,0,0,0.55), rgba(0,0,0,0.72)),
    url('https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/05/MarcePucci_SC_LaDisena_14122025_013.jpg') center / cover no-repeat;
}

.hero-disena-contenido{
  position:relative;
  box-sizing:border-box;
  width:100%;
  max-width:800px; /* mantiene la línea en un largo cómodo de leer */
  padding:0 24px;
  text-align:center;
}

.hero-disena-texto{
  color:#ffffff;
  /* acompaña el ancho de la pantalla entre 17 y 22px */
  font-size:clamp(17px, 1.7vw, 22px);
  line-height:1.5;
  margin:0;
  text-shadow:0 2px 18px rgba(0,0,0,0.85), 0 1px 3px rgba(0,0,0,0.7);
}

/* Entrada: sube rápido y se acomoda lento. La curva es una salida exponencial,
   así que casi todo el recorrido pasa en el primer tercio del tiempo y el resto
   es el frenado. El texto entra apenas después que el logo. */
@keyframes heroEntra{
  from{ opacity:0; transform:translateY(56px); }
  to{ opacity:1; transform:translateY(0); }
}
.hero-disena-texto{
  animation:heroEntra 1.3s cubic-bezier(.16, 1, .3, 1) .15s both;
}

@media (prefers-reduced-motion: reduce){
  .hero-disena-texto{
    animation:none;
  }
}

@media(max-width:768px){
  .hero-disena{
    height:auto;
    min-height:100svh;
    padding:80px 0;
  }
  .hero-disena-texto{
    line-height:1.55; /* un respiro más en pantallas angostas, donde corta en más líneas */
  }
}
</style>

<section class="hero-disena">
  <div class="hero-disena-contenido">
    <p class="hero-disena-texto">Festival Diseña es el encuentro de diseño de Santa Fe: impulsa la creatividad, la innovación y la economía creativa local, y reúne cada año a cientos de marcas y diseñadores de la región.</p>
  </div>
</section>

<script>
// Descuenta el ancho de la barra de scroll para que la hero mida exactamente el
// ancho visible y la página no gane scroll horizontal.
(function(){
  function medir(){
    var barra = window.innerWidth - document.documentElement.clientWidth;
    document.querySelectorAll('.hero-disena').forEach(function(h){
      h.style.setProperty('--barra', barra + 'px');
    });
  }
  medir();
  window.addEventListener('resize', medir);
})();
</script>

<!-- Aviso de resultados: misma forma que el CTA de abajo, para no competir con
     la hero ni con el resto de la página. -->
<p style="text-align:center; margin:0 auto 14px auto;">Ya están los resultados de la convocatoria 2026/2027. <a href="/capitalcultural/festivaldisena/docs/#seleccionados">Ver las marcas seleccionadas →</a></p>

