/* LIGHTBOX */
.disena-lightbox{
  display:none;
  position:fixed;
  inset:0;
  background:rgba(0,0,0,0.92);
  z-index:9999;
  align-items:center;
  justify-content:center;
}
.disena-lightbox:target{
  display:flex;
}
/* Capa de fondo: cubre todo el overlay y cierra al hacer click fuera de la
   imagen. Va detrás de la foto, la cruz y las flechas, que suben con z-index.
   aria-hidden + tabindex="-1" para no duplicar el botón de cerrar en lectores
   de pantalla ni en la navegación por teclado. */
.disena-lightbox-fondo{
  position:absolute;
  inset:0;
  cursor:zoom-out;
}
.disena-lightbox img{
  position:relative;
  z-index:1;
  max-width:90vw;
  max-height:85vh;
  width:auto;
  height:auto;
  object-fit:contain;
  border-radius:4px;
}
.disena-lightbox-close,
.disena-lightbox-arrow{
  position:absolute;
  z-index:2; /* por encima de la foto: en pantallas angostas la foto llega a
                solaparlos, y con el mismo z-index tapaba la flecha anterior */
  color:#fff;
  text-decoration:none;
  line-height:1;
  user-select:none;
}
.disena-lightbox-close{
  top:20px;
  right:30px;
  font-size:36px;
