<!-- Mejora opcional (no crítica): flechas del teclado y Escape para cerrar. Si este
     script no corre por algún motivo, el lightbox sigue funcionando igual con clicks. -->
<script>
document.addEventListener('keydown', function(e){
  var open = document.querySelector('.disena-lightbox:target');
  if(!open) return;
  if(e.key === 'Escape'){ location.hash = '#galeria'; }
  if(e.key === 'ArrowRight'){ var n = open.querySelector('.disena-lightbox-next'); if(n) location.hash = n.getAttribute('href'); }
  if(e.key === 'ArrowLeft'){ var p = open.querySelector('.disena-lightbox-prev'); if(p) location.hash = p.getAttribute('href'); }
});
</script>

