[{"id":"d801310","elType":"section","settings":{"margin":{"unit":"px","top":"50","right":0,"bottom":"50","left":0,"isLinked":false},"padding":{"unit":"px","top":"0","right":"50","bottom":"0","left":"50","isLinked":false},"padding_mobile":{"unit":"px","top":"0","right":"5","bottom":"0","left":"5","isLinked":false}},"elements":[{"id":"7205f08","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"1b63c0d","elType":"widget","settings":{"html":"<style>
.accordion{
  width:100%;
}

/* ITEM */
.accordion-item{
  border-bottom:1px solid #e5e5e5;
}

/* HEADER */
.accordion-header{
  width:100%;
  text-align:left;
  background:none;
  border:none;
  outline:none;
  cursor:pointer;

  font-size:15px;
  font-weight:600;
  color:#54595f !important;

  padding:14px 0;

  display:flex;
  align-items:center;
  gap:10px;
}

/* ICONO IZQUIERDA */
.accordion-header::before{
  content:"+";
  font-size:18px;
  transition:transform .2s ease;
}

/* ACTIVO */
.accordion-header.active{
  color:#00C08B !important;
}

.accordion-header.active::before{
  content:"−";
}

/* CONTENIDO */
.accordion-content{
  max-height:0;
  overflow:hidden;
  transition:max-height .3s ease;

  font-size:13px;
  color:#54595f;
}

.accordion-content-inner{
  padding-bottom:14px;
}

/* PÁRRAFOS */
.accordion-content p{
  font-size:13px;
  line-height:18px;
  padding-left:10px;
  margin:0 0 10px 0;
}

/* LINKS */
.accordion-content a{
  color:#54595f;
  text-decoration:underline;
}
</style>


<div class="accordion">

  <!-- ========================= -->
  <!-- ITEM 1 -->
  <!-- ========================= -->
  <div class="accordion-item">
    <button class="accordion-header">Diseñar libros desde el vacío</button>
    <div class="accordion-content">
      <div class="accordion-content-inner">

     <p><strong>Tipografía, grilla y composición para la lectura.</strong></p>
      <p>A cargo de <strong>Julián Balangero.</strong></p><br>

      <p><strong>Fechas:</strong> Lunes 27 y martes 28 de abril.</p>
      <p><strong>Horario:</strong> De 16 a 19 horas.</p><br>

      <p><strong>Lugar:</strong> Sala Mercado Editorial, Balcarce 1635.</p><br>
      <p><strong>Destinado a mayores de 16 años.</strong></p>
      <p><strong>Cupos limitados.</strong></p>
      <p><strong>Inscripción abierta hasta el 24 de abril.</strong></p><br>

      <p>Formulario: <a href="https://forms.gle/uREyfLyWi1hHD5JJA" target="_blank">Formulario de inscripción</a></p>

      <br>

      <p>Este taller propone un recorrido desde la historia y la teoría del diseño editorial hacia su aplicación práctica en InDesign, abordando decisiones clave desde la hoja en blanco hasta el libro impreso.</p>

      <p>Se sugiere contar con conocimientos previos de InDesign.</p>

      <p>Julián Balangero es Licenciado en Diseño de la Comunicación Visual (FADU–UNL) y docente de Tipografía en FADU–UBA. Cuenta con amplia experiencia en proyectos editoriales e institucionales.</p><br>

      <p><strong>Para más información:</strong> 
        <a href="mailto:mercadoeditorial@santafeciudad.gov.ar">mercadoeditorial@santafeciudad.gov.ar</a>
      </p>
      </div>
    </div>
  </div>


  <!-- ========================= -->
  <!-- ITEM 2 -->
  <!-- ========================= -->
  <div class="accordion-item">
    <button class="accordion-header">Ciclo: Borges, lector</button>
    <div class="accordion-content">
      <div class="accordion-content-inner">

        <p>Con motivo del Día del Lector, el grupo Epopeya presenta el ciclo “Borges, lector”, compuesto por dos charlas a cargo de invitados especialistas.</p>

        <p>Participarán la profesora <strong>Adriana Crolla</strong> con "Borges y Dante, en contrapunto", y el escritor <strong>Santiago De Luca</strong> con "La dimensión borgeana. Una introducción".</p>

        <p>Ambas presentaciones incluirán un espacio de intercambio con el público.</p>

        <p>Para consultas: <a href="mailto:mercadoeditorial@santafeciudad.gov.ar">mercadoeditorial@santafeciudad.gov.ar</a></p>

      </div>
    </div>
  </div>


  <!-- ========================= -->
  <!-- ITEM 3 -->
  <!-- ========================= -->
  <div class="accordion-item">
    <button class="accordion-header">La edición de lo inédito</button>
    <div class="accordion-content">
      <div class="accordion-content-inner">

        <p><strong>Lugar:</strong> Sala Mercado Editorial (Mercado Progreso) – Balcarce 1635</p>
        <p><strong>Fechas:</strong> Sábados 28 de junio, 5, 12 y 19 de julio</p>
        <p><strong>Horario:</strong> De 10 a 12 h</p>
        <p><strong>Destinado a mayores de 16 años</strong></p>

        <p>El taller propone una introducción a la <strong>edición artesanal de textos</strong> desde una perspectiva teórico-práctica.</p>

        <p><strong>Bloque lógico:</strong> Edición de textos y herramientas.</p>
        <p><strong>Bloque físico:</strong> Producción y encuadernación.</p>

        <p><a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2025/06/LaEdiciondeloinedito.pdf" target="_blank">Estructura del taller</a></p>

        <p><strong>Inscripción gratuita con cupos limitados.</strong></p>
        <p>Hasta el 26 de junio: <a href="https://forms.gle/XHDCHQ21v7oozsHr6" target="_blank">Formulario de inscripción</a></p>

        <p>Consultas: <a href="mailto:mercadoeditorial@santafeciudad.gov.ar">mercadoeditorial@santafeciudad.gov.ar</a></p>

      </div>
    </div>
  </div>


  <!-- ========================= -->
  <!-- ITEM 4 -->
  <!-- ========================= -->
  <div class="accordion-item">
    <button class="accordion-header">Ilustración de libros y publicaciones</button>
    <div class="accordion-content">
      <div class="accordion-content-inner">

        <p>Taller a cargo de <strong>Soledad Grossi</strong>.</p>

        <p><strong>Lugar:</strong> Sala Mercado Editorial (Mercado Progreso)</p>
        <p><strong>Fechas:</strong> Sábados 10, 17, 24 y 31 de mayo</p>
        <p><strong>Horario:</strong> De 10 a 12 h</p>
        <p><strong>Destinado a mayores de 16 años</strong></p>

        <p>Contenidos:</p>
        <ul>
          <li>Libros y revistas</li>
          <li>Prensa gráfica</li>
          <li>Cómics y novelas gráficas</li>
          <li>Libros infantiles</li>
        </ul>

        <p><a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2025/04/tallerProg.pdf" target="_blank">Estructura del taller</a></p>

        <p><strong>Inscripción gratuita con cupos limitados.</strong></p>
        <p>Hasta el 5 de mayo: <a href="https://forms.gle/uqZunNuDHt5ysHoW9" target="_blank">Formulario de inscripción</a></p>

        <p>Consultas: <a href="mailto:mercadoeditorial@santafeciudad.gov.ar">mercadoeditorial@santafeciudad.gov.ar</a></p>

      </div>
    </div>
  </div>


  <!-- ===================================================== -->
  <!-- 🔧 PARA AGREGAR NUEVOS ITEMS -->
  <!-- Copiá desde <div class="accordion-item"> hasta </div> -->
  <!-- y pegalo abajo, cambiando título y contenido -->
  <!-- ===================================================== -->

</div>


<script>
const headers = document.querySelectorAll(".accordion-header");

headers.forEach(header => {
  header.addEventListener("click", () => {

    const content = header.nextElementSibling;

    header.classList.toggle("active");

    if(content.style.maxHeight){
      content.style.maxHeight = null;
    } else {
      content.style.maxHeight = content.scrollHeight + "px";
    }

  });
});
