/* Contenedor flex con wrapping y centrado */
.btn-row {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  justify-content: center;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}

/* Botón base */
.btn-insti {
  display: flex;
  align-items: center;       /* centra verticalmente */
  justify-content: center;
  padding: 10px 20px;
  font-size: 15px !important;
  font-weight: 700 !important;
  color: #002751 !important;
  background-color: #ffffff;
  border: none;
  border-radius: 0;
  cursor: pointer;
  white-space: normal;
  position: relative;
  flex: 1 1 23%;
  box-sizing: border-box;
  min-width: 180px;
  text-align: center;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

/* Hover flotante */
.btn-insti:hover {
  transform: translateY(-5px);
  box-shadow: 0 6px 15px rgba(0,0,0,0.15);
}

/* Contenedor texto */
.btn-insti > span:first-child {
  display: inline-block;
  max-width: 100%;
  word-wrap: break-word;
  line-height: 1.2em;
}

/* Barra inclinada */
.barra-inclinada {
  width: 2px;
  height: 1.5em;
  margin-left: 10px;
  background: linear-gradient(to bottom, #00c08b, #002751);
  transform: rotate(15deg);
  transform-origin: top center;
  display: inline-block;
  vertical-align: middle;
  flex-shrink: 0;
}

</style>

