  padding:18px 0;
}

.muttis-anio{
  font-size:14px;
  font-weight:700;
  text-transform:uppercase;
  color:#002751;
  margin-bottom:4px;
}

.muttis-titulo{
  font-size:15px;
  line-height:1.3;
  font-weight:700;
  color:#00C08B;
  margin-bottom:10px;
}

.muttis-titulo span{
  opacity:.7;
  font-weight:500;
}

.muttis-info{
  font-size:13px;
  line-height:1.6;
}

.muttis-info p{
  margin:0 0 10px;
}

.muttis-link{
  display:inline-flex;
  margin-top:8px;
  text-decoration:none;
  font-weight:700;
  border-bottom:1px solid currentColor;
  transition:.25s ease;
}

.muttis-link:hover{
  opacity:.7;
}

.muttis-programa{
  margin-top:14px;
  padding-left:12px;
  border-left:2px solid #dcdcdc;
}

.muttis-programa h4{
  margin:0 0 10px;
  font-size:13px;
  font-weight:700;
}

.muttis-programa p{
  margin:0 0 10px;
}

@media(max-width:768px){

  .muttis-bloque{
    padding:16px 0;
  }

}
</style>

<div class="muttis-cursos">

  <!-- 2025 -->
  <section class="muttis-bloque">

    <div class="muttis-anio">
      2025
    </div>

    <div class="muttis-titulo">
      Imaginar, ver, contar <span>| Taller</span>
    </div>

    <div class="muttis-info">

      <p>
        <strong>Docente:</strong> Dr. Estanislao Giménez Corte<br>
        <strong>Fechas:</strong> Miércoles 3, 10, 17 y 24 de septiembre<br>
        <strong>Horario:</strong> De 19 a 21 horas<br>
        <strong>Lugar:</strong> Biblioteca Municipal “Profesor Enrique Muttis”<br>
        <strong>Dirección:</strong> Primera Junta 2451, Santa Fe
      </p>

      <p>
        El taller propone estimular la lectura, la imaginación y la reflexión a través de encuentros presenciales de análisis, intercambio y discusión.
      </p>

    </div>

  </section>


  <!-- 2025 -->
  <section class="muttis-bloque">

    <div class="muttis-anio">
      2025
    </div>

    <div class="muttis-titulo">
      Borges vuelve a la Biblioteca Muttis <span>| Curso</span>
    </div>

    <div class="muttis-info">

      <p>
        <strong>Docente:</strong> Dr. Estanislao Giménez Corte<br>
        <strong>Fechas:</strong> Miércoles 7, 14, 21 y 28 de mayo<br>
        <strong>Horario:</strong> De 19 a 21 horas (con pausa a mitad del encuentro)<br>
        <strong>Lugar:</strong> Biblioteca Municipal “Profesor Enrique Muttis”<br>
        <strong>Dirección:</strong> 1º de Junta 2451, Santa Fe
      </p>

      <p>
        Este curso propone una introducción abierta a la obra de Jorge Luis Borges.
      </p>

    </div>

  </section>


  <!-- 2024 -->
  <section class="muttis-bloque">

    <div class="muttis-anio">
      2024
    </div>

    <div class="muttis-titulo">
      Borges visita la Biblioteca Muttis <span>| Curso</span>
    </div>

    <div class="muttis-info">

      <p>
        <strong>Docente:</strong> Dr. Estanislao Giménez Corte<br>
        <strong>Fechas:</strong> 28/08, 25/09, 30/10 y 27/11<br>
        <strong>Horario:</strong> De 19 a 21 horas (con pausa a mitad del encuentro)<br>
        <strong>Lugar:</strong> Biblioteca Municipal “Profesor Enrique Muttis”<br>
        <strong>Dirección:</strong> 1º de Junta 2451, Santa Fe
      </p>

      <a href="#" class="muttis-link">
        Encontrá toda la información
      </a>

    </div>

  </section>
  
  <!-- AGREGAR ESTE BLOQUE DEBAJO DEL CURSO "CURSO DE LECTURA Y ANÁLISIS" -->

<section class="muttis-bloque">

  <div class="muttis-anio">
    2024
  </div>

  <div class="muttis-titulo">
    Tertulias en la Muttis <span>| Curso</span>
  </div>

  <div class="muttis-info">

    <p>
      <strong>A cargo de:</strong> Verónica Przylucki
    </p>

    <p>
      ¿Te gusta Shakespeare? ¡Entonces no te podés perder esta oportunidad! Vení a las “Tertulias en la Muttis”, donde vamos a leer, reflexionar y debatir sobre <strong>“Sueño de una Noche de Verano”</strong>.
    </p>

    <p>
      Este curso presencial está pensado para todo público y estará dirigido por Verónica Przylucki.
    </p>

    <p>
      Nos vamos a encontrar tres veces: el 4 de septiembre, el 4 de octubre y el 4 de noviembre de 2024, de 18 a 20 horas.
    </p>

    <p>
      La actividad es gratuita, pero requiere inscripción previa. Los cupos son limitados.
    </p>

    <a href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2024/08/pdf-shakespeare.pdf" target="_blank" class="muttis-link">
      Más información
    </a>

  </div>

</section>

</div>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false}]

