				<div class="elementor-widget-container">
					<div class="texto-container">
  <p class="texto">
    Es una obra clave de la dramaturgia argentina y santafesina que narra el encuentro inquietante entre dos personas en medio de la inmensidad de la pampa. Esta nueva versión propone una mirada contemporánea, profundamente física y poética, sobre el texto original. Se incorporan técnicas de mimo corporal dramático, así como el uso de teatro de sombras y diseño sonoro, para construir un lenguaje escénico multidisciplinario.

  </p>
  <a href="#" class="leer-mas">Leer más</a>
</div>

<style>
  .texto {
    font-size: 13px;
    display: -webkit-box;
    -webkit-line-clamp: 2; /* líneas visibles */
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
    cursor: inherit;
  }
  .texto.expandido {
    -webkit-line-clamp: unset;
  }
  .leer-mas {
    color: inherit;
    cursor: pointer;
    text-decoration: underline;
    font-weight: bold;
    user-select: none;
  }
</style>

<script>
  function activarLeerMas() {
    const contenedores = document.querySelectorAll('.texto-container');
    contenedores.forEach(container => {
      const texto = container.querySelector('.texto');
      const toggle = container.querySelector('.leer-mas');

      if (texto && toggle && !toggle.dataset.listener) {
        toggle.dataset.listener = "true";
        toggle.addEventListener('click', function(e) {
          e.preventDefault();
          texto.classList.toggle('expandido');
          toggle.textContent = texto.classList.contains('expandido') ? 'Leer menos' : 'Leer más';
        });
      }
    });
  }

  // Ejecutar en carga inicial
  document.addEventListener('DOMContentLoaded', activarLeerMas);

  // Ejecutar si Elementor recarga contenido (por ejemplo, en plantillas o listas)
  if (window.elementorFrontend) {
    window.elementorFrontend.hooks.addAction('frontend/element_ready/global', activarLeerMas);
  }
</script>

				</div>
