"elements":[{"id":"925e3ab","elType":"widget","settings":{"title":"Jurado Selección Artistas, Galerías, Colectivos y Proyectos","typography_typography":"custom","typography_font_size":{"unit":"px","size":17,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"4114a0b","elType":"widget","settings":{"html":"<div class="jurado-grid">

<!-- 1 -->
<div class="jurado-item" onclick="abrirModal('modal1')">
  <div class="jurado-img">
    <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/03/juradoJoaquin.png">
  </div>
  <div class="jurado-nombre">Joaquín Rodríguez</div>
  <div class="jurado-bio">
    Licenciado en Curaduría y Gestión de Arte. Vicedirector del MAMBA, curador general de arteCo 2025 e impulsor del Premio EN OBRA y el Premio IN SITU.
  </div>
</div>

<!-- 2 -->
<div class="jurado-item" onclick="abrirModal('modal2')">
  <div class="jurado-img">
    <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/03/Analía-Solomonoff.jpg">
  </div>
  <div class="jurado-nombre">Analía Solomonoff</div>
  <div class="jurado-bio">
    Curadora y gestora cultural. Directora del Museo Rosa Galisteo y la Sala Siqueiros. Dirige el Programa NODO.
  </div>
</div>

<!-- 3 -->
<div class="jurado-item" onclick="abrirModal('modal3')">
  <div class="jurado-img">
    <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/03/WhatsApp-Image-2021-10-17-at-22.44.13-1.jpeg">
  </div>
  <div class="jurado-nombre">Lali Martínez Spaggiari</div>
  <div class="jurado-bio">
    Artista, docente y gestora cultural. Directora de Museos y Patrimonio de Santa Fe y directora de Púrpura Proyecto.
  </div>
</div>

<!-- 4 -->
<div class="jurado-item" onclick="abrirModal('modal4')">
  <div class="jurado-img">
    <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/03/Blank-foto-pro-byn-scaled.jpg">
  </div>
  <div class="jurado-nombre">Carolina Blank</div>
  <div class="jurado-bio">
    Licenciada en Comunicación Social. Coordinadora de Museos y Patrimonios de la Secretaría de Cultura.
  </div>
</div>

<!-- 5 -->
<div class="jurado-item" onclick="abrirModal('modal5')">
  <div class="jurado-img">
    <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/03/Flor-Olmos.jpg">
  </div>
  <div class="jurado-nombre">Florencia Elisa Olmos</div>
  <div class="jurado-bio">
    Gestora cultural y profesora de Artes Visuales. Trabajadora del Museo Sor Josefa y co-directora de Delta Galería.
  </div>
</div>

</div>


