","_padding_mobile":{"unit":"px","top":"0","right":"5","bottom":"0","left":"5","isLinked":false}},"elements":[],"widgetType":"html"},{"id":"a5a621d","elType":"widget","settings":{"html":"<style>

@import url('https://fonts.googleapis.com/css2?family=Encode+Sans:wght@300;400;500;600&display=swap');

.jurado-grid,
.modal-contenido{
font-family:'Encode Sans', sans-serif;
}
/* =========================
GRID AUTO RESPONSIVE
========================= */

.jurado-grid{
display:grid;
grid-template-columns:repeat(auto-fit, minmax(180px, 1fr));
gap:24px;
margin-top:20px;

margin-left:auto;
margin-right:auto;

justify-items:center;
}

/* =========================
ITEM
========================= */

.jurado-item{
text-align:center;
cursor:pointer;
font-family:inherit !important;
}

/* =========================
IMAGEN
========================= */

.jurado-img{
width:100%;
max-width:120px;
aspect-ratio:1/1;
margin:0 auto 10px auto;
overflow:hidden;
}

.jurado-img img{
width:100%;
height:100%;
object-fit:cover;
display:block;

filter:grayscale(1);
transition:transform .4s ease, filter .4s ease;

border-radius:0 !important;
}

.jurado-item:hover .jurado-img img{
transform:scale(1.06);
filter:grayscale(0);
}

/* =========================
TEXTO
========================= */

.jurado-nombre{
font-size:15px;
font-weight:500;
color:#33434B;
}

.jurado-bio{
font-size:13px;
line-height:20px;
color:#33434B;
line-height:20px;

margin-top:6px;

display:-webkit-box;
-webkit-line-clamp:3;
-webkit-box-orient:vertical;
overflow:hidden;
min-height:57px;
}

/* =========================
MODAL
========================= */

.modal{
display:flex;
position:fixed;
top:0;
left:0;
width:100%;
height:100%;

background:rgba(0,0,0,0.45);
backdrop-filter: blur(6px);

z-index:9999;
padding:20px;

align-items:center;
justify-content:center;

opacity:0;
visibility:hidden;
pointer-events:none;

transition:opacity .3s ease;
}

.modal.activo{
opacity:1;
visibility:visible;
pointer-events:auto;
}

/* CONTENIDO */

.modal-contenido{
background:#ffffff;
max-width:700px;
width:100%;
padding:25px;
border-radius:8px;

display:grid;
grid-template-columns:200px 1fr;
gap:25px;

font-family:inherit !important;

transform:scale(0.95);
opacity:0;
transition:all .3s ease;
}

.modal.activo .modal-contenido{
transform:scale(1);
opacity:1;
}

/* IMAGEN MODAL */

.modal-img{
aspect-ratio:1/1;
overflow:hidden;
border-radius:0 !important;
}

.modal-img img{
width:100%;
height:100%;
object-fit:cover;
}

/* TEXTO */

.modal-texto h3{
font-size:15px;
font-weight:500;
color:#33434B;
margin-bottom:10px;
}

.modal-texto p{
font-size:14px;
line-height:20px;
color:#33434B;
}

/* BOTÓN */

.cerrar{
position:absolute;
top:10px;
right:15px;
font-size:22px;
cursor:pointer;
}

/* MOBILE */

@media(max-width:768px){

.modal-contenido{
grid-template-columns:1fr;
text-align:left;
}

.modal-img{
max-width:180px;
margin:0 auto;
}

}

</style>



<script>

function abrirModal(id){
document.getElementById(id).classList.add("activo");
}

function cerrarModal(id){
document.getElementById(id).classList.remove("activo");
}

window.addEventListener("click", function(e){
document.querySelectorAll(".modal").forEach(modal=>{
if(e.target === modal){
modal.classList.remove("activo");
}
});
});

document.addEventListener("keydown", function(e){
if(e.key === "Escape"){
document.querySelectorAll(".modal.activo").forEach(modal=>{
modal.classList.remove("activo");
});
}
});

</script>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false},{"id":"85770c8","elType":"section","settings":{"margin":{"unit":"px","top":"0","right":0,"bottom":"50","left":0,"isLinked":false}},"elements":[{"id":"1cb6f7b","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"84146dd","elType":"widget","settings":{"title":"Jurado Selección Editoriales","typography_typography":"custom","typography_font_size":{"unit":"px","size":17,"sizes":[]},"__globals__":{"title_color":""}},"elements":[],"widgetType":"heading"},{"id":"ffe124c","elType":"widget","settings":{"html":"<div class="jurado-grid">

