<div id="sf-seleccionados-root"></div>

<style>
#sf-seleccionados-root{
  width:100%;
  box-sizing:border-box;
  padding:15px;
  color:#54595F;
  font-family:'Encode Sans', sans-serif;
}
#sf-seleccionados-root h2{
  font-size:15px;
  margin:0 0 12px;
  font-weight:700;
}

.sf-categoria{padding:12px 0}
.sf-cab{margin-bottom:8px}
.sf-titulo{font-size:15px;font-weight:500}
.sf-sub{font-size:13px;margin-top:4px}

.sf-lista{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  margin-top:12px;
}

.sf-expositor-btn{
  background:#fff;
  padding:10px 12px;
  border-radius:2px;
  cursor:pointer;
  display:inline-flex;
  align-items:center;
  gap:10px;
  font-weight:600;
  font-size:13px;
  color:#54595F;

  /* 👇 NUEVO BORDE */
  border:1px solid #E3E6E8;

  transition:all .12s ease;
}

/* FIX ELEMENTOR */
#sf-seleccionados-root .sf-name{
  color:#54595F !important;
  display:inline !important;
  font-size:13px !important;
  opacity:1 !important;
  visibility:visible !important;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

/* 👇 HOVER MEJORADO */
.sf-expositor-btn:hover{
  border-color:#f4a2c7;
  box-shadow:0 0 0 2px rgba(244,162,199,.15);
}

.sf-dot{
  width:10px;
  height:10px;
  border-radius:50%;
  background:#f4a2c7;;
}

/* MODAL */
#sf-seleccionados-modal{
  position:fixed;
  inset:0;
  display:none;
  background:rgba(0,0,0,.45);
  align-items:center;
  justify-content:center;
  z-index:9999;
}
.sf-modal{
  background:#fff;
  padding:18px;
  border-radius:10px;
  max-width:560px;
  width:100%;
}
.sf-links{
  display:flex;
  flex-direction:column;
  gap:8px;
  margin-top:8px;
}
.sf-links a{
  padding:10px;
  border-radius:8px;
  background:#fff;
  font-weight:600;
  text-decoration:none;
  color:#54595F;
}
.sf-close{
  margin-top:12px;
  padding:8px 12px;
  border:0;
  background:#eee;
  border-radius:8px;
  cursor:pointer;
}

.sf-main{
  font-weight:700;
}

.sf-paren{
  font-weight:400;
  opacity:.6;
  font-size:13px;
}

@media(max-width:720px){
  .sf-lista{flex-direction:column}
  .sf-expositor-btn{width:100%}
}
@media(min-width:721px){
  .sf-expositor-btn{
    flex:1 1 calc(33.333% - 8px);
    min-width:160px;
  }
}
</style>

<div id="sf-seleccionados-modal">
  <div class="sf-modal">
    <h3 id="sf-modalTitle"></h3>
    <div id="sf-modalLinks" class="sf-links"></div>
    <button id="sf-modalClose" class="sf-close">Cerrar</button>
  </div>
</div>

<script>
(function(){

const data = [
{
categoria:"Artista individual (Ciudad de Santa Fe y Área Metropolitana)",
items:[
