{name:"Tres tristes trastiendas",links:["https://www.instagram.com/raffo.mariano/","https://www.instagram.com/hdlafranconiart/","https://www.instagram.com/maximilianomaignien/"]},
{name:"U.N.A. Red",links:["https://www.instagram.com/proyectobrea/","https://www.instagram.com/ainebertottiburket/","https://www.instagram.com/juanpablogarcia.jpg/"]},
