{name:"Biblioteca Turma",links:["https://www.instagram.com/somosturma/"]},
{name:"Bulbo Editorial",links:["https://www.instagram.com/bulbo_editorial/"]},
{name:"Editorial Karaoke",links:["https://www.instagram.com/karaoke_fan/"]},
{name:"Río arte y objetos",links:["https://www.instagram.com/__riotienda/"]},
{name:"Suspiro microediciones",links:["https://www.instagram.com/suspiro.editorial/"]}
]
}
];

const root=document.getElementById('sf-seleccionados-root');

const h=document.createElement('h2');
h.textContent="Seleccionados para esta edición";
root.appendChild(h);

data.forEach(cat=>{
const sec=document.createElement('div');
sec.className='sf-categoria';

const cab=document.createElement('div');
cab.className='sf-cab';

const t=document.createElement('div');
t.className='sf-titulo';

const match = cat.categoria.match(/^(.*?)\s*(\(.+\))$/);

if(match){
  const main = document.createElement('span');
  main.className = 'sf-main';
  main.textContent = match[1];

  const sub = document.createElement('span');
  sub.className = 'sf-paren';
  sub.textContent = ' ' + match[2];

  t.appendChild(main);
  t.appendChild(sub);
}else{
  t.textContent = cat.categoria;
}

const s=document.createElement('div');
s.className='sf-sub';
s.textContent='Expositores seleccionados';

cab.appendChild(t);
cab.appendChild(s);

const list=document.createElement('div');
list.className='sf-lista';

cat.items.forEach(item=>{
const btn=document.createElement('button');
btn.className='sf-expositor-btn';

const dot=document.createElement('span');
dot.className='sf-dot';

const name=document.createElement('span');
name.className='sf-name';
name.textContent=item.name;

btn.appendChild(dot);
btn.appendChild(name);

if(item.links.length===1){
btn.onclick=()=>window.open(item.links[0],'_blank');
}else{
btn.onclick=()=>openModal(item);
}

list.appendChild(btn);
});

sec.appendChild(cab);
sec.appendChild(list);
root.appendChild(sec);
});

/* MODAL */
const modal=document.getElementById('sf-seleccionados-modal');
const modalLinks=document.getElementById('sf-modalLinks');
const modalTitle=document.getElementById('sf-modalTitle');
document.getElementById('sf-modalClose').onclick=()=>modal.style.display='none';

function openModal(item){
modalTitle.textContent=item.name;
modalLinks.innerHTML='';
item.links.forEach(l=>{
const a=document.createElement('a');
a.href=l;
a.target='_blank';
a.textContent=l;
modalLinks.appendChild(a);
});
modal.style.display='flex';
}

})();
</script>
