document.querySelectorAll('.menu-ladisena a').forEach(function(a){
  var current = location.pathname.replace(/\/$/, '');
  var linkPath = a.getAttribute('href').replace(/\/$/, '');
  if (current === linkPath) a.classList.add('active');
});
</script>
