:root{
  --color-negro:#000000;
  --color-blanco:#ffffff;

  --color-verde:#00C08B;              /* --ast-global-color-1 del sitio */
  --color-azul-institucional:#002751; /* --ast-global-color-0 del sitio, mismo azul de .docs-card */
  --color-rojo-institucional:#E63312; /* extraído del isotipo SF/Cultura, mismo rojo de .docs-card */

  --color-gris-texto:#33434B;
  --color-gris-borde:#e5e5e5;
}

.menu-ladisena{
  position: sticky;      /* fija el menú al hacer scroll */
  top: 0;
  z-index: 500;          /* header del sitio no es sticky, no compite */
  border-top:1px solid var(--color-gris-borde);
  border-bottom:1px solid var(--color-gris-borde);
  margin:25px 0 0 0;
  padding:12px 0;
  background:var(--color-blanco);
}

.menu-ladisena-grid{
  display:flex;
  justify-content:center;
  gap:28px;
  flex-wrap:wrap;
}

.menu-ladisena a{
  text-decoration:none;
  font-size:14px;
  font-weight:500;
  color:var(--color-azul-institucional);
  padding:6px 12px;
  border-radius:4px;
  transition:color .25s ease, background-color .35s ease;
}

.menu-ladisena a:hover{
  color:var(--color-verde);
  background:rgba(0,192,139,0.08);
}

.menu-ladisena a.active{
  color:var(--color-rojo-institucional);
  background:rgba(230,51,18,0.08);
  font-weight:600;
}

/* Compensa la altura del menú sticky al saltar a un ancla (#clinicas-..., #disertantes).
   Sin esto el título de destino queda tapado por el menú. Acotado a encabezados
   con id para no tocar el resto del tema. */
h2[id], h3[id], h4[id], h5[id]{
  scroll-margin-top:80px;
}

@media(max-width:768px){
  .menu-ladisena-grid{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:10px;
    padding:0 10px;
  }
  .menu-ladisena a{
    border:1px solid var(--color-gris-borde);
    border-radius:4px; /* antes 6px, ajustado al radio institucional del sitio */
    padding:10px;
    font-size:13px;
    text-align:center;
  }
  .menu-ladisena a:hover{
    color:var(--color-verde);
    border-color:var(--color-verde);
  }
  .menu-ladisena a.active{
    border-color:var(--color-rojo-institucional);
  }
  h2[id], h3[id], h4[id], h5[id]{
    scroll-margin-top:140px; /* en mobile el menú ocupa dos filas */
  }
}

</style>

<div class="menu-ladisena">
  <div class="menu-ladisena-grid">
    <a href="/capitalcultural/festivaldisena/">Diseña Santa Fe</a>
    <a href="/capitalcultural/festivaldisena/trayectoria/">Historia y Trayectoria</a>
    <a href="/capitalcultural/festivaldisena/formaciones/">Formaciones</a>
    <a href="/capitalcultural/festivaldisena/docs/">Documentación Oficial</a>
  </div>
</div>

<script>
document.querySelectorAll('.menu-ladisena a').forEach(function(a){
  var current = location.pathname.replace(/\/$/, '');
  var linkPath = a.getAttribute('href').replace(/\/$/, '');
  if (current === linkPath) a.classList.add('active');
});
</script>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false},{"id":"fd0f92c","elType":"section","settings":{"layout":"full_width"},"elements":[{"id":"30b8ff7","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"aad92be","elType":"widget","settings":{"html":"<style>

:root{
  --color-rojo-institucional:#E63312;
}
/* ^ FIX: este bloque :root estaba sin cerrar. Al faltar la llave, todo el CSS
   siguiente quedaba anidado dentro de :root y @keyframes docsCardIn (inválido
   dentro de una regla de estilo) nunca se definía: las tarjetas no animaban. */

/* CONTENEDOR */
.docs-block{
  width:100%;
  margin:50px 0 25px 0;
}

/* TITULO */
.docs-block h3{
  font-size:20px;
  color:#002751;
  font-weight:700;
  margin-bottom:12px;
  line-height:20px;
}

/* TEXTO */
.docs-block p{
  font-size:14px;
  color:#33434B;
  line-height:20px;
  margin-bottom:18px;
}

.docs-cards{
  width:100%;
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(220px, 1fr));
  gap:22px;
  margin-top:30px;
  margin-bottom:80px;
}

/* CARD */
.docs-card{
  display:block;
  text-decoration:none;
  color:inherit;
  background:#002751;
  padding:20px;
  border-radius:4px;
  position:relative;
  overflow:hidden;
  cursor:pointer;

  transition:transform .35s ease, box-shadow .35s ease;

  animation:docsCardIn .5s ease both;
}

@keyframes docsCardIn{
  from{ opacity:0; transform:translateY(20px); }
  to{ opacity:1; transform:translateY(0); }
}

/* delay escalonado por posición, hasta la 6ta tarjeta */
.docs-card:nth-child(1){ animation-delay:.05s; }
.docs-card:nth-child(2){ animation-delay:.1s; }
.docs-card:nth-child(3){ animation-delay:.15s; }
.docs-card:nth-child(4){ animation-delay:.2s; }
.docs-card:nth-child(5){ animation-delay:.25s; }
.docs-card:nth-child(n+6){ animation-delay:.3s; }

/* accesibilidad: respetar "reducir movimiento" del sistema operativo */
@media (prefers-reduced-motion: reduce){
  .docs-card{
    animation:none;
  }
  .docs-card:hover{
    transform:none;
  }
}

/* línea superior */
.docs-card::before{
  content:'';
  position:absolute;
  top:0;
  left:0;
  width:100%;
  height:3px;
  background:linear-gradient(90deg, #00C08B, #002751);
}

/* hover */
.docs-card:hover{
  transform:translateY(-8px);
  box-shadow:0 12px 30px rgba(0,0,0,0.25);
}

/* foco visible por teclado: las cards son enlaces, deben verse al tabular */
.docs-card:focus-visible{
  outline:2px solid var(--color-rojo-institucional);
  outline-offset:3px;
}

/* TITULO — el ícono va al lado izquierdo, dentro de .docs-card-head */
.docs-card-head{
  display:flex;
  align-items:center;
  gap:10px;
  margin-bottom:6px;
}

.docs-card h4{
  font-size:15px;
  color:#ffffff;
  margin:0;
  font-weight:700;
  line-height:20px;
}

/* TEXTO */
.docs-card p{
  font-size:13px;
  color:#ffffff;
  line-height:1.5; /* sin unidad: escala con el font-size */
  margin:0;
}

/* ACENTO ROJO INSTITUCIONAL */
.docs-card .docs-card-meta{
  display:inline-block;
  margin-top:10px;
  font-size:11px;
  font-weight:700;
  letter-spacing:.03em;
  text-transform:uppercase;
  color:var(--color-rojo-institucional);
}

.docs-card .docs-card-arrow{
  display:inline-block;
  margin-top:10px;
  font-size:13px;
  font-weight:700;
  color:#ffffff; /* antes rojo institucional; ahora blanco, igual que el resto del texto de la card */
  transition:transform .25s ease;
}

.docs-card:hover .docs-card-arrow{
  transform:translateX(4px);
}

/* ícono: mismo tamaño/línea que el título, blanco como el resto del texto de la card */
.docs-card-icon{
  width:20px;
  height:20px;
  flex-shrink:0;
  color:#ffffff;
}

/* número azul sobre círculo blanco (antes: número blanco sobre círculo rojo) */
.docs-card-step{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:24px;
  height:24px;
  border-radius:50%;
  background:#ffffff;
  color:#002751;
  font-size:12px;
  font-weight:700;
  margin-bottom:10px;
}

/* MOBILE */
@media(max-width:768px){
  .docs-cards{
    grid-template-columns:1fr;
  }
}

</style>

