}
.disertante-card{
  border:1px solid #e5e5e5;
  border-radius:8px;
  padding:16px;
  text-align:center;

  /* columna flexible para que el "Ver CV completo" quede al pie de todas las
     tarjetas, sin importar el largo del resumen */
  display:flex;
  flex-direction:column;
}
.disertante-foto{
  width:120px;
  height:120px;
  border-radius:50%;
  margin:0 auto 12px;
  background:#f2f2f2;
  display:flex;
  align-items:center;
  justify-content:center;
  color:#33434B;
  font-size:12px;
  overflow:hidden;
}
.disertante-card img{
  width:100%;
  height:100%;
  object-fit:cover;
}
.disertante-card h4{
  color:#002751; /* antes #2F5D62 (verde azulado fuera de paleta); ahora azul institucional */
  margin:0 0 6px;
  font-size:16px;
}
.disertante-card .resumen{
  font-size:14px;
  color:#33434B;
  line-height:1.5;
  margin-bottom:10px;
}
.disertante-card .ver-cv{
  margin-top:auto;
  cursor:pointer;
