  font-weight:600;
  font-size:13px;
  text-decoration:none;
}

/* MODAL — mismo patrón CSS-only (:target) que el lightbox de fotos: no depende
   de ningún <script>, se abre/cierra solo con clicks. Reemplaza el <details>
   que expandía en línea. */
.cv-modal{
  display:none;
  position:fixed;
  inset:0;
  background:rgba(0,39,81,0.6); /* velo con el azul institucional, no negro puro */
  z-index:9999;
  align-items:center;
  justify-content:center;
  padding:20px;
}
.cv-modal:target{
  display:flex;
}
.cv-modal-content{
  background:#ffffff;
  border-radius:4px;
  max-width:600px;
  width:100%;
  max-height:85vh;
  overflow-y:auto;
  padding:32px;
  position:relative;
}
.cv-modal-content h4{
  color:#002751;
  margin:0 0 12px;
  font-size:18px;
}
.cv-modal-content p{
  color:#33434B;
  font-size:14px;
  line-height:1.6;
  margin:0 0 14px; /* varios CV ahora tienen más de un párrafo */
}
.cv-modal-content p:last-child{
  margin-bottom:0;
}
.cv-modal-close{
  position:absolute;
  top:16px;
  right:20px;
  color:#33434B;
  font-size:28px;
  line-height:1;
  text-decoration:none;
}
.cv-modal-close:hover{
  color:#E63312;
}
</style>

