<style>

:root{
  --color-negro:#000000;
  --color-blanco:#ffffff;

  --color-verde:#00C08B;              /* --ast-global-color-1 del sitio */
  --color-azul-institucional:#002751; /* --ast-global-color-0 del sitio, mismo azul de .docs-card */
  --color-rojo-institucional:#E63312; /* extraído del isotipo SF/Cultura, mismo rojo de .docs-card */

  --color-gris-texto:#33434B;
  --color-gris-borde:#e5e5e5;
}

.menu-ladisena{
  position: sticky;      /* fija el menú al hacer scroll */
  top: 0;
  z-index: 500;          /* header del sitio no es sticky, no compite */
  border-top:1px solid var(--color-gris-borde);
  border-bottom:1px solid var(--color-gris-borde);
  margin:25px 0 0 0;
  padding:12px 0;
  background:var(--color-blanco);
}

.menu-ladisena-grid{
  display:flex;
  justify-content:center;
  gap:28px;
  flex-wrap:wrap;
}

.menu-ladisena a{
  text-decoration:none;
  font-size:14px;
  font-weight:500;
  color:var(--color-azul-institucional);
  padding:6px 12px;
  border-radius:4px;
  transition:color .25s ease, background-color .35s ease;
}

.menu-ladisena a:hover{
  color:var(--color-verde);
  background:rgba(0,192,139,0.08);
}

.menu-ladisena a.active{
  color:var(--color-rojo-institucional);
  background:rgba(230,51,18,0.08);
  font-weight:600;
}

/* Compensa la altura del menú sticky al saltar a un ancla (#clinicas-..., #disertantes).
   Sin esto el título de destino queda tapado por el menú. Acotado a encabezados
   con id para no tocar el resto del tema. */
h2[id], h3[id], h4[id], h5[id]{
  scroll-margin-top:80px;
}

@media(max-width:768px){
  .menu-ladisena-grid{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:10px;
    padding:0 10px;
  }
  .menu-ladisena a{
    border:1px solid var(--color-gris-borde);
    border-radius:4px; /* antes 6px, ajustado al radio institucional del sitio */
    padding:10px;
    font-size:13px;
    text-align:center;
  }
  .menu-ladisena a:hover{
    color:var(--color-verde);
    border-color:var(--color-verde);
  }
  .menu-ladisena a.active{
    border-color:var(--color-rojo-institucional);
  }
  h2[id], h3[id], h4[id], h5[id]{
    scroll-margin-top:140px; /* en mobile el menú ocupa dos filas */
  }
}

</style>

