  font-size:13px;
  line-height:1.4;
  padding:9px 0;
  border-top:1px solid #e5e5e5;
  overflow-wrap:anywhere; /* nombres largos sin espacios no desbordan la columna */
}

/* Suplentes: el número es dato, no decoración — indica el orden de convocatoria */
.marcas-suplentes{
  counter-reset:suplente;
}
.marcas-suplentes li{
  counter-increment:suplente;
  display:flex;
  align-items:flex-start;
  gap:9px;
}
.marcas-suplentes li::before{
  content:counter(suplente);
  flex:0 0 auto;
  min-width:21px;
  height:21px;
  box-sizing:border-box;
  display:inline-flex;
  align-items:center;
  justify-content:center;
