  margin-bottom:10px;
  font-size:13px;
  line-height:20px;
}

.cc-capacitaciones-texto a{
  text-decoration:none;
}

.cc-capacitaciones-texto a:focus-visible{
  outline:2px solid currentColor;
  outline-offset:2px;
  border-radius:10px;
}

/* ---------- Tercer encuentro ---------- */

.cc-capacitaciones-texto .cc-cap-objetivos{
  margin:0 0 16px;
}

.cc-capacitaciones-texto .cc-cap-boton{
  display:inline-block;
  margin:4px 0 0 6px;
  padding:5px 16px;
  border:1px solid currentColor;
  border-radius:10px;
  font-size:13px;
  line-height:18px;
  font-weight:700;
  text-transform:none;
}

.cc-capacitaciones-texto .cc-cap-boton[aria-disabled="true"]{
  opacity:.5;
  pointer-events:none;
}

/* ---------- Docente ---------- */

.cc-capacitaciones-texto .cc-cap-docente{
  display:grid;
  grid-template-columns:160px 1fr;
  gap:24px;
  align-items:start;
  margin-top:30px;
}

.cc-capacitaciones-texto .cc-cap-docente img{
  width:100%;
  height:auto;
  display:block;
  border-radius:10px;
}

/* ---------- Encuentros realizados ---------- */

.cc-capacitaciones-texto .cc-cap-cards{
  display:grid;
  grid-template-columns:repeat(2, 1fr);
  gap:20px;
}

.cc-capacitaciones-texto .cc-cap-card{
  padding:20px;
  border:1px solid rgba(0,0,0,.1);
  border-radius:10px;
}

.cc-capacitaciones-texto .cc-cap-card-num{
  margin-bottom:6px;
  font-size:12px;
  opacity:.7;
}

.cc-capacitaciones-texto .cc-cap-card ul{
  margin-top:12px;
}

