            <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/08/logoCinemateca.jpg" alt="Cinemateca Armenia" loading="lazy" decoding="async">

            <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/08/logoACAU.jpg" alt="ACAU" loading="lazy" decoding="async">

            <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/08/logoCinema.png" alt="Cinema" loading="lazy" decoding="async">

            <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/08/logoRedCasasCultura.png" alt="Red de Casas de la Cultura" loading="lazy" decoding="async">

            <img src="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/08/logoCulturaNacion.png" alt="Secretaría de Cultura de la Nación" loading="lazy" decoding="async">

        </div>

    </section>

