/* ==========================================================================
   SECCION CIERRE TOCHI
   ========================================================================== */

.tochi-cierre-box {
  position: relative;
  overflow: hidden;
  padding: 60px 40px;
  text-align: center;
}

.tochi-cierre-box::before {
  content: "";
  position: absolute;
  top: 50%;
  right: 40px;
  transform: translateY(-50%);
  width: 260px;
  height: 260px;
  background-image: url('https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/06/TOCHI_Sello_un-juego-de-historias-prestadas@2x.png');
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  opacity: .08;
  pointer-events: none;
}

.tochi-cierre-content {
  position: relative;
  z-index: 2;
}

.tochi-cierre-content p {
  font-size: 17px;
  line-height: 1.3;
}

/* ==========================================================================
   TEXTO COORGANIZAN
   ========================================================================== */

.tochi-coorganizan {
  margin: 28px 0 18px;
  font-size: 13px;
  font-weight: 600;
  color: inherit;
}

/* ==========================================================================
   CONTENEDOR DE LOGOS
   ========================================================================== */

.tochi-logos {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 40px;
  flex-wrap: nowrap;
}

/* Regla base para todos los logos */
.tochi-logo {
  width: auto !important;
  max-width: none !important;
  object-fit: contain !important;
  display: block !important;
  flex-shrink: 0;
}

/* Logo Municipalidad de Santa Fe */
.tochi-logo-msf {
  height: 58px !important;
}

/* Logo Ministerio de Cultura */
.tochi-logo-cultura {
  height: 45px !important;
}

/* ==========================================================================
   RESPONSIVE
   ========================================================================== */

@media (max-width: 768px) {
  .tochi-cierre-box {
    padding: 40px 20px;
  }

  .tochi-cierre-box::before {
    width: 180px;
    height: 180px;
    right: -20px;
    opacity: .05;
  }

  .tochi-logos {
    gap: 24px;
    flex-wrap: wrap;
  }

  .tochi-logo-msf {
    height: 34px !important;
  }

  .tochi-logo-cultura {
    height: 25px !important;
  }
}

