.tochi-cierre-box {
  position: relative;
  overflow: hidden;
  padding: 60px 40px;
  text-align: center;
}

.tochi-cierre-box::before {
  content: "";
  position: absolute;
  top: 50%;
  right: 40px;
  transform: translateY(-50%);
  width: 260px;
  height: 260px;
  background-image: url('https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/06/TOCHI_Sello_un-juego-de-historias-prestadas@2x.png');
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  opacity: .08;
  pointer-events: none;
}

.tochi-cierre-content {
  position: relative;
  z-index: 2;
}

.tochi-cierre-content p {
  font-size: 17px;
  line-height: 1.3;
