    color:#002751;
    font-size:28px;
    margin-bottom:20px;
}

.cml-texto p{
    color:#555;
    line-height:1.8;
    margin-bottom:18px;
}

/*======================================
PROGRAMA
======================================*/

.cml-programa{
    margin-bottom:65px;
}

.cml-programa h3{
    color:#002751;
    font-size:30px;
    margin-bottom:28px;
}

.cml-grid{
    display:grid;
    grid-template-columns:repeat(auto-fit,minmax(260px,1fr));
    gap:24px;
}

.cml-card{
    background:#fff;
