    <!-- HERO -->

    <section class="cml-hero">

             <p>
            Todos los <strong>miércoles de agosto</strong>, de <strong>18 a 20 horas</strong>, se desarrollará en la Biblioteca Prof. Enrique Muttis (Primera Junta 2451) el curso <strong>"Música y Literatura: un diálogo posible"</strong>, a cargo de Estanislao Giménez Corte y Daniel Paolantonio. La actividad es <strong>libre y gratuita</strong> y <strong>no requiere inscripción previa.</strong>
        </p>

    </section>



    <!-- INFORMACIÓN -->

    <section class="cml-info">

        <article class="cml-item">
            <h3>Cuándo</h3>
            <p>
                Todos los miércoles de agosto.<br>
                18 a 20 h.
            </p>
        </article>

        <article class="cml-item">
            <h3>Dónde</h3>
            <p>
                Biblioteca Prof. Enrique Muttis.<br>
                Primera Junta 2451.
            </p>
        </article>

        <article class="cml-item">
            <h3>Modalidad</h3>
            <p>
                Actividad libre y gratuita.<br>
                Sin inscripción previa.
            </p>
        </article>

        <article class="cml-item">
            <h3>Expositores</h3>
            <p>
                Estanislao Giménez Corte<br>
                Daniel Paolantonio
            </p>
        </article>

    </section>



    <!-- SOBRE EL CURSO -->

    <section class="cml-texto">

        <h3>Sobre el curso</h3>

        <p>
            La propuesta invita a recorrer distintas composiciones musicales y literarias desde la mirada conjunta de un escritor y un pianista. A través de un viaje interpretativo se ofrecerán herramientas para comprender cómo dialogan ambas disciplinas, explorando aspectos como ritmo, melodía, armonía, narrativa, repetición, variación y clímax.
        </p>

        <p>
            Cada encuentro estará dedicado a un eje temático específico y combinará exposiciones conceptuales con el análisis de obras musicales y literarias, promoviendo la participación de los asistentes y el intercambio de diferentes lecturas e interpretaciones.
        </p>

    </section>



    <!-- PROGRAMA -->

    <section class="cml-programa">

        <h3>Programa</h3>

        <div class="cml-grid">

            <!-- CLASE 1 -->

            <article class="cml-card">


                

                <div class="cml-body">

                    <h4>
                        Clase 1: Movimiento continuo
                    </h4>

                    <p>
                        La ciudad como tópico poético y como forma sonora del devenir.
                    </p>

                    <button class="cml-toggle">

                        Ver programa

                        <span>+</span>

                    </button>

                </div>

                <div class="cml-content">

                    <div class="cml-content-inner">

                        <h5>Obras musicales</h5>

                        <ul>
                            <li>A Day in the Life – The Beatles</li>
                            <li>Movimiento Continuo – Astor Piazzolla</li>
                        </ul>

                        <h5>Obras literarias</h5>

                        <ul>
                            <li>Estampas Parisiennes – Charles Baudelaire</li>
                            <li>Hojas de Hierba – Walt Whitman</li>
                            <li>Poemas escogidos – Charles Bukowski</li>
                        </ul>

                    </div>

                </div>

            </article>



            <!-- CLASE 2 -->

            <article class="cml-card">



                <div class="cml-body">

                    <h4>
                        Clase 2: Alienación, soledad y totalitarismo
                    </h4>

                    <p>
                        Lo ajeno y aquello que el sujeto no logra controlar.
                    </p>

                    <button class="cml-toggle">

                        Ver programa

                        <span>+</span>

                    </button>

                </div>

                <div class="cml-content">

                    <div class="cml-content-inner">

                        <h5>Obras musicales</h5>

                        <ul>

                            <li>The Wall – Pink Floyd</li>

                            <li>Working Class Hero – John Lennon</li>

                            <li>Creep – Radiohead</li>

                        </ul>

                        <h5>Obras literarias</h5>

                        <ul>

                            <li>El proceso – Franz Kafka</li>

                            <li>La naranja mecánica – Anthony Burgess</li>

                        </ul>

                    </div>

                </div>

            </article>



            <!-- CLASE 3 -->

            <article class="cml-card">

         

                <div class="cml-body">

                    <h4>
                        Clase 3: Swing, improvisación y standards
                    </h4>

                    <p>
                        El jazz como forma musical y literaria.
                    </p>

                    <button class="cml-toggle">

                        Ver programa

                        <span>+</span>

                    </button>

                </div>

                <div class="cml-content">

                    <div class="cml-content-inner">

                        <h5>Obras musicales</h5>

                        <ul>

                            <li>Selección de obras de Charlie Parker</li>

                        </ul>

                        <h5>Obras literarias</h5>

                        <ul>

                            <li>Rayuela – Julio Cortázar</li>

                            <li>El perseguidor – Julio Cortázar</li>

                        </ul>

                    </div>

                </div>

            </article>



            <!-- CLASE 4 -->

            <article class="cml-card">

                
                <div class="cml-body">

                    <h4>
                        Clase 4: El laberinto como ingreso, extravío y fuga
                    </h4>

                    <p>
                        Un recorrido por Borges y Bach desde la literatura y la música.
                    </p>

                    <button class="cml-toggle">

                        Ver programa

                        <span>+</span>

                    </button>

                </div>

                <div class="cml-content">

                    <div class="cml-content-inner">

                        <h5>Obras musicales</h5>

                        <ul>

                            <li>El clave bien temperado – J. S. Bach</li>

                        </ul>

                        <h5>Obras literarias</h5>

                        <ul>

                            <li>Del rigor de la ciencia</li>

                            <li>La biblioteca de Babel</li>

                            <li>El jardín de senderos que se bifurcan</li>

                            <li>Los dos reyes y los dos laberintos</li>

                            <li>La casa de Asterión</li>

                        </ul>

                    </div>

                </div>

            </article>

        </div>

    </section>
       
       
<!-- EXPOSITORES -->

    <section class="cml-exp">

        <h3>Sobre los expositores</h3>

        <div class="cml-exp-grid">


            <!-- ESTANISLAO -->

            <article class="cml-prof">

                <div class="cml-prof-top">

                   

                    <div>

                        <h4>
                            Estanislao Giménez Corte
                        </h4>

                        <p>
                            Escritor, periodista, investigador y docente universitario.
                        </p>

                    </div>

                </div>

                <div class="cml-body">

                    <button class="cml-toggle">

                        Ver trayectoria

                        <span>+</span>

                    </button>

                </div>

                <div class="cml-content">

                    <div class="cml-content-inner">

                        <p>

                            Nació en Santa Fe en 1973. Es Doctor, Magíster y Licenciado en Comunicación Social por la Universidad Nacional de Rosario.

                        </p>

                        <p>

                            Se desempeña como editor y columnista del diario <strong>El Litoral</strong> y como profesor e investigador en la Universidad Católica de Santa Fe.

                        </p>

                        <p>

                            Publicó numerosos libros de poesía, ensayo e investigación, entre ellos <em>El afuera</em>, <em>Oceánica</em>, <em>Conversación junto al fuego</em> y <em>Borges periodista</em>.

                        </p>

                        <p>

                            Además dicta conferencias, seminarios, talleres y cursos en universidades, bibliotecas e instituciones culturales de todo el país.

                        </p>

                    </div>

                </div>

            </article>



            <!-- DANIEL -->

            <article class="cml-prof">

                <div class="cml-prof-top">

                   

                    <div>

                        <h4>
                            Daniel Paolantonio
                        </h4>

                        <p>
                            Pianista, músico y gestor cultural.
                        </p>

                    </div>

                </div>

                <div class="cml-body">

                    <button class="cml-toggle">

                        Ver trayectoria

                        <span>+</span>

                    </button>

                </div>

                <div class="cml-content">

                    <div class="cml-content-inner">

                        <p>

                            Nació en Santa Fe en 1977. Estudió piano clásico con Mario Montrul y Edith Valeri, y posteriormente profundizó su formación en tango junto a Nicolás Guerschberg.

                        </p>

                        <p>

                            Posee un Posgrado en Gestión Cultural y Comunicación (FLACSO) y desarrolló una intensa actividad artística interpretando diversos géneros musicales como tango, rock, folklore, reggae, pop y música sinfónica.

                        </p>

                        <p>

                            Integró durante varios años la Comisión Directiva del Mozarteum Santa Fe Filial Salzburgo y realizó presentaciones en Santa Fe, Rosario y Buenos Aires.

                        </p>

                        <p>

                            Actualmente combina su actividad musical con la gestión cultural y la coordinación de propuestas de formación artística.

                        </p>

                    </div>

                </div>

            </article>

        </div>

    </section>



    <!-- CIERRE -->

    <section class="cml-final">

        <h3>
            ¿Querés participar?
        </h3>

        <p>

            El curso es <strong>libre y gratuito</strong>, no requiere inscripción previa y está destinado a todas las personas interesadas en descubrir nuevas formas de relacionar la literatura y la música.

        </p>

        <div class="cml-datos">

            <div class="cml-dato">
                Miércoles de agosto
            </div>

            <div class="cml-dato">
                18 a 20 horas
            </div>

            <div class="cml-dato">
                Biblioteca Prof. Enrique Muttis
            </div>

            <div class="cml-dato">
                Primera Junta 2451
            </div>

        </div>

    </section>

</div>"},"elements":[],"widgetType":"html"},{"id":"4911554","elType":"widget","settings":{"html":"<script>
    
    document.addEventListener("DOMContentLoaded", function () {

    const botones = document.querySelectorAll(".cml-toggle");

    botones.forEach(function (boton) {

        boton.addEventListener("click", function () {

            const contenedor = this.closest(".cml-card, .cml-prof");
            const contenido = contenedor.querySelector(".cml-content");
            const icono = this.querySelector("span");


            if (!contenido) return;


            // Si está abierto
            if (contenido.classList.contains("activo")) {

                contenido.style.maxHeight = null;
                contenido.classList.remove("activo");

                icono.textContent = "+";

                this.classList.remove("abierto");


            } else {

                // Abrir
                contenido.classList.add("activo");
                contenido.style.maxHeight = contenido.scrollHeight + "px";

                icono.textContent = "−";

                this.classList.add("abierto");

            }

        });

    });


    // Ajusta alturas si cambia el tamaño de pantalla
    window.addEventListener("resize", function () {

        document.querySelectorAll(".cml-content.activo").forEach(function(contenido){

            contenido.style.maxHeight = contenido.scrollHeight + "px";

        });

    });

});

</script>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false}]

