<style>
  #fdl-programacion, #fdl-programacion * { box-sizing: border-box; }

  #fdl-programacion {
    background: #fff;
    width: 100%;
    line-height: 22px;
    font-family: 'Alegreya Sans', sans-serif;
    color: #333;
  }
  #fdl-programacion h1 { font-size: 22px; line-height: 22px; margin: 0; font-weight: 700; color: #002751; }
  #fdl-programacion h2 { font-size: 20px; line-height: 22px; margin: 0; font-weight: 700; color: #002751; }
  #fdl-programacion h3 { font-size: 18px; line-height: 22px; margin: 0; font-weight: 700; color: #002751; }
  #fdl-programacion p  { font-size: 14px; line-height: 22px; margin: 0; }

  #fdl-programacion select,
  #fdl-programacion input,
  #fdl-programacion button,
  #fdl-programacion a {
    font-family: inherit;
    font-size: 14px;
    line-height: 22px;
    color: #333;
  }

  /* ---------- Encabezado ---------- */
  .fdl-head {
    padding-bottom: 20px;
    margin-bottom: 24px;
    border-bottom: 1px solid rgba(0, 39, 81, .12);
  }
