    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-top: 10px;
  }
  .fdl-sub { color: #333; }

  .fdl-pdf-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    text-decoration: underline;
    text-underline-offset: 3px;
    padding: 8px 2px;
    white-space: nowrap;
    color: #002751;
    font-weight: 600;
    flex: 0 0 auto;
  }
  .fdl-icon { width: 17px; height: 17px; flex: 0 0 auto; }

  /* ---------- Sedes (5 columnas) ---------- */
  .fdl-sedes-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
    margin-bottom: 30px;
  }
  /* Son <div>, no <button>: evita heredar el estilo de botón del theme */
  .fdl-sede-card {
    text-align: left;
    cursor: pointer;
    background: #fff;
    border: 1px solid rgba(0, 39, 81, .12);
    border-radius: 4px;
