  }

  /* ---------- Listado agrupado ---------- */
  .fdl-dia-grupo { margin-bottom: 34px; }
  .fdl-dia-header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    margin-bottom: 16px;
  }
  .fdl-dia-header .fdl-dia-linea {
    flex: 1;
    height: 1px;
    background: rgba(0, 39, 81, .12);
  }

  /* Lista de actividades: sin caja ni borde de color, separadas por una línea */
  .fdl-card {
