    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .04em;
    margin-bottom: 4px;
  }
  .fdl-card-cat::before {
    content: "";
    width: 7px;
    height: 7px;
    border-radius: 2px;
    background: var(--cat-color, #002751);
    transform: rotate(45deg);
    flex: 0 0 auto;
  }

  .fdl-leyenda {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    margin: 10px 2px 18px !important;
  }
  .fdl-leyenda-item { display: inline-flex; align-items: center; gap: 7px; color: #333; }
