    width: 10px;
    height: 10px;
    border-radius: 2px;
    background: var(--cat-color);
    transform: rotate(45deg);
    flex: 0 0 auto;
  }

  .fdl-hora { display: block; font-weight: 700; color: #002751; margin-bottom: 4px; }
  .fdl-card-titulo { display: block; font-weight: 700; font-size: 15px; color: #333; margin-bottom: 4px; }
  .fdl-card-desc { color: #333; opacity: .85; margin-top: 2px !important; }
  .fdl-card-mod { color: #333; opacity: .85; margin-top: 4px !important; }
  .fdl-card-auspicia { color: #333; opacity: .7; margin-top: 2px !important; }
  .fdl-card-sede { display: block; margin-top: 8px !important; color: #333; opacity: .6; font-style: italic; }

  .fdl-empty {
    text-align: center;
    padding: 36px 20px;
    color: #333;
    opacity: .75;
    border: 1px dashed rgba(0, 39, 81, .25);
    border-radius: 4px;
    background: #f8fafc;
  }

  /* ---------- Responsive ---------- */
  @media (max-width: 1000px) {
    .fdl-sedes-grid { grid-template-columns: repeat(3, 1fr); }
    .fdl-layout { grid-template-columns: 32% 68%; gap: 20px; }
  }

  @media (max-width: 768px) {
    .fdl-layout { grid-template-columns: 1fr; }
    .fdl-sidebar { position: static; text-align: center; }
    .fdl-field { align-items: center; }
    .fdl-sede-card { align-items: center; text-align: center; }
    .fdl-count { text-align: center; }
    .fdl-leyenda { justify-content: center; }
    .fdl-filtro-sede { display: flex; width: fit-content; margin-left: auto !important; margin-right: auto !important; }
  }

  @media (max-width: 640px) {
    .fdl-sedes-grid { grid-template-columns: repeat(2, 1fr); }
    .fdl-head-row { flex-direction: column; align-items: stretch; }
    .fdl-stamp { align-self: stretch; }
  }

  @media (max-width: 420px) {
    .fdl-sedes-grid { grid-template-columns: 1fr; }
  }

  @media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
  }
</style>

<script>
(function () {
  "use strict";

  /* ===================================================================
     CATEGORÍAS: color e identificador de cada tipo de actividad.
       charla        -> Charlas / Conversatorios / Lecturas / Conferencias
       presentacion  -> Presentaciones / Aperturas / Entrega de premios
       actividad     -> Actividades / Talleres / Otros
     Usá la clave (charla / presentacion / actividad) en el campo
     "categoria" de cada actividad en ACTIVIDADES.
     =================================================================== */
