  };

  /* ===================================================================
     SEDES: dirección física de cada sede. El texto debe coincidir
     exactamente con el campo "sede" usado en ACTIVIDADES para que el
     conteo y el filtrado funcionen.
     =================================================================== */
  const SEDES = [
    { nombre: "Estación Belgrano", direccion: "Bv. Gálvez 1150" },
    { nombre: "Casa de la Cultura", direccion: "Bv. Gálvez 1274" },
