  ];

  /* ===================================================================
     ESPACIOS_CORTOS: la Estación Belgrano tiene varios espacios
     internos, así que en la línea de "dónde se realiza" de cada card
     mostramos "Estación Belgrano - <espacio corto>" en vez de repetir
     el nombre completo del auditorio. El resto de las sedes tiene un
     solo espacio, así que ahí alcanza con el nombre de la sede.
     =================================================================== */
  const ESPACIOS_CORTOS = {
    "Hall ingreso": "Hall de ingreso"
  };

  /* ===================================================================
     ESPACIOS_LABEL_COMPLETO: casos donde en vez de "Sede - corto"
     mostramos una etiqueta propia armada a mano (el nombre del espacio
     en sí, sin el prefijo de la sede).
     =================================================================== */
  const ESPACIOS_LABEL_COMPLETO = {
    "Auditorio Central Estela Figueroa - Sala 5": "Sala 5 Auditorio Central Estela Figueroa",
    "Auditorio 1 Juan Manuel Inchauspe": "Auditorio 1 Juan M. Inchauspe",
    "Auditorio 2 Beatriz Vallejos": "Auditorio 2 Beatriz Vallejos",
    "Brew Pub Estación Saer": "Brew Pub Estación Saer",
    "Sala Mercado Editorial": "Sala Mercado Editorial"
  };

  /* ===================================================================
     DIRECCIONES_ESPACIO: dirección o ubicación puntual de cada espacio,
     que se agrega con punto y seguido después del nombre que ya arma
     espacioLabel(). La clave debe coincidir exactamente con el nombre
     ya mostrado (el resultado de ESPACIOS_LABEL_COMPLETO, el de
     "Sede - corto", o el nombre de la sede a secas).
     =================================================================== */
  const DIRECCIONES_ESPACIO = {
    "Estación Belgrano": "Bv. Gálvez 1150",
    "Sala 5 Auditorio Central Estela Figueroa": "Planta Alta Estación Belgrano",
    "Auditorio 1 Juan M. Inchauspe": "Planta Alta Estación Belgrano",
    "Auditorio 2 Beatriz Vallejos": "Planta Alta Estación Belgrano",
    "Brew Pub Estación Saer": "Planta Baja Estación Belgrano",
    "Sala Mercado Editorial": "Balcarce 1635 - Mercado Progreso",
    "Casa de la Cultura": "Bv. Gálvez 1274",
    "Museo de Arte Contemporáneo de la UNL": "Boulevard Gálvez 1578",
    "Café Tokio Norte": "Rivadavia 2973",
    "Estación Belgrano - Hall de ingreso": "Boulevard Gálvez 1150"
  };

  function espacioLabel(a) {
    let base;
    if (ESPACIOS_LABEL_COMPLETO[a.espacioNombre]) {
      base = ESPACIOS_LABEL_COMPLETO[a.espacioNombre];
    } else {
      const corto = ESPACIOS_CORTOS[a.espacioNombre];
      base = corto ? `${a.sede} - ${corto}` : a.sede;
    }
    const direccion = DIRECCIONES_ESPACIO[base];
    return direccion ? `${base}. ${direccion}` : base;
  }

