  /* Orden de las opciones del filtro "Espacio" (no afecta el orden del listado, que va por horario) */
  const ORDEN_ESPACIO = { apertura: -1, principal: 0, auditorio1: 1, auditorio2: 2, externo: 3 };

  const $sedesGrid = document.getElementById('fdl-sedes-grid');
  const $leyenda = document.getElementById('fdl-leyenda');
  const $dia = document.getElementById('fdl-dia');
  const $espacio = document.getElementById('fdl-espacio');
  const $sede = document.getElementById('fdl-sede');
  const $buscar = document.getElementById('fdl-buscar');
  const $hoy = document.getElementById('fdl-hoy');
  const $limpiar = document.getElementById('fdl-limpiar');
  const $listado = document.getElementById('fdl-listado');
  const $empty = document.getElementById('fdl-empty');
  const $count = document.getElementById('fdl-count');
  const $filtroSede = document.getElementById('fdl-filtro-sede');

  function hoyISO() {
    const d = new Date();
    const pad = n => String(n).padStart(2, '0');
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  }

  function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  function renderLeyenda() {
    $leyenda.innerHTML = Object.values(CATEGORIAS).map(c => `
      <span class="fdl-leyenda-item">
        <span class="fdl-leyenda-punto" style="--cat-color:${c.color}"></span>
        <span>${escapeHtml(c.grupoLabel)}</span>
      </span>
    `).join('');
  }

  function renderSedes() {
    $sedesGrid.innerHTML = SEDES.map(s => {
      const cantidad = ACTIVIDADES.filter(a => a.sede === s.nombre).length;
      const texto = cantidad === 1 ? '1 actividad' : cantidad + ' actividades';
      return `
        <div class="fdl-sede-card" role="button" tabindex="0" data-sede="${escapeHtml(s.nombre)}" aria-pressed="false">
          <h3>${escapeHtml(s.nombre)}</h3>
          <p class="fdl-sede-dir">${escapeHtml(s.direccion)}</p>
          <p class="fdl-sede-count">${texto}</p>
        </div>
      `;
    }).join('');

    function activarSede(tarjeta) {
      const yaActiva = tarjeta.getAttribute('aria-pressed') === 'true';
      $sedesGrid.querySelectorAll('.fdl-sede-card').forEach(b => b.setAttribute('aria-pressed', 'false'));
      $sede.value = yaActiva ? 'todos' : tarjeta.dataset.sede;
      tarjeta.setAttribute('aria-pressed', yaActiva ? 'false' : 'true');
      render();
      $listado.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    $sedesGrid.querySelectorAll('.fdl-sede-card').forEach(tarjeta => {
      tarjeta.addEventListener('click', () => activarSede(tarjeta));
      tarjeta.addEventListener('keydown', (ev) => {
        if (ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar') {
          ev.preventDefault();
          activarSede(tarjeta);
        }
      });
    });
  }

  function sincronizarSedeCards() {
    $sedesGrid.querySelectorAll('.fdl-sede-card').forEach(b => {
      b.setAttribute('aria-pressed', b.dataset.sede === $sede.value ? 'true' : 'false');
    });
  }

  function poblarSelects() {
    const dias = [];
    const espacios = new Map(); // nombre de espacio -> grupo (para ordenar)
    const sedes = new Set();

    ACTIVIDADES.forEach(a => {
      if (!dias.find(d => d.fecha === a.fecha)) dias.push({ fecha: a.fecha, label: a.diaLabel });
      if (!espacios.has(a.espacioNombre)) espacios.set(a.espacioNombre, a.espacioGrupo);
      sedes.add(a.sede);
    });

    dias.sort((a, b) => a.fecha.localeCompare(b.fecha));
    dias.forEach(d => {
      const opt = document.createElement('option');
      opt.value = d.fecha;
      opt.textContent = d.label;
      $dia.appendChild(opt);
    });

    [...espacios.entries()]
      .sort((a, b) => {
        const diff = (ORDEN_ESPACIO[a[1]] ?? 99) - (ORDEN_ESPACIO[b[1]] ?? 99);
        return diff !== 0 ? diff : a[0].localeCompare(b[0]);
      })
      .forEach(([nombre]) => {
        const opt = document.createElement('option');
        opt.value = nombre;
        opt.textContent = nombre;
        $espacio.appendChild(opt);
      });

    [...sedes].sort().forEach(s => {
      const opt = document.createElement('option');
      opt.value = s;
      opt.textContent = s;
      $sede.appendChild(opt);
    });
  }

  function coincideBusqueda(a, texto) {
    if (!texto) return true;
    const t = texto.toLowerCase();
    return (a.nombre + ' ' + (a.descripcion || '') + ' ' + (a.moderacion || '') + ' ' + (a.auspiciantes || ''))
      .toLowerCase().includes(t);
  }

  function obtenerFiltros() {
    return {
      dia: $dia.value,
      espacio: $espacio.value,
      sede: $sede.value,
      texto: $buscar.value.trim(),
      soloHoy: $hoy.getAttribute('aria-pressed') === 'true'
    };
  }

  function filtrar() {
    const f = obtenerFiltros();
    const hoy = hoyISO();
    return ACTIVIDADES.filter(a => {
      if (f.soloHoy && a.fecha !== hoy) return false;
      if (!f.soloHoy && f.dia !== 'todos' && a.fecha !== f.dia) return false;
      if (f.espacio !== 'todos' && a.espacioNombre !== f.espacio) return false;
      if (f.sede !== 'todos' && a.sede !== f.sede) return false;
      if (!coincideBusqueda(a, f.texto)) return false;
      return true;
    });
  }

  function agrupar(actividades) {
    const porDia = new Map();
    actividades.forEach(a => {
      if (!porDia.has(a.fecha)) porDia.set(a.fecha, { label: a.diaLabel, items: [] });
      porDia.get(a.fecha).items.push(a);
    });

    return [...porDia.entries()]
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([fecha, data]) => {
        const items = [...data.items].sort((a, b) => {
          const diff = a.hora.localeCompare(b.hora);
          return diff !== 0 ? diff : a.espacioNombre.localeCompare(b.espacioNombre);
        });
        return { fecha, label: data.label, items };
      });
  }

  function render() {
    sincronizarSedeCards();

    const resultado = filtrar();
    const grupos = agrupar(resultado);
    const f = obtenerFiltros();

    $count.textContent = resultado.length === 1
      ? '1 actividad encontrada'
      : resultado.length + ' actividades encontradas';

    if (f.sede !== 'todos') {
      $filtroSede.hidden = false;
      $filtroSede.textContent = `Viendo actividades en ${f.sede}`;
    } else {
      $filtroSede.hidden = true;
      $filtroSede.textContent = '';
    }

    $empty.hidden = resultado.length !== 0;
    $listado.innerHTML = '';

    grupos.forEach(dia => {
      const diaWrap = document.createElement('section');
      diaWrap.className = 'fdl-dia-grupo';
      diaWrap.innerHTML = `
        <div class="fdl-dia-header">
          <h2>${escapeHtml(dia.label)}</h2>
          <div class="fdl-dia-linea"></div>
        </div>
      `;

      const listaWrap = document.createElement('div');
      listaWrap.className = 'fdl-dia-lista';

      listaWrap.innerHTML = dia.items.map(a => {
        const cat = CATEGORIAS[a.categoria] || null;
        const colorCard = a.colorOverride || (cat ? cat.color : null);
        const catStyle = colorCard ? ` style="--cat-color:${colorCard}"` : '';
        const textoEtiqueta = a.etiqueta || (cat ? cat.grupoLabel : '');
        const catBadge = textoEtiqueta ? `<span class="fdl-card-cat">${escapeHtml(textoEtiqueta)}</span>` : '';
        const lugar = espacioLabel(a);
        return `
        <div class="fdl-card"${catStyle}>
          ${catBadge}
          <span class="fdl-hora">${escapeHtml(a.hora)} horas</span>
          <p class="fdl-card-titulo">${escapeHtml(a.nombre)}</p>
          ${a.descripcion ? `<p class="fdl-card-desc">${escapeHtml(a.descripcion)}</p>` : ''}
          ${a.moderacion ? `<p class="fdl-card-mod">${escapeHtml(a.moderacion)}</p>` : ''}
          ${a.auspiciantes ? `<p class="fdl-card-auspicia">${escapeHtml(a.auspiciantes)}</p>` : ''}
          <span class="fdl-card-sede">${escapeHtml(lugar)}</span>
        </div>
      `;
      }).join('');

      diaWrap.appendChild(listaWrap);

      $listado.appendChild(diaWrap);
    });
  }

  /* ---------- Eventos ---------- */
  $dia.addEventListener('change', () => { $hoy.setAttribute('aria-pressed', 'false'); render(); });
  $espacio.addEventListener('change', render);
  $sede.addEventListener('change', render);
  $buscar.addEventListener('input', render);

  $hoy.addEventListener('click', () => {
    const activo = $hoy.getAttribute('aria-pressed') === 'true';
    $hoy.setAttribute('aria-pressed', activo ? 'false' : 'true');
    if (!activo) $dia.value = 'todos';
    render();
  });

  $limpiar.addEventListener('click', () => {
    $dia.value = 'todos';
    $espacio.value = 'todos';
    $sede.value = 'todos';
    $buscar.value = '';
    $hoy.setAttribute('aria-pressed', 'false');
    render();
  });

  renderLeyenda();
  renderSedes();
  poblarSelects();
  render();
})();
</script>","_element_width":"inherit","_element_custom_width":{"unit":"%","size":88.551},"_element_custom_width_mobile":{"unit":"%","size":"","sizes":[]}},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false}]

{"timeout":1792682219,"value":{"content":"		<section class="elementor-section elementor-top-section elementor-element elementor-element-8ea3c77 elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="8ea3c77" data-element_type="section" data-e-type="section">
						<div class="elementor-container elementor-column-gap-default">
					<div class="elementor-column elementor-col-100 elementor-top-column elementor-element elementor-element-d919515" data-id="d919515" data-element_type="column" data-e-type="column">
			<div class="elementor-widget-wrap elementor-element-populated">
						<div class="elementor-element elementor-element-dfaeb56 elementor-widget__width-inherit elementor-widget elementor-widget-html" data-id="dfaeb56" data-element_type="widget" data-e-type="widget" data-widget_type="html.default">
				<div class="elementor-widget-container">
					<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Alegreya+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap" rel="stylesheet">

<div class="fdl-wrap" id="fdl-programacion">

  <!-- ===================== ENCABEZADO ===================== -->
  <header class="fdl-head">
    <h1 class="fdl-title">Programación completa XXXII Feria del Libro - Santa Fe</h1>
    <div class="fdl-head-row">
      <p class="fdl-sub">Buscá por día, espacio o sede, o mirá qué pasa hoy.</p>
      <!-- PDF-LINK: reemplazar href por la ruta real del PDF -->
      <a class="fdl-pdf-btn" href="https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/08/FDL2026_programacion-completa.pdf" download
         aria-label="Descargar la programación completa en PDF">
        <svg class="fdl-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M12 3v12m0 0-4.5-4.5M12 15l4.5-4.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
          <path d="M4.5 16.5V19a1.5 1.5 0 0 0 1.5 1.5h12A1.5 1.5 0 0 0 19.5 19v-2.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        <span>Descargar programación en PDF</span>
      </a>
    </div>
  </header>

  <!-- ===================== SEDES (5 columnas, antes del buscador) ===================== -->
  <div class="fdl-sedes-grid" id="fdl-sedes-grid" aria-label="Filtrar por sede"></div>

  <!-- ===================== CONTENIDO: FILTROS (25%) + LISTADO (75%) ===================== -->
  <div class="fdl-layout">

    <!-- FILTROS: apilados y estáticos -->
    <aside class="fdl-sidebar" aria-label="Buscador y filtros">
      <button type="button" id="fdl-hoy" class="fdl-stamp" aria-pressed="false">HOY</button>

      <div class="fdl-field">
        <label for="fdl-buscar">Buscar</label>
        <input type="search" id="fdl-buscar" placeholder="Título, autor, tema…" autocomplete="off">
      </div>

      <div class="fdl-field">
        <label for="fdl-dia">Día</label>
        <select id="fdl-dia">
          <option value="todos">Todos los días</option>
        </select>
      </div>

      <div class="fdl-field">
        <label for="fdl-espacio">Espacio</label>
        <select id="fdl-espacio">
          <option value="todos">Todos los espacios</option>
        </select>
      </div>

      <div class="fdl-field">
        <label for="fdl-sede">Sede</label>
        <select id="fdl-sede">
          <option value="todos">Todas las sedes</option>
        </select>
      </div>

      <button type="button" id="fdl-limpiar" class="fdl-clear">Limpiar filtros</button>
    </aside>

    <!-- LISTADO -->
    <div class="fdl-main">
      <p class="fdl-count" id="fdl-count" aria-live="polite"></p>
      <div class="fdl-leyenda" id="fdl-leyenda"></div>
      <p class="fdl-filtro-sede" id="fdl-filtro-sede" aria-live="polite" hidden></p>

      <div id="fdl-listado" class="fdl-listado" aria-live="polite"></div>

      <p class="fdl-empty" id="fdl-empty" hidden>
        No encontramos actividades con esos filtros. Probá limpiar la búsqueda.
      </p>
    </div>
  </div>
</div>

<style>
  #fdl-programacion, #fdl-programacion * { box-sizing: border-box; }

  #fdl-programacion {
    background: #fff;
    width: 100%;
    line-height: 22px;
    font-family: 'Alegreya Sans', sans-serif;
    color: #333;
  }
  #fdl-programacion h1 { font-size: 22px; line-height: 22px; margin: 0; font-weight: 700; color: #002751; }
  #fdl-programacion h2 { font-size: 20px; line-height: 22px; margin: 0; font-weight: 700; color: #002751; }
  #fdl-programacion h3 { font-size: 18px; line-height: 22px; margin: 0; font-weight: 700; color: #002751; }
  #fdl-programacion p  { font-size: 14px; line-height: 22px; margin: 0; }

  #fdl-programacion select,
  #fdl-programacion input,
  #fdl-programacion button,
  #fdl-programacion a {
    font-family: inherit;
    font-size: 14px;
    line-height: 22px;
    color: #333;
  }

  /* ---------- Encabezado ---------- */
  .fdl-head {
    padding-bottom: 20px;
    margin-bottom: 24px;
    border-bottom: 1px solid rgba(0, 39, 81, .12);
  }
  .fdl-head-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-top: 10px;
  }
  .fdl-sub { color: #333; }

  .fdl-pdf-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    text-decoration: underline;
    text-underline-offset: 3px;
    padding: 8px 2px;
    white-space: nowrap;
    color: #002751;
    font-weight: 600;
    flex: 0 0 auto;
  }
  .fdl-icon { width: 17px; height: 17px; flex: 0 0 auto; }

  /* ---------- Sedes (5 columnas) ---------- */
  .fdl-sedes-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
    margin-bottom: 30px;
  }
  /* Son <div>, no <button>: evita heredar el estilo de botón del theme */
  .fdl-sede-card {
    text-align: left;
    cursor: pointer;
    background: #fff;
    border: 1px solid rgba(0, 39, 81, .12);
    border-radius: 4px;
    padding: 14px;
    display: flex;
    flex-direction: column;
    gap: 4px;
  }
  .fdl-sede-card:hover {
    border-color: rgba(0, 39, 81, .35);
  }
  .fdl-sede-card[aria-pressed="true"] {
    border-color: #002751;
    border-width: 2px;
    background: #f8fafc;
  }
  .fdl-sede-card .fdl-sede-dir { color: #333; opacity: .8; }
  .fdl-sede-card .fdl-sede-count { color: #002751; opacity: .85; margin-top: 4px !important; font-weight: 600; }

  /* ---------- Layout: sidebar de filtros (25%) + listado (75%) ---------- */
  .fdl-layout {
    display: grid;
    grid-template-columns: 25% 75%;
    gap: 28px;
    align-items: start;
  }
  .fdl-main { min-width: 0; }

  /* ---------- Sidebar de filtros: apilados y estáticos ---------- */
  .fdl-sidebar {
    position: static;
    display: flex;
    flex-direction: column;
    gap: 14px;
    border: 1px solid rgba(0, 39, 81, .12);
    border-radius: 4px;
    padding: 18px;
    background: #fff;
  }
  .fdl-field { display: flex; flex-direction: column; gap: 5px; width: 100%; }
  .fdl-field label { font-size: 11.5px; text-transform: uppercase; letter-spacing: .05em; color: #002751; font-weight: 600; }
  .fdl-field input, .fdl-field select {
    width: 100%;
    padding: 8px 10px;
    border: 1px solid rgba(0, 39, 81, .12);
    border-radius: 4px;
    background: #fff;
    color: #333;
  }

  .fdl-field input:focus-visible,
  .fdl-field select:focus-visible,
  .fdl-pdf-btn:focus-visible,
  .fdl-stamp:focus-visible,
  .fdl-clear:focus-visible,
  .fdl-sede-card:focus-visible {
    outline: 2px solid #002751;
    outline-offset: 2px;
  }

  .fdl-clear {
    width: 100%;
    border: 1px solid rgba(0, 39, 81, .12);
    background: #fff;
    padding: 10px 14px;
    border-radius: 4px;
    font-weight: 600;
    color: #002751;
    cursor: pointer;
  }
  .fdl-clear:hover { border-color: #002751; }

  /* Botón "Hoy" */
  .fdl-stamp {
    width: 100%;
    text-align: center;
    border: 1px solid rgba(0, 39, 81, .45);
    background: #fff;
    color: #002751;
    padding: 10px 16px;
    border-radius: 4px;
    font-weight: 700;
    letter-spacing: .04em;
    cursor: pointer;
  }
  #fdl-programacion .fdl-stamp[aria-pressed="true"] {
  border-style: solid;
  background: #002751;
  color: #fff;
}

  .fdl-count { color: #333; opacity: .75; margin: 0 2px 18px !important; }

  .fdl-filtro-sede {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: #002751;
    font-weight: 700;
    border: 1px solid rgba(0, 39, 81, .15);
    border-radius: 4px;
    background: #f8fafc;
    padding: 8px 14px;
    margin: -6px 2px 20px !important;
  }
  .fdl-filtro-sede::before {
    content: "";
    width: 8px;
    height: 8px;
    border-radius: 2px;
    background: #002751;
    transform: rotate(45deg);
    flex: 0 0 auto;
  }

  /* ---------- Listado agrupado ---------- */
  .fdl-dia-grupo { margin-bottom: 34px; }
  .fdl-dia-header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    margin-bottom: 16px;
  }
  .fdl-dia-header .fdl-dia-linea {
    flex: 1;
    height: 1px;
    background: rgba(0, 39, 81, .12);
  }

  /* Lista de actividades: sin caja ni borde de color, separadas por una línea */
  .fdl-card {
    padding: 16px 2px;
    border-bottom: 1px solid rgba(0, 39, 81, .12);
  }
  .fdl-dia-lista .fdl-card:last-child { border-bottom: none; }

  .fdl-card-cat {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: var(--cat-color, #002751);
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .04em;
    margin-bottom: 4px;
  }
  .fdl-card-cat::before {
    content: "";
    width: 7px;
    height: 7px;
    border-radius: 2px;
    background: var(--cat-color, #002751);
    transform: rotate(45deg);
    flex: 0 0 auto;
  }

  .fdl-leyenda {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    margin: 10px 2px 18px !important;
  }
  .fdl-leyenda-item { display: inline-flex; align-items: center; gap: 7px; color: #333; }
  .fdl-leyenda-punto {
    width: 10px;
    height: 10px;
    border-radius: 2px;
    background: var(--cat-color);
    transform: rotate(45deg);
    flex: 0 0 auto;
  }

  .fdl-hora { display: block; font-weight: 700; color: #002751; margin-bottom: 4px; }
  .fdl-card-titulo { display: block; font-weight: 700; font-size: 15px; color: #333; margin-bottom: 4px; }
  .fdl-card-desc { color: #333; opacity: .85; margin-top: 2px !important; }
  .fdl-card-mod { color: #333; opacity: .85; margin-top: 4px !important; }
  .fdl-card-auspicia { color: #333; opacity: .7; margin-top: 2px !important; }
  .fdl-card-sede { display: block; margin-top: 8px !important; color: #333; opacity: .6; font-style: italic; }

  .fdl-empty {
    text-align: center;
    padding: 36px 20px;
    color: #333;
    opacity: .75;
    border: 1px dashed rgba(0, 39, 81, .25);
    border-radius: 4px;
    background: #f8fafc;
  }

  /* ---------- Responsive ---------- */
  @media (max-width: 1000px) {
    .fdl-sedes-grid { grid-template-columns: repeat(3, 1fr); }
    .fdl-layout { grid-template-columns: 32% 68%; gap: 20px; }
  }

  @media (max-width: 768px) {
    .fdl-layout { grid-template-columns: 1fr; }
    .fdl-sidebar { position: static; text-align: center; }
    .fdl-field { align-items: center; }
    .fdl-sede-card { align-items: center; text-align: center; }
    .fdl-count { text-align: center; }
    .fdl-leyenda { justify-content: center; }
    .fdl-filtro-sede { display: flex; width: fit-content; margin-left: auto !important; margin-right: auto !important; }
  }

  @media (max-width: 640px) {
    .fdl-sedes-grid { grid-template-columns: repeat(2, 1fr); }
    .fdl-head-row { flex-direction: column; align-items: stretch; }
    .fdl-stamp { align-self: stretch; }
  }

  @media (max-width: 420px) {
    .fdl-sedes-grid { grid-template-columns: 1fr; }
  }

  @media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
  }
</style>

<script>
(function () {
  "use strict";

  /* ===================================================================
     CATEGORÍAS: color e identificador de cada tipo de actividad.
       charla        -> Charlas / Conversatorios / Lecturas / Conferencias
       presentacion  -> Presentaciones / Aperturas / Entrega de premios
       actividad     -> Actividades / Talleres / Otros
     Usá la clave (charla / presentacion / actividad) en el campo
     "categoria" de cada actividad en ACTIVIDADES.
     =================================================================== */
  const CATEGORIAS = {
    charla:       { grupoLabel: "Charla / Conversatorio / Lectura",   color: "#7e8757" },
    presentacion: { grupoLabel: "Presentación / Entrega de premios",  color: "#8b80b9" },
    actividad:    { grupoLabel: "Actividad / Taller / Otros",         color: "#f27f4c" }
  };

  /* ===================================================================
     SEDES: dirección física de cada sede. El texto debe coincidir
     exactamente con el campo "sede" usado en ACTIVIDADES para que el
     conteo y el filtrado funcionen.
     =================================================================== */
  const SEDES = [
    { nombre: "Estación Belgrano", direccion: "Bv. Gálvez 1150" },
    { nombre: "Casa de la Cultura", direccion: "Bv. Gálvez 1274" },
    { nombre: "Mercado Progreso", direccion: "Balcarce 1635" },
    { nombre: "Museo de Arte Contemporáneo de la UNL", direccion: "Bv. Gálvez 1578" },
    { nombre: "Café Tokio Norte", direccion: "Rivadavia 2973" }
  ];

  /* ===================================================================
     ESPACIOS_CORTOS: la Estación Belgrano tiene varios espacios
     internos, así que en la línea de "dónde se realiza" de cada card
     mostramos "Estación Belgrano - <espacio corto>" en vez de repetir
     el nombre completo del auditorio. El resto de las sedes tiene un
     solo espacio, así que ahí alcanza con el nombre de la sede.
     =================================================================== */
  const ESPACIOS_CORTOS = {
    "Hall ingreso": "Hall de ingreso"
  };

  /* ===================================================================
     ESPACIOS_LABEL_COMPLETO: casos donde en vez de "Sede - corto"
     mostramos una etiqueta propia armada a mano (el nombre del espacio
     en sí, sin el prefijo de la sede).
     =================================================================== */
  const ESPACIOS_LABEL_COMPLETO = {
    "Auditorio Central Estela Figueroa - Sala 5": "Sala 5 Auditorio Central Estela Figueroa",
    "Auditorio 1 Juan Manuel Inchauspe": "Auditorio 1 Juan M. Inchauspe",
    "Auditorio 2 Beatriz Vallejos": "Auditorio 2 Beatriz Vallejos",
    "Brew Pub Estación Saer": "Brew Pub Estación Saer",
    "Sala Mercado Editorial": "Sala Mercado Editorial"
  };

  /* ===================================================================
     DIRECCIONES_ESPACIO: dirección o ubicación puntual de cada espacio,
     que se agrega con punto y seguido después del nombre que ya arma
     espacioLabel(). La clave debe coincidir exactamente con el nombre
     ya mostrado (el resultado de ESPACIOS_LABEL_COMPLETO, el de
     "Sede - corto", o el nombre de la sede a secas).
     =================================================================== */
  const DIRECCIONES_ESPACIO = {
    "Estación Belgrano": "Bv. Gálvez 1150",
    "Sala 5 Auditorio Central Estela Figueroa": "Planta Alta Estación Belgrano",
    "Auditorio 1 Juan M. Inchauspe": "Planta Alta Estación Belgrano",
    "Auditorio 2 Beatriz Vallejos": "Planta Alta Estación Belgrano",
    "Brew Pub Estación Saer": "Planta Baja Estación Belgrano",
    "Sala Mercado Editorial": "Balcarce 1635 - Mercado Progreso",
    "Casa de la Cultura": "Bv. Gálvez 1274",
    "Museo de Arte Contemporáneo de la UNL": "Boulevard Gálvez 1578",
    "Café Tokio Norte": "Rivadavia 2973",
    "Estación Belgrano - Hall de ingreso": "Boulevard Gálvez 1150"
  };

  function espacioLabel(a) {
    let base;
    if (ESPACIOS_LABEL_COMPLETO[a.espacioNombre]) {
      base = ESPACIOS_LABEL_COMPLETO[a.espacioNombre];
    } else {
      const corto = ESPACIOS_CORTOS[a.espacioNombre];
      base = corto ? `${a.sede} - ${corto}` : a.sede;
    }
    const direccion = DIRECCIONES_ESPACIO[base];
    return direccion ? `${base}. ${direccion}` : base;
  }

  /* ===================================================================
     DATOS: programación oficial XXXII Feria del Libro de Santa Fe
     (extraída de progCompleta.docx).
     Campos de cada actividad:
       fecha        -> "AAAA-MM-DD" (para que "Hoy" funcione solo)
       diaLabel     -> texto a mostrar, ej: "Miércoles 26"
       espacioGrupo -> uno de: "apertura" | "principal" | "auditorio1" | "auditorio2" | "externo"
                       (define el orden de aparición dentro del día)
       espacioNombre-> texto a mostrar, ej: "Auditorio Central Estela Figueroa - Sala 5"
       sede         -> debe coincidir con un "nombre" de SEDES
       categoria    -> "charla" | "presentacion" | "actividad" (define el color)
       etiqueta     -> texto exacto a mostrar como tipo de actividad
       hora         -> "HH:MM" (24 h, para poder ordenar)
       nombre       -> nombre de la actividad/obra
       descripcion  -> opcional: autores, participantes, detalle breve
       moderacion   -> opcional: "Modera/Moderan/Coordina/Presenta: ..."
       auspiciantes -> opcional: editorial, organiza, invita, facultad, etc.
     =================================================================== */
  const ACTIVIDADES = [
    /* ---------- MIÉRCOLES 26 DE AGOSTO ---------- */
    {
      fecha: "2026-08-26", diaLabel: "Miércoles 26",
      espacioGrupo: "apertura", espacioNombre: "Apertura de la Feria",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Apertura", hora: "15:00",
      nombre: "Apertura",
      descripcion: "", moderacion: "", auspiciantes: ""
    },
    {
      fecha: "2026-08-26", diaLabel: "Miércoles 26",
      espacioGrupo: "principal", espacioNombre: "Auditorio Central Estela Figueroa - Sala 5",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Presentación", hora: "16:00",
      nombre: "Intercambio de miradas",
      descripcion: "Presentaciones: Fin y principio, de Alicia Vincenzini; Un mensajito que diga que estás bien, de Juan Pablo Bagnarol; y Recuento de fantasmas, de Laura Hormaeche",
      moderacion: "Modera: Mariano Peralta",
      auspiciantes: "Halley Ediciones y Ediciones De l'aire"
    },
    {
      fecha: "2026-08-26", diaLabel: "Miércoles 26",
      espacioGrupo: "principal", espacioNombre: "Auditorio Central Estela Figueroa - Sala 5",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Presentación", hora: "17:00",
      nombre: "Pequeños grandes escritores y Aventuleo",
      descripcion: "Antologías de cuentos: Pequeños grandes escritores, de nivel primario y secundario, y Aventuleo, del nivel inicial",
      moderacion: "", auspiciantes: "Secretaría de Educación de la Municipalidad de Santa Fe"
    },
    {
      fecha: "2026-08-26", diaLabel: "Miércoles 26",
      espacioGrupo: "principal", espacioNombre: "Auditorio Central Estela Figueroa - Sala 5",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Apertura", hora: "19:00",
      colorOverride: "#002751",
      nombre: "Apertura de la XXXII Feria del Libro",
      descripcion: "Conferencia: Entre experiencia e imaginación, a cargo de Marilyn Contardi",
      moderacion: "", auspiciantes: ""
    },
    {
      fecha: "2026-08-26", diaLabel: "Miércoles 26",
      espacioGrupo: "auditorio1", espacioNombre: "Auditorio 1 Juan Manuel Inchauspe",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Presentación", hora: "16:00",
      nombre: "Sellado en mi alma",
      descripcion: "de Maria Gabriela Wellig",
      moderacion: "Modera: María Belén Gamboglia",
      auspiciantes: "Genco servicios editoriales (Reconquista)"
    },
    {
      fecha: "2026-08-26", diaLabel: "Miércoles 26",
      espacioGrupo: "auditorio1", espacioNombre: "Auditorio 1 Juan Manuel Inchauspe",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Presentación", hora: "17:00",
      nombre: "La Vera Cruz de Santa Fe",
      descripcion: "de Norma Battú",
      moderacion: "Modera: Jorge Terpin",
      auspiciantes: "Editorial Librería Cívica"
    },
    {
      fecha: "2026-08-26", diaLabel: "Miércoles 26",
      espacioGrupo: "auditorio1", espacioNombre: "Auditorio 1 Juan Manuel Inchauspe",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Presentación", hora: "18:00",
      nombre: "Infancias, violencias y derechos",
      descripcion: "de Julia Grinberg y Carla Villalta (comp.)",
      moderacion: "Moderan: Judith Galetti y Mariángeles Guerrero",
      auspiciantes: "Organizan: Defensoría de Niños, Niñas y Adolescentes; Mesa institucional causa Laguna Paiva II y Secretaría de Derechos Humanos"
    },
    {
      fecha: "2026-08-26", diaLabel: "Miércoles 26",
      espacioGrupo: "auditorio1", espacioNombre: "Auditorio 1 Juan Manuel Inchauspe",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Presentación", hora: "19:00",
