      espacioGrupo: "auditorio2", espacioNombre: "Auditorio 2 Beatriz Vallejos",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Presentación", hora: "20:00",
      nombre: "Nacen rosas en un desierto de cenizas",
      descripcion: "de Lorena Nittoli",
