    },
    {
      fecha: "2026-08-30", diaLabel: "Domingo 30",
      espacioGrupo: "externo", espacioNombre: "Brew Pub Estación Saer",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Presentación", hora: "17:00",
