    },
    {
      fecha: "2026-08-30", diaLabel: "Domingo 30",
      espacioGrupo: "externo", espacioNombre: "Brew Pub Estación Saer",
      sede: "Estación Belgrano", categoria: "presentacion", etiqueta: "Presentación", hora: "19:00",
      nombre: "Colección Historia Social de la Canción",
      descripcion: "Silvia Majul, Sergio Arboleya, Héctor Sánchez y Mariano Suárez",
