    {
      fecha: "2026-08-30", diaLabel: "Domingo 30",
      espacioGrupo: "externo", espacioNombre: "Museo de Arte Contemporáneo de la UNL",
      sede: "Museo de Arte Contemporáneo de la UNL", categoria: "charla", etiqueta: "Conversatorio", hora: "15:00",
      nombre: "Pensamientos y sentimientos que devienen páginas",
      descripcion: "Poetas y narradores",
      moderacion: "", auspiciantes: "Asoc. Civil Construir Futuro y Biblioteca de Alto Verde"
    },
    {
      fecha: "2026-08-30", diaLabel: "Domingo 30",
      espacioGrupo: "externo", espacioNombre: "Museo de Arte Contemporáneo de la UNL",
      sede: "Museo de Arte Contemporáneo de la UNL", categoria: "charla", etiqueta: "Conversatorio", hora: "17:00",
      nombre: "El psicoanálisis en la escritura. La publicación como acto",
      descripcion: "con Ignacio Neffen",
