      espacioGrupo: "externo", espacioNombre: "Casa de la Cultura",
      sede: "Casa de la Cultura", categoria: "charla", etiqueta: "Conversatorio", hora: "16:00",
      nombre: "Cuando la poesía se hizo decreto: 40 años de Acebal, Capital Provincial de la Poesía",
      descripcion: "",
      moderacion: "", auspiciantes: "Organizan: Asociación de arte y cultura y Municipio de Acebal"
    },
    {
      fecha: "2026-08-30", diaLabel: "Domingo 30",
      espacioGrupo: "externo", espacioNombre: "Casa de la Cultura",
      sede: "Casa de la Cultura", categoria: "charla", etiqueta: "Lectura", hora: "17:00",
      nombre: "El Juego de las Palabras",
      descripcion: "",
      moderacion: "", auspiciantes: "Organiza: Grupo literario Contrapunto Cultural"
    },
    {
      fecha: "2026-08-30", diaLabel: "Domingo 30",
      espacioGrupo: "externo", espacioNombre: "Casa de la Cultura",
      sede: "Casa de la Cultura", categoria: "actividad", etiqueta: "Otros", hora: "18:00",
      nombre: "La orilla infinita",
      descripcion: "Canciones y retroproyección sobre poemas de Juan L. Ortiz, con Sebastián Macchi y Agustina Bianchi",
      moderacion: "", auspiciantes: ""
    }
  ];

  /* Orden de las opciones del filtro "Espacio" (no afecta el orden del listado, que va por horario) */
  const ORDEN_ESPACIO = { apertura: -1, principal: 0, auditorio1: 1, auditorio2: 2, externo: 3 };

  const $sedesGrid = document.getElementById('fdl-sedes-grid');
  const $leyenda = document.getElementById('fdl-leyenda');
  const $dia = document.getElementById('fdl-dia');
  const $espacio = document.getElementById('fdl-espacio');
  const $sede = document.getElementById('fdl-sede');
  const $buscar = document.getElementById('fdl-buscar');
  const $hoy = document.getElementById('fdl-hoy');
  const $limpiar = document.getElementById('fdl-limpiar');
  const $listado = document.getElementById('fdl-listado');
  const $empty = document.getElementById('fdl-empty');
  const $count = document.getElementById('fdl-count');
  const $filtroSede = document.getElementById('fdl-filtro-sede');

  function hoyISO() {
    const d = new Date();
    const pad = n => String(n).padStart(2, '0');
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  }

  function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
  }

  function renderLeyenda() {
    $leyenda.innerHTML = Object.values(CATEGORIAS).map(c => `
      <span class="fdl-leyenda-item">
        <span class="fdl-leyenda-punto" style="--cat-color:${c.color}"></span>
        <span>${escapeHtml(c.grupoLabel)}</span>
      </span>
    `).join('');
  }

  function renderSedes() {
    $sedesGrid.innerHTML = SEDES.map(s => {
      const cantidad = ACTIVIDADES.filter(a => a.sede === s.nombre).length;
      const texto = cantidad === 1 ? '1 actividad' : cantidad + ' actividades';
      return `
        <div class="fdl-sede-card" role="button" tabindex="0" data-sede="${escapeHtml(s.nombre)}" aria-pressed="false">
          <h3>${escapeHtml(s.nombre)}</h3>
          <p class="fdl-sede-dir">${escapeHtml(s.direccion)}</p>
          <p class="fdl-sede-count">${texto}</p>
        </div>
      `;
    }).join('');

    function activarSede(tarjeta) {
      const yaActiva = tarjeta.getAttribute('aria-pressed') === 'true';
      $sedesGrid.querySelectorAll('.fdl-sede-card').forEach(b => b.setAttribute('aria-pressed', 'false'));
      $sede.value = yaActiva ? 'todos' : tarjeta.dataset.sede;
      tarjeta.setAttribute('aria-pressed', yaActiva ? 'false' : 'true');
      render();
      $listado.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    $sedesGrid.querySelectorAll('.fdl-sede-card').forEach(tarjeta => {
      tarjeta.addEventListener('click', () => activarSede(tarjeta));
      tarjeta.addEventListener('keydown', (ev) => {
        if (ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar') {
          ev.preventDefault();
          activarSede(tarjeta);
        }
      });
    });
  }

  function sincronizarSedeCards() {
    $sedesGrid.querySelectorAll('.fdl-sede-card').forEach(b => {
      b.setAttribute('aria-pressed', b.dataset.sede === $sede.value ? 'true' : 'false');
    });
  }

  function poblarSelects() {
    const dias = [];
    const espacios = new Map(); // nombre de espacio -> grupo (para ordenar)
    const sedes = new Set();

    ACTIVIDADES.forEach(a => {
      if (!dias.find(d => d.fecha === a.fecha)) dias.push({ fecha: a.fecha, label: a.diaLabel });
      if (!espacios.has(a.espacioNombre)) espacios.set(a.espacioNombre, a.espacioGrupo);
      sedes.add(a.sede);
    });

    dias.sort((a, b) => a.fecha.localeCompare(b.fecha));
    dias.forEach(d => {
      const opt = document.createElement('option');
      opt.value = d.fecha;
      opt.textContent = d.label;
      $dia.appendChild(opt);
    });

    [...espacios.entries()]
      .sort((a, b) => {
        const diff = (ORDEN_ESPACIO[a[1]] ?? 99) - (ORDEN_ESPACIO[b[1]] ?? 99);
        return diff !== 0 ? diff : a[0].localeCompare(b[0]);
      })
      .forEach(([nombre]) => {
        const opt = document.createElement('option');
        opt.value = nombre;
        opt.textContent = nombre;
        $espacio.appendChild(opt);
      });

    [...sedes].sort().forEach(s => {
      const opt = document.createElement('option');
      opt.value = s;
      opt.textContent = s;
      $sede.appendChild(opt);
    });
  }

  function coincideBusqueda(a, texto) {
    if (!texto) return true;
    const t = texto.toLowerCase();
    return (a.nombre + ' ' + (a.descripcion || '') + ' ' + (a.moderacion || '') + ' ' + (a.auspiciantes || ''))
      .toLowerCase().includes(t);
  }

  function obtenerFiltros() {
    return {
      dia: $dia.value,
      espacio: $espacio.value,
      sede: $sede.value,
      texto: $buscar.value.trim(),
      soloHoy: $hoy.getAttribute('aria-pressed') === 'true'
    };
  }

  function filtrar() {
    const f = obtenerFiltros();
    const hoy = hoyISO();
    return ACTIVIDADES.filter(a => {
      if (f.soloHoy && a.fecha !== hoy) return false;
      if (!f.soloHoy && f.dia !== 'todos' && a.fecha !== f.dia) return false;
      if (f.espacio !== 'todos' && a.espacioNombre !== f.espacio) return false;
      if (f.sede !== 'todos' && a.sede !== f.sede) return false;
      if (!coincideBusqueda(a, f.texto)) return false;
      return true;
    });
  }

  function agrupar(actividades) {
    const porDia = new Map();
    actividades.forEach(a => {
      if (!porDia.has(a.fecha)) porDia.set(a.fecha, { label: a.diaLabel, items: [] });
      porDia.get(a.fecha).items.push(a);
    });

    return [...porDia.entries()]
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([fecha, data]) => {
        const items = [...data.items].sort((a, b) => {
          const diff = a.hora.localeCompare(b.hora);
          return diff !== 0 ? diff : a.espacioNombre.localeCompare(b.espacioNombre);
        });
        return { fecha, label: data.label, items };
      });
  }

  function render() {
    sincronizarSedeCards();

    const resultado = filtrar();
    const grupos = agrupar(resultado);
    const f = obtenerFiltros();

    $count.textContent = resultado.length === 1
      ? '1 actividad encontrada'
      : resultado.length + ' actividades encontradas';

    if (f.sede !== 'todos') {
      $filtroSede.hidden = false;
      $filtroSede.textContent = `Viendo actividades en ${f.sede}`;
    } else {
      $filtroSede.hidden = true;
      $filtroSede.textContent = '';
    }

    $empty.hidden = resultado.length !== 0;
    $listado.innerHTML = '';

    grupos.forEach(dia => {
      const diaWrap = document.createElement('section');
      diaWrap.className = 'fdl-dia-grupo';
      diaWrap.innerHTML = `
        <div class="fdl-dia-header">
          <h2>${escapeHtml(dia.label)}</h2>
          <div class="fdl-dia-linea"></div>
        </div>
      `;

      const listaWrap = document.createElement('div');
      listaWrap.className = 'fdl-dia-lista';

      listaWrap.innerHTML = dia.items.map(a => {
        const cat = CATEGORIAS[a.categoria] || null;
        const colorCard = a.colorOverride || (cat ? cat.color : null);
        const catStyle = colorCard ? ` style="--cat-color:${colorCard}"` : '';
        const textoEtiqueta = a.etiqueta || (cat ? cat.grupoLabel : '');
        const catBadge = textoEtiqueta ? `<span class="fdl-card-cat">${escapeHtml(textoEtiqueta)}</span>` : '';
        const lugar = espacioLabel(a);
        return `
        <div class="fdl-card"${catStyle}>
          ${catBadge}
          <span class="fdl-hora">${escapeHtml(a.hora)} horas</span>
          <p class="fdl-card-titulo">${escapeHtml(a.nombre)}</p>
          ${a.descripcion ? `<p class="fdl-card-desc">${escapeHtml(a.descripcion)}</p>` : ''}
          ${a.moderacion ? `<p class="fdl-card-mod">${escapeHtml(a.moderacion)}</p>` : ''}
          ${a.auspiciantes ? `<p class="fdl-card-auspicia">${escapeHtml(a.auspiciantes)}</p>` : ''}
          <span class="fdl-card-sede">${escapeHtml(lugar)}</span>
        </div>
      `;
      }).join('');

      diaWrap.appendChild(listaWrap);

      $listado.appendChild(diaWrap);
    });
  }

  /* ---------- Eventos ---------- */
  $dia.addEventListener('change', () => { $hoy.setAttribute('aria-pressed', 'false'); render(); });
  $espacio.addEventListener('change', render);
  $sede.addEventListener('change', render);
  $buscar.addEventListener('input', render);

  $hoy.addEventListener('click', () => {
    const activo = $hoy.getAttribute('aria-pressed') === 'true';
    $hoy.setAttribute('aria-pressed', activo ? 'false' : 'true');
    if (!activo) $dia.value = 'todos';
    render();
  });

  $limpiar.addEventListener('click', () => {
    $dia.value = 'todos';
    $espacio.value = 'todos';
    $sede.value = 'todos';
    $buscar.value = '';
    $hoy.setAttribute('aria-pressed', 'false');
    render();
  });

  renderLeyenda();
  renderSedes();
  poblarSelects();
  render();
})();
</script>				</div>
				</div>
					</div>
		</div>
					</div>
		</section>
		","scripts":["elementor-frontend"],"styles":[]}}

