.evento-cc-divider{
    max-width:450px;
    margin:24px auto 24px;
    border-top:1px solid rgba(0,39,81,.12);
}

/* COORDINACIÓN */
.evento-cc-coord{
    max-width:500px;
    display:flex;
    align-items:center;
    gap:20px;
    margin-top:28px;
}

.evento-cc-coord-foto{
    flex-shrink:0;
    display:block;
}

.evento-cc-coord-foto img{
    width:84px;
    height:84px;
    border-radius:50%;
    object-fit:cover;
    display:block;
    transition:.3s;
}

.evento-cc-coord-foto:hover img{
    opacity:.85;
}

