,"titulo":"Modalidades de mediación para personas con discapacidad visual y auditiva."}],"avisos":[],"suspendePorLluvia":false,"municipal":true,"coords":{"lat":-31.6687,"lng":-60.71668}},{"id":"museo-de-la-mutualidad-y-la-cooperacion","nombre":"Museo de la Mutualidad y la Cooperación","nombreOriginal":"MUSEO DE LA MUTUALIDAD Y LA COOPERACIÓN","direccion":"Dr. Zavalla 3351","horario":{"desde":"18:00","hasta":"22:00","texto":"18 a 22 horas"},"paseo":"oeste","paseoEtiqueta":"Oeste","experiencias":["patrimonio-historia","artes-escenicas"],"accesibilidad":{"apoyos":["rampa-ingreso","darsena-estacionamiento","puertas-anchas","silla-cortesia","acera-buen-estado","pasillos-amplios","bano-accesible","puntos-descanso","pisos-mismo-nivel","braille","subtitulos-audiodescripcion","personal-capacitado","ritmo-pausado","amarre-bicicleta","bicipunto"],"advertencias":[]},"descripcion":"Espacio dedicado a la historia de la primera mutual de la región y a la creación del Hospital Italiano por la comunidad italiana en la segunda oleada inmigratoria del siglo XIX.","actividades":[{"hora":"18, 19, 20 y 21 horas","titulo":"Amor y Ciencia - La historia tras los muros. Visitas guiadas. Mediación por parte del equipo del Museo de la Mutualidad."},{"hora":"19:30 y 21 horas","titulo":"Italia Baila. Danzas típicas italianas."},{"hora":"18 a 22 horas","titulo":"Amor y Esperanza. Pasillos de feriantes, reproducción audiovisual y trabajos in situ de conservación de patrimonio."}],"avisos":[],"suspendePorLluvia":false,"municipal":false,"coords":{"lat":-31.6344256,"lng":-60.7169915}},{"id":"museo-del-puerto-de-santa-fe","nombre":"Museo del Puerto de Santa Fe","nombreOriginal":"MUSEO DEL PUERTO DE SANTA FE","direccion":"Cabecera Dique 1 – Edificio del Reloj – Puerto de Santa Fe","horario":{"desde":"17:00","hasta":"22:00","texto":"17 a 22 horas"},"paseo":"este","paseoEtiqueta":"Este","experiencias":["infancias","aire-libre","patrimonio-historia","artes-escenicas","literario-editorial","gastronomia"],"