 <!-- El modal va fuera de la seccion oscura: adentro heredaria los colores
 claros de los botones y el texto, pensados para fondo azul. -->
 <dialog class="ndlm ndlm-modal" data-ndlm-gastro-modal aria-labelledby="ndlm-gastro-modal-titulo"></dialog>
</div>

<script>
/* ===========================================================================
 NOCHE DE LOS MUSEOS 2026 — Santa Fe
 Gastronomia: mapa de bares adheridos y Food Parks. Se inyecta en el propio
 bloque de Gastronomia, que es autocontenido: no depende de que el bloque
 "NDLM · Scripts" este actualizado. Por eso repite los pocos utilitarios que
 usa (escapado, canvas, compartir) en vez de tomarlos de ndlm.js.

 Los datos no vienen de ningun archivo ni JSON: los lee de la lista de la
 propia seccion, donde cada item lleva los suyos en atributos data-*.

 IDEMPOTENTE, como el resto: el editor de Elementor re-renderiza los widgets
 sin recargar, asi que cada seccion se marca al inicializarse.
 =========================================================================== */
(function () {
 'use strict'

 // ── Utilitarios (copia de los de ndlm.js) ───────────────────────────────
 function esc (s) {
 return String(s == null ? '' : s)
 .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
 .replace(/"/g, '&quot;').replace(/'/g, '&#39;')
 }

 function icono (d, clase) {
 return '<svg class="' + (clase || '') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
 'stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' +
 '<path d="' + d + '"/></svg>'
 }

 var ICONOS = { cerrar: 'M6 6l12 12M18 6L6 18' }

 function comoLlegar (espacio) {
 var destino = espacio.coords
 ? espacio.coords.lat + ',' + espacio.coords.lng
 : (espacio.direccion || espacio.nombre) + ', Santa Fe, Argentina'
 return 'https://www.google.com/maps/dir/?api=1&destination=' + encodeURIComponent(destino)
 }

 // ── Gastronomia: el mapa ─────────────────────────────────────────────────
 /**
 * OpenFreeMap da los mosaicos sin clave ni cuenta, y MapLibre los dibuja.
 * MapLibre pesa ~800 KB, asi que no se pide al cargar la pagina: se pide
 * cuando la seccion esta por entrar en pantalla, y solo una vez.
 *
 * Version fija y con integridad (SRI): si unpkg sirviera otro archivo, el
 * navegador se niega a ejecutarlo. Para actualizar MapLibre hay que
 * recalcular los dos hashes (ver README).
 */
 var MAPLIBRE = {
 js: 'https://unpkg.com/maplibre-gl@5.24.0/dist/maplibre-gl.js',
 jsSri: 'sha384-5+cfbwT0iiub6VsQAdn6yz16nr6sDiQoHx6tm4O8OVYXHYOxcffFmCJBL0dgdvGp',
 css: 'https://unpkg.com/maplibre-gl@5.24.0/dist/maplibre-gl.css',
 cssSri: 'sha384-uTttxo/aOKbdE5RlD/SPzSDoDmNvGlUYPjONi2MN/b7c9HPSvW07OIuyP7uL6jxK'
 }

 // Positron es el estilo mas austero de OpenFreeMap: sin puntos de interes
 // propios que compitan con los bares. Se lo recolorea con la paleta de la
 // noche antes de pintarlo, asi no hay un destello de mapa claro al cargar.
 var ESTILO_MAPA = 'https://tiles.openfreemap.org/styles/positron'

 var PALETA_MAPA = {
 fondo: '#182b4c', // --ndlm-azul-hondo
 manzana: '#1b3157',
 verde: '#213a60',
 agua: '#101d33',
 edificio: '#2b436d',
 edificioBorde: '#344d79',
 calle: '#385078',
 avenida: '#465f86',
 autopista: '#536c94',
 borde: '#2b4166',
 limite: 'rgba(246,128,198,.35)',
 texto: '#cbd3e2', // el mismo celeste de las bajadas sobre azul
 textoAgua: '#8b97b0',
 halo: '#182b4c'
 }

 var TEXTOS_MAPA = {
 'AttributionControl.ToggleAttribution': 'Mostrar créditos del mapa',
 'Map.Title': 'Mapa de bares adheridos y Food Parks',
 'Marker.Title': 'Punto del mapa',
 'NavigationControl.ZoomIn': 'Acercar',
 'NavigationControl.ZoomOut': 'Alejar',
 'CooperativeGesturesHandler.WindowsHelpText': 'Usá Ctrl + la rueda del mouse para acercar el mapa',
 'CooperativeGesturesHandler.MacHelpText': 'Usá ⌘ + la rueda del mouse para acercar el mapa',
 'CooperativeGesturesHandler.MobileHelpText': 'Usá dos dedos para mover el mapa'
 }

 // La promesa vive en window y no en esta funcion: si en la pagina quedara
 // otra copia de este script (un bloque viejo), MapLibre se pide una sola vez.
 function cargarMapLibre () {
 if (window.maplibregl) return Promise.resolve(window.maplibregl)
 if (window.NDLM_MAPLIBRE) return window.NDLM_MAPLIBRE

 if (!document.querySelector('link[data-ndlm-maplibre]')) {
 var hoja = document.createElement('link')
 hoja.rel = 'stylesheet'
 hoja.href = MAPLIBRE.css
 hoja.integrity = MAPLIBRE.cssSri
 hoja.crossOrigin = 'anonymous'
 hoja.setAttribute('data-ndlm-maplibre', '')
 document.head.appendChild(hoja)
 }

 var carga = window.NDLM_MAPLIBRE = new Promise(function (ok, mal) {
 var s = document.createElement('script')
 s.src = MAPLIBRE.js
 s.integrity = MAPLIBRE.jsSri
 s.crossOrigin = 'anonymous'
 s.async = true
 s.onload = function () {
 window.maplibregl ? ok(window.maplibregl) : mal(new Error('MapLibre cargo pero no quedo disponible'))
 }
 s.onerror = function () { mal(new Error('No se pudo cargar MapLibre')) }
 document.head.appendChild(s)
 })
 // Si fallo, que el proximo intento vuelva a probar en vez de heredar el error.
 carga.catch(function () { window.NDLM_MAPLIBRE = null })
 return carga
 }

 /**
 * La "capa" de la noche: recolorea el estilo por tipo de capa y por nombre.
 * Va por patrones y no capa por capa para que siga andando si OpenFreeMap
 * agrega o renombra alguna.
 */
 /** Los creditos del mapa arrancan plegados: queda solo el boton (i), que
 * los abre. MapLibre los muestra desplegados al cargar; se pliegan igual
 * que cuando el usuario arrastra el mapa. */
 function plegarCreditos (mapa) {
 mapa.once('idle', function () {
 var c = mapa.getContainer().querySelector('.maplibregl-ctrl-attrib.maplibregl-compact')
 if (c) c.classList.remove('maplibregl-compact-show')
 })
 }

 function tematizarMapa (estilo) {
 var P = PALETA_MAPA
 estilo.layers = estilo.layers.filter(function (l) {
 // Relieve satelital de zoom bajo y escudos de ruta: ruido a escala de ciudad.
 return l.type !== 'raster' && l.type !== 'hillshade' && !/shield/.test(l.id)
 })
 estilo.layers.forEach(function (l) {
 var id = l.id
 var p = l.paint = l.paint || {}
 if (l.type === 'background') {
 p['background-color'] = P.fondo
 } else if (l.type === 'fill') {
 p['fill-color'] = /water/.test(id) ? P.agua
 : /building/.test(id) ? P.edificio
 : /park|wood|grass|landcover/.test(id) ? P.verde
 : /pier|aeroway/.test(id) ? P.fondo
 : P.manzana
 if (/building/.test(id)) p['fill-outline-color'] = P.edificioBorde
 } else if (l.type === 'line') {
 p['line-color'] = /water/.test(id) ? P.agua
 : /boundary/.test(id) ? P.limite
 : /casing/.test(id) ? P.borde
 : /dashline|pier/.test(id) ? P.fondo
 : /motorway/.test(id) ? P.autopista
 : /major/.test(id) ? P.avenida
 : P.calle
 } else if (l.type === 'symbol') {
 var agua = /water/.test(id)
 p['text-color'] = agua ? P.textoAgua : P.texto
 p['text-halo-color'] = agua ? P.agua : P.halo
 p['text-halo-width'] = 1.2
 p['text-halo-blur'] = 0
 }
 })
 return estilo
 }

 /**
 * El pin es un <button>: se enfoca con Tab y se activa con Enter como
 * cualquier otro control. Los bares son un punto rosa, como los espacios en
 * el mapa del hero; los Food Parks, una etiqueta rosa con nombre y pulso.
 */
 function pinGastro (g) {
 var b = document.createElement('button')
 b.type = 'button'
 b.className = 'ndlm-pin' + (g.foodpark ? ' ndlm-pin--foodpark' : '')
 b.setAttribute('data-gastro', g.id)
 b.setAttribute('aria-haspopup', 'dialog')
 b.setAttribute('aria-label', g.nombre + '. Ver propuesta')
 b.innerHTML = g.foodpark
 ? '<span class="ndlm-pin__marca"><span>Food Park</span></span>'
 : '<span class="ndlm-pin__marca"></span>'
 return b
 }

 /** `pines` se llena con el <button> de cada punto, por id, para poder
 * resaltarlo desde la lista. */
 function crearMapa (ml, contenedor, puntos, pines) {
 return fetch(ESTILO_MAPA)
 .then(function (r) { if (!r.ok) throw new Error('Estilo HTTP ' + r.status); return r.json() })
 .then(function (estilo) {
 var quieto = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches
 var limites = new ml.LngLatBounds()
 puntos.forEach(function (g) { limites.extend([g.coords.lng, g.coords.lat]) })

 contenedor.innerHTML = ''
 var mapa = new ml.Map({
 container: contenedor,
 style: tematizarMapa(estilo),
 bounds: limites,
 // Margen para que la etiqueta de los Food Parks, que es ancha y va
 // centrada en su punto, no quede cortada contra el borde; a la
 // derecha, ademas, lugar para los botones de zoom.
 fitBoundsOptions: { padding: { top: 60, bottom: 60, left: 100, right: 100 }, maxZoom: 15 },
 // En una pagina larga, la rueda del mouse tiene que seguir bajando
 // la pagina: el mapa se mueve con Ctrl + rueda o con dos dedos.
 cooperativeGestures: true,
 dragRotate: false,
 pitchWithRotate: false,
 touchPitch: false,
 fadeDuration: quieto ? 0 : 300,
 attributionControl: { compact: true },
 locale: TEXTOS_MAPA
 })
 mapa.touchZoomRotate.disableRotation()
 mapa.keyboard.disableRotation()
 mapa.addControl(new ml.NavigationControl({ showCompass: false }), 'top-right')
 plegarCreditos(mapa)

 // Los Food Parks se agregan al final para quedar por encima de los bares.
 puntos.filter(function (g) { return !g.foodpark })
 .concat(puntos.filter(function (g) { return g.foodpark }))
 .forEach(function (g) {
 var el = pines[g.id] = pinGastro(g)
 new ml.Marker({ element: el, anchor: 'center' })
 .setLngLat([g.coords.lng, g.coords.lat])
 .addTo(mapa)
 })
 return mapa
 })
 }

 // ── Gastronomia: modal ───────────────────────────────────────────────────
 /**
 * El perfil de Instagram a partir de lo que haya en los datos: un usuario
 * con arroba, sin arroba, o el enlace completo. Devuelve '' si no hay nada
 * utilizable, y entonces la ficha va sin boton.
 *
 * Se rechaza cualquier cosa que no sea un usuario de Instagram valido
 * —letras, numeros, punto y guion bajo— en vez de armar una URL con lo que
 * venga: un dato mal cargado tiene que dejar la ficha sin boton, no mandar
 * al visitante a una direccion inventada.
 */
 function perfilInstagram (valor) {
 var v = String(valor || '').trim()
 if (!v) return ''
 v = v.replace(/^https?:\/\/(www\.)?instagram\.com\//i, '')
 .replace(/^@/, '')
 .replace(/[/?#].*$/, '')
 if (!/^[A-Za-z0-9._]{1,30}$/.test(v)) return ''
 return 'https://www.instagram.com/' + v + '/'
 }

 function contenidoGastro (g) {
 var h = '<div class="ndlm-modal__cuerpo"><div class="ndlm-modal__cabecera"><div>' +
 '<h2 class="ndlm-modal__titulo" id="ndlm-gastro-modal-titulo">' + esc(g.nombre) + '</h2>' +
 '<p class="ndlm-modal__paseo">' + (g.foodpark ? 'Food Park' : 'Bar adherido') + '</p>' +
 '</div><button type="button" class="ndlm-modal__cerrar" data-cerrar aria-label="Cerrar">' +
 icono(ICONOS.cerrar) + '</button></div><div class="ndlm-modal__contenido">'

 if (g.direccion) {
 h += '<div class="ndlm-dato-fuerte"><p class="ndlm-dato-fuerte__rotulo">Dónde</p><p>' + esc(g.direccion) + '</p></div>'
 }

 /* La ficha de un bar es la direccion y nada mas. La propuesta, el horario
 y el beneficio los cuenta el bar en su Instagram, que es a donde lleva
 el unico boton: si cambian el horario o la promo, cambia alla y aca no
 hay nada que actualizar.

 Los Food Parks no tienen perfil propio, asi que siguen contando su
 propuesta en la ficha, como hasta ahora. */
 if (g.foodpark) {
 if (g.propuesta) {
 h += '<div class="ndlm-dato-fuerte"><p class="ndlm-dato-fuerte__rotulo">La propuesta</p>' +
 '<p class="ndlm-descripcion">' + esc(g.propuesta) + '</p></div>'
 }
 if (g.beneficio) {
 h += '<div class="ndlm-beneficio"><p class="ndlm-beneficio__rotulo">Beneficio de la noche</p>' +
 '<p class="ndlm-beneficio__texto">' + esc(g.beneficio) + '</p></div>'
 }
 if (g.horario) {
 h += '<div class="ndlm-dato-fuerte"><p class="ndlm-dato-fuerte__rotulo">Cuándo</p><p>' + esc(g.horario) + '</p></div>'
 }
 }

 h += '</div><div class="ndlm-modal__pie">'
 if (g.foodpark) {
 h += '<a class="ndlm-boton ndlm-boton--rosa" href="' + esc(comoLlegar(g)) +
 '" target="_blank" rel="noopener">Cómo llegar</a>'
 } else {
 // Sin perfil cargado no hay boton: antes que un enlace que no lleva a
 // ningun lado, la ficha se queda con la direccion sola.
 var perfil = perfilInstagram(g.instagram)
 if (perfil) {
 h += '<a class="ndlm-boton ndlm-boton--rosa" href="' + esc(perfil) +
 '" target="_blank" rel="noopener">Conocé la propuesta' +
 '<span class="ndlm-oculto-visual"> de ' + esc(g.nombre) + ' en Instagram</span></a>'
 }
 }
 h += '</div></div>'
 return h
 }

 // ── Gastronomia: inicializacion ──────────────────────────────────────────
 function iniciarGastronomia (raiz) {
 if (raiz.dataset.ndlmGastroInit === '1') return // guarda contra el doble init
 raiz.dataset.ndlmGastroInit = '1'

 var contenedor = raiz.querySelector('[data-ndlm-gastro-mapa]')
 var modal = raiz.querySelector('[data-ndlm-gastro-modal]')
 if (!modal) return

 // Los datos salen de la lista estatica: cada item trae los suyos en
 // atributos data-*. Asi el bloque no depende de ningun archivo ni JSON.
 var puntos = []
 var porId = {}
 raiz.querySelectorAll('.ndlm-gastro__item[data-gastro]').forEach(function (el) {
 var d = el.dataset
 var lat = parseFloat(d.lat)
 var lng = parseFloat(d.lng)
 var g = {
 id: d.gastro,
 foodpark: d.tipo === 'foodpark',
 nombre: d.nombre || '',
 direccion: d.direccion || '',
 horario: d.horario || '',
 propuesta: d.propuesta || '',
 beneficio: d.beneficio || '',
 whatsapp: d.whatsapp || '',
 instagram: d.instagram || '',
 coords: isFinite(lat) && isFinite(lng) ? { lat: lat, lng: lng } : null
 }
 if (!g.id || porId[g.id]) return
 porId[g.id] = g
 puntos.push(g)
 })
 var ultimoFoco = null

 function abrir (id, disparador) {
 var g = porId[id]
 if (!g) return
 // El clic sobre un pin no le da foco (MapLibre lo evita), asi que se
 // recuerda el boton que abrio el modal y no el foco del documento.
 ultimoFoco = disparador || document.activeElement
 modal.dataset.id = id
 modal.innerHTML = contenidoGastro(g)
 if (!modal.open) modal.showModal()
 var x = modal.querySelector('[data-cerrar]')
 if (x) x.focus()
 }

 // Un solo manejador para los pines del mapa y los items de la lista.
 raiz.addEventListener('click', function (ev) {
 if (modal.contains(ev.target)) return
 var b = ev.target.closest('[data-gastro]')
 if (b) abrir(b.getAttribute('data-gastro'), b)
 })

 modal.addEventListener('click', function (ev) {
 if (ev.target === modal || ev.target.closest('[data-cerrar]')) return modal.close()
 var g = porId[modal.dataset.id]
 })
 modal.addEventListener('close', function () {
 modal.dataset.id = ''
 modal.innerHTML = ''
 if (ultimoFoco && document.contains(ultimoFoco)) ultimoFoco.focus()
 ultimoFoco = null
 })

 // ── Lista y mapa conectados ──
 // Pasar el mouse o el foco por un item de la lista resalta su punto en el
 // mapa: con las dos columnas lado a lado, asi se ve donde queda cada bar.
 var pines = {}
 function resaltar (ev, activo) {
 var item = ev.target.closest && ev.target.closest('.ndlm-gastro__item[data-gastro]')
 if (!item) return
 var pin = pines[item.getAttribute('data-gastro')]
 if (pin) pin.classList.toggle('ndlm-pin--activo', activo)
 }
 raiz.addEventListener('mouseover', function (ev) { resaltar(ev, true) })
 raiz.addEventListener('mouseout', function (ev) { resaltar(ev, false) })
 raiz.addEventListener('focusin', function (ev) { resaltar(ev, true) })
 raiz.addEventListener('focusout', function (ev) { resaltar(ev, false) })

 // ── El mapa, recien cuando se va a ver ──
 if (!contenedor) return
 var conCoords = puntos.filter(function (g) { return g.coords })
 if (!conCoords.length) { contenedor.hidden = true; return }

 function sinMapa (err) {
 contenedor.innerHTML = '<p class="ndlm-gastro__aviso">No pudimos cargar el mapa. ' +
 'Todas las propuestas están en la lista de abajo.</p>'
 if (window.console) console.error('[NDLM]', err)
 }

 function montar () {
 contenedor.innerHTML = '<p class="ndlm-gastro__aviso">Cargando el mapa…</p>'
 cargarMapLibre()
 .then(function (ml) { return crearMapa(ml, contenedor, conCoords, pines) })
 .catch(sinMapa)
 }

 if (!('IntersectionObserver' in window)) return montar()
 var vigia = new IntersectionObserver(function (entradas) {
 if (!entradas.some(function (e) { return e.isIntersecting })) return
