 .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
 .replace(/"/g, '&quot;').replace(/'/g, '&#39;')
 }

 /** Ignora comillas y parentesis iniciales al ordenar. */
 function claveOrden (s) { return String(s || '').replace(/^[^\p{L}\p{N}]+/u, '') }

 function sinTildes (s) {
 return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
 }

 function icono (d, clase) {
 return '<svg class="' + (clase || '') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
 'stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' +
 '<path d="' + d + '"/></svg>'
 }

 // Los iconos de la pagina son los pictogramas de accesibilidad (que son
 // informacion, no decoracion) y los de los controles: la cruz del modal, la
 // lupa del buscador y los dos de compartir, que dicen que se comparte: el
 // enlace (un eslabon) o la historia (una captura de pantalla).
 var ICONOS = {
 lupa: 'M11 4a7 7 0 100 14 7 7 0 000-14zM20 20l-4-4',
 cerrar: 'M6 6l12 12M18 6L6 18',
 alerta: 'M12 4l9 16H3zM12 10v4M12 17.5h.01',
 enlace: 'M10 14a4.5 4.5 0 006.4 0l3-3a4.5 4.5 0 00-6.4-6.4l-1.2 1.2M14 10a4.5 4.5 0 00-6.4 0l-3 3a4.5 4.5 0 006.4 6.4l1.2-1.2',
 captura: 'M4 8V5.5A1.5 1.5 0 015.5 4H8M16 4h2.5A1.5 1.5 0 0120 5.5V8M20 16v2.5a1.5 1.5 0 01-1.5 1.5H16M8 20H5.5A1.5 1.5 0 014 18.5V16M9.5 8h5v8h-5z',
 abajo: 'M6 9l6 6 6-6'
 }

 /** Los parentesis de la marca. Decorativos: siempre aria-hidden. */
 function parentesis (clase, abierto) {
 var sep = abierto ? 5 : 1.5
 return '<svg class="' + (clase || '') + '" viewBox="0 0 48 48" fill="none" stroke="currentColor" ' +
 'stroke-width="3.2" stroke-linecap="round" aria-hidden="true" focusable="false">' +
 '<path d="M' + (19 - sep) + ' 8a20 20 0 000 32"/>' +
 '<path d="M' + (29 + sep) + ' 8a20 20 0 010 32"/></svg>'
 }

 function comoLlegar (espacio) {
 var destino = espacio.coords
 ? espacio.coords.lat + ',' + espacio.coords.lng
 : (espacio.direccion || espacio.nombre) + ', Santa Fe, Argentina'
 return 'https://www.google.com/maps/dir/?api=1&destination=' + encodeURIComponent(destino)
 }

 // ── Estado ───────────────────────────────────────────────────────────────
 function crearEstado () {
 return { q: '', paseo: '', experiencia: '', accesibilidad: '' }
 }

 function leerURL (estado) {
 var p = new URLSearchParams(location.search)
 estado.q = p.get('q') || ''
 estado.paseo = p.get('paseo') || ''
 estado.experiencia = p.get('exp') || ''
 estado.accesibilidad = p.get('acc') || ''
 return p.get('espacio') || ''
 }

 function escribirURL (estado, idEspacio, empujar) {
 var p = new URLSearchParams(location.search)
 var set = function (k, v) { v ? p.set(k, v) : p.delete(k) }
 set('q', estado.q); set('paseo', estado.paseo)
 set('exp', estado.experiencia); set('acc', estado.accesibilidad)
 set('espacio', idEspacio || '')
 var url = location.pathname + (p.toString() ? '?' + p : '') + location.hash
 history[empujar ? 'pushState' : 'replaceState']({ ndlm: true, espacio: idEspacio || '' }, '', url)
 }

 // ── Render ───────────────────────────────────────────────────────────────
 function tarjeta (e) {
 var h = '<button type="button" class="ndlm-tarjeta" data-id="' + esc(e.id) + '" ' +
 'aria-haspopup="dialog" aria-label="' + esc(e.nombre) + '. Ver detalle">'

 if (e.paseoEtiqueta) {
 h += '<span class="ndlm-tarjeta__paseo">' + esc(e.paseoEtiqueta) + '</span>'
 }
 h += '<span class="ndlm-tarjeta__nombre">' + esc(e.nombre) + '</span>'

 if (e.direccion) h += '<span class="ndlm-tarjeta__dato">' + esc(e.direccion) + '</span>'
 if (e.horario && e.horario.texto) h += '<span class="ndlm-tarjeta__dato">' + esc(e.horario.texto) + '</span>'
 if (e.suspendePorLluvia) h += '<span class="ndlm-lluvia">Se suspende por lluvia</span>'

 var exps = (e.experiencias || []).map(function (id) { return expPorId[id] }).filter(Boolean)
 if (exps.length) {
 h += '<span class="ndlm-insignias">' + exps.slice(0, 3).map(function (x) {
 return '<span class="ndlm-insignia"><span>' + esc(x.etiqueta) + '</span></span>'
 }).join('') + (exps.length > 3 ? '<span class="ndlm-insignia"><span>+' + (exps.length - 3) + '</span></span>' : '') + '</span>'
 }

 // Solo apoyos en la tarjeta. Las advertencias nunca se resumen en un
 // icono suelto: se leen enteras, en su bloque, dentro del modal.
 var apoyos = e.accesibilidad && e.accesibilidad.apoyos ? e.accesibilidad.apoyos : []
 var clave = DESTACADOS.filter(function (id) { return apoyos.indexOf(id) !== -1 })
 h += '<span class="ndlm-tarjeta__pie">'
 if (clave.length) {
 h += '<span class="ndlm-iconos">' + clave.slice(0, 4).map(function (id) {
 return icono(apoyosPorId[id].icono)
 }).join('') +
 (apoyos.length > clave.slice(0, 4).length
 ? '<span class="ndlm-iconos__mas">+' + (apoyos.length - clave.slice(0, 4).length) + '</span>'
 : '') +
 '<span class="ndlm-oculto-visual">' + apoyos.length + ' apoyos de accesibilidad</span></span>'
 } else {
 h += '<span></span>'
 }
 h += '</span></button>'
 return h
 }

 function bloqueApoyos (acc) {
 if (!acc) return ''
 var apoyos = acc.apoyos || []
 var advertencias = acc.advertencias || []
 if (!apoyos.length && !advertencias.length) {
 return '<p class="ndlm-panel__texto">Este espacio todavía no informó sus apoyos de accesibilidad.</p>'
 }

 var h = '<div class="ndlm-apoyos">'
 GRUPOS.forEach(function (g) {
 var dentro = apoyos.map(function (id) { return apoyosPorId[id] })
 .filter(function (e) { return e && e.grupo === g.id && e.tipo === 'apoyo' })
 if (!dentro.length) return
 h += '<div class="ndlm-apoyos__grupo"><p class="ndlm-apoyos__rotulo">' + esc(g.rotulo) + '</p><ul class="ndlm-apoyos__lista">'
 dentro.forEach(function (e) {
 h += '<li class="ndlm-apoyo">' + icono(e.icono) + '<span>' + esc(e.etiqueta) + '</span></li>'
 })
 h += '</ul></div>'
 })

 // Bloque aparte, con tratamiento visual distinto. Si esto se mezclara con
 // los apoyos, alguien leeria un escalon como si fuera una rampa.
 if (advertencias.length) {
 h += '<div class="ndlm-advertencias"><p class="ndlm-apoyos__rotulo">A tener en cuenta</p><ul class="ndlm-apoyos__lista">'
 advertencias.forEach(function (id) {
 var e = apoyosPorId[id]
 if (e) h += '<li class="ndlm-apoyo">' + icono(ICONOS.alerta) + '<span>' + esc(e.etiqueta) + '</span></li>'
 })
 h += '</ul></div>'
 }
 return h + '</div>'
 }

 function contenidoModal (e) {
 var h = '<div class="ndlm-modal__cuerpo"><div class="ndlm-modal__cabecera"><div>' +
 '<h2 class="ndlm-modal__titulo" id="ndlm-modal-titulo">' + esc(e.nombre) + '</h2>'
 if (e.paseoEtiqueta) h += '<p class="ndlm-modal__paseo">Paseo ' + esc(e.paseoEtiqueta) + '</p>'
 h += '</div><button type="button" class="ndlm-modal__cerrar" data-cerrar aria-label="Cerrar">' +
 icono(ICONOS.cerrar) + '</button></div><div class="ndlm-modal__contenido">'

 // La descripcion dice que ES el espacio, asi que abre la ficha. No va bajo
 // el rotulo "Programación": ahi estaria mal titulada.
 if (e.descripcion) h += '<p class="ndlm-descripcion">' + esc(e.descripcion) + '</p>'

 if (e.direccion) {
 h += '<div class="ndlm-dato-fuerte"><p class="ndlm-dato-fuerte__rotulo">Dónde</p><p>' + esc(e.direccion) + '</p></div>'
 }
 if (e.horario && e.horario.texto) {
 h += '<div class="ndlm-dato-fuerte"><p class="ndlm-dato-fuerte__rotulo">Cuándo</p><p>Abierto de ' + esc(e.horario.texto) + '</p></div>'
 }

 var exps = (e.experiencias || []).map(function (id) { return expPorId[id] }).filter(Boolean)
 if (exps.length) {
 h += '<div class="ndlm-dato-fuerte"><p class="ndlm-dato-fuerte__rotulo">Experiencias</p><p class="ndlm-insignias">' +
 exps.map(function (x) {
 return '<span class="ndlm-insignia"><span>' + esc(x.etiqueta) + '</span></span>'
 }).join('') + '</p></div>'
 }

 // La programacion va entre las experiencias y los apoyos de accesibilidad.
 if (e.actividades && e.actividades.length) {
 h += '<div class="ndlm-dato-fuerte"><p class="ndlm-dato-fuerte__rotulo">Programación</p>' +
 '<ul class="ndlm-programa">'
 e.actividades.forEach(function (a) {
 h += '<li class="ndlm-actividad' + (a.hora ? '' : ' ndlm-actividad--sin-hora') + '">'
 if (a.hora) h += '<span class="ndlm-actividad__hora">' + esc(a.hora) + '</span>'
 h += '<span class="ndlm-actividad__texto">' + esc(a.titulo) + '</span></li>'
 })
 h += '</ul></div>'
 }

 h += bloqueApoyos(e.accesibilidad)

 if (e.suspendePorLluvia) {
 h += '<p class="ndlm-lluvia">Las actividades al aire libre se suspenden por lluvia.</p>'
 }

 h += '</div><div class="ndlm-modal__pie ndlm-modal__pie--cuatro">' +
 '<a class="ndlm-boton ndlm-boton--rosa" href="' + esc(comoLlegar(e)) + '" target="_blank" rel="noopener">Cómo llegar</a>' +
 '<button type="button" class="ndlm-boton ndlm-boton--linea" data-cerrar>Volver a la lista</button>' +
 '<button type="button" class="ndlm-boton ndlm-boton--linea" data-compartir>' +
 icono(ICONOS.enlace) + 'Compartir</button>' +
 '<button type="button" class="ndlm-boton ndlm-boton--linea" data-historia>' +
 icono(ICONOS.captura) + 'Compartir historia</button>' +
 '<span class="ndlm-modal__aviso" data-aviso role="status" aria-live="polite"></span>' +
 '</div></div>'
 return h
 }

 // ── Compartir ────────────────────────────────────────────────────────────
 function enlaceDe (id) {
 var u = new URL(location.href)
 u.searchParams.set('espacio', id)
 u.hash = 'ndlm-espacios'
 return u.toString()
 }

 function textoDe (e) {
 var t = e.nombre + ' — Noche de los Museos, 24 de octubre'
 if (e.horario && e.horario.texto) t += ', de ' + e.horario.texto
 return e.direccion ? t + '. ' + e.direccion + '.' : t + '.'
 }

 function avisar (raiz, mensaje) {
 var a = raiz.querySelector('[data-aviso]')
 if (!a) return
 a.textContent = mensaje
 clearTimeout(a._t)
 a._t = setTimeout(function () { a.textContent = '' }, 4000)
 }

 function copiar (texto) {
 if (!navigator.clipboard || !navigator.clipboard.writeText) return Promise.reject(new Error('sin portapapeles'))
 return navigator.clipboard.writeText(texto)
 }

 /**
 * Compartir el enlace a la ficha. En el celular abre el menu nativo; en
 * escritorio casi nunca existe, asi que el portapapeles es el camino real.
 */
 function compartirEnlace (e, raiz) {
 var url = enlaceDe(e.id)
 function alPortapapeles () {
 copiar(url)
 .then(function () { avisar(raiz, 'Enlace copiado') })
 .catch(function () { avisar(raiz, 'No se pudo copiar el enlace') })
 }
 if (navigator.share) {
 navigator.share({ title: e.nombre, text: textoDe(e), url: url }).catch(function (err) {
 if (err && err.name !== 'AbortError') alPortapapeles()
 })
 return
 }
 alPortapapeles()
 }

 // ── Imagen para compartir ────────────────────────────────────────────────
 /**
 * Dibuja la ficha del espacio en un canvas de 1080x1920 (9:16), el formato
 * de las historias de Instagram. Tambien es el que mejor se ve a pantalla
 * completa en los estados de WhatsApp.
 *
 * Se dibuja a mano en vez de usar una libreria que capture el DOM: el modal
 * tiene scroll, alto variable y tipografias web, y capturarlo daria un
 * recorte impredecible. Dibujando se controla exactamente que entra.
 *
 * Zonas seguras: los 230 px de arriba (barra de progreso, perfil) y los
 * 230 de abajo (responder, reacciones) quedan vacios; todo lo que se dibuja
 * entra entre los dos. La marca apoya su borde superior en el limite de
 * arriba y el pie, en el de abajo. A los costados, el mismo margen de 88 px.
 */
 var COLOR = { azul: '#203a66', rosa: '#ec008c', rosaClaro: '#f680c6', blanco: '#ffffff', tenue: '#cbd3e2' }
 var INCLINACION = Math.tan(15 * Math.PI / 180)
 var HISTORIA = { W: 1080, H: 1920, M: 88, arriba: 230, abajo: 230 }
 HISTORIA.D = HISTORIA.W - HISTORIA.M // borde derecho del contenido

 /**
 * Texto alineado a la izquierda por su tinta, no por su caja. Cada letra
 * trae su propio aire antes del trazo (la N de Geologica a 76 px, unos
 * 6 px): dibujado en `x` a secas, cada linea arrancaria en otro lugar y la
 * marca quedaria corrida respecto del texto de abajo.
 */
 function sangria (ctx, texto) { return ctx.measureText(texto).actualBoundingBoxLeft || 0 }
 function textoIzq (ctx, texto, x, y) { ctx.fillText(texto, x + sangria(ctx, texto), y) }

 function fuente (peso, tam) { return peso + ' ' + tam + 'px "Encode Sans", system-ui, sans-serif' }
 function fuenteMarca (tam) { return '700 ' + tam + 'px Geologica, "Encode Sans", system-ui, sans-serif' }

 // El logo es el mismo del hero: si alli se cambia el src, la historia lo sigue.
 var LOGO_MUNI = 'https://www.santafeciudad.gov.ar/capitalcultural/wp-content/uploads/2026/04/logoMuniPNG-8.png'

 /** Carga el logo para el canvas. Si no llega (o llega de otro dominio sin
 * CORS, que "ensuciaria" el canvas y no dejaria exportarlo), resuelve null
 * y la historia sale igual, sin logo. */
 function cargarLogo () {
 var img = document.querySelector('.ndlm-hero__logo img')
 var src = (img && img.getAttribute('src')) || LOGO_MUNI
 return new Promise(function (ok) {
 var logo = new Image()
 logo.crossOrigin = 'anonymous'
 logo.onload = function () { ok(logo.naturalWidth ? logo : null) }
 logo.onerror = function () { ok(null) }
 logo.src = src
 })
 }

 /**
 * La parte visible del logo: el rectangulo que ocupa su dibujo, sin el
 * margen transparente que suele traer un PNG exportado. Con ese margen,
 * el logo arrancaria mas abajo que el texto del pie y terminaria antes del
 * margen derecho. Si no se puede leer (canvas sucio por CORS), devuelve la
 * imagen entera.
 */
 function tintaLogo (logo) {
 var w = logo.naturalWidth
 var h = logo.naturalHeight
 var entera = { x: 0, y: 0, w: w, h: h }
 try {
 var c = document.createElement('canvas')
 c.width = w
 c.height = h
 var cx = c.getContext('2d')
 cx.drawImage(logo, 0, 0)
 var px = cx.getImageData(0, 0, w, h).data
 var x0 = w, y0 = h, x1 = -1, y1 = -1
 for (var y = 0; y < h; y++) {
 for (var x = 0; x < w; x++) {
 if (px[(y * w + x) * 4 + 3] > 16) {
 if (x < x0) x0 = x
 if (x > x1) x1 = x
 if (y < y0) y0 = y
 if (y > y1) y1 = y
 }
 }
 }
 return x1 < 0 ? entera : { x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1 }
 } catch (err) { return entera }
 }

 /**
 * La marca del hero —NOCHE / DE LOS / MUSEOS con cada O como parentesis
 * blanco— con las mismas proporciones que .ndlm-lockup__o. En la historia
 * va en negrita y con las lineas alineadas a la izquierda en `izquierda`;
 * devuelve la caja que ocupa.
 */
 var LOCKUP = [['N', 'CHE'], ['DE L', 'S'], ['MUSE', 'S']]
 function lockupCanvas (ctx, izquierda, arriba, tam) {
 ctx.font = fuenteMarca(tam)
 ctx.letterSpacing = (tam * 0.01) + 'px'
 var o = tam * 0.54
 var anchos = LOCKUP.map(function (l) { return ctx.measureText(l[0]).width + o + ctx.measureText(l[1]).width })
 var ancho = Math.max.apply(null, anchos)
 LOCKUP.forEach(function (l, i) {
 var base = arriba + tam * 0.74 + i * tam * 0.98
 var x = izquierda + sangria(ctx, l[0])
 ctx.fillStyle = COLOR.rosa
 ctx.fillText(l[0], x, base)
 x += ctx.measureText(l[0]).width
 // Mitad derecha de un anillo: centro a .12em del borde de la caja,
 // radio exterior .36em y trazo de .125em, como en el CSS.
 ctx.save()
 ctx.strokeStyle = COLOR.blanco
 ctx.lineWidth = tam * 0.125
 ctx.beginPath()
 ctx.arc(x + tam * 0.12, base - tam * 0.36, tam * (0.36 - 0.0625), -Math.PI / 2, Math.PI / 2)
 ctx.stroke()
 ctx.restore()
 ctx.fillStyle = COLOR.rosa
 ctx.fillText(l[1], x + o, base)
 })
 ctx.letterSpacing = '0px'
 return { x: izquierda, ancho: ancho, fin: arriba + tam * 0.74 + 2 * tam * 0.98 + tam * 0.1 }
 }

 /** Parte el texto en lineas que entren en `ancho`. Devuelve las lineas. */
 function cortar (ctx, texto, ancho, maxLineas) {
 var palabras = String(texto).split(/\s+/)
 var lineas = []
 var actual = ''
 var sobra = false
 for (var i = 0; i < palabras.length; i++) {
 var prueba = actual ? actual + ' ' + palabras[i] : palabras[i]
 if (ctx.measureText(prueba).width <= ancho || !actual) { actual = prueba; continue }
 lineas.push(actual)
 actual = palabras[i]
 if (maxLineas && lineas.length === maxLineas) { sobra = true; break }
 }
 if ((!maxLineas || lineas.length < maxLineas) && actual) lineas.push(actual)
 // Los puntos suspensivos van solo si quedo texto afuera: un nombre que
 // entra justo en el maximo de lineas no esta cortado.
 if (sobra) {
 var u = lineas[maxLineas - 1]
 while (u && ctx.measureText(u + '…').width > ancho) u = u.replace(/\s*\S+$/, '')
 lineas[maxLineas - 1] = (u || '').replace(/[\s.,;:]+$/, '') + '…'
 }
 return lineas
 }

 /** La barra inclinada del sistema. */
 function barraCanvas (ctx, x, y, alto, color) {
 var d = alto * INCLINACION
 var g = alto * 0.19
 ctx.beginPath()
 ctx.moveTo(x + d, y)
 ctx.lineTo(x + d + g, y)
 ctx.lineTo(x + g, y + alto)
 ctx.lineTo(x, y + alto)
 ctx.closePath()
 ctx.fillStyle = color
 ctx.fill()
 }

 /**
 * En la historia las horas van abreviadas: "19 a 21 h", "20:30 h",
 * "Duracion 1 h". Es una red social, la pieza se lee de un vistazo y la
 * abreviatura deja la columna de horas angosta. La pagina sigue diciendo
 * "horas": esto solo cambia lo que se dibuja en el canvas.
 */
 function horaCorta (t) {
 return typeof t === 'string' ? t.replace(/(\d)\s+horas?\b/g, '$1 h') : t
 }

 function conHorasCortas (e) {
 var c = {}
 for (var k in e) c[k] = e[k]
 if (e.horario) c.horario = { desde: e.horario.desde, hasta: e.horario.hasta, texto: horaCorta(e.horario.texto) }
 c.actividades = (e.actividades || []).map(function (a) { return { hora: horaCorta(a.hora), titulo: horaCorta(a.titulo) } })
 return c
 }

 function rotulo (ctx, texto, x, y) {
 ctx.font = fuente(700, 26)
 ctx.fillStyle = COLOR.rosa
 ctx.letterSpacing = '3px'
 textoIzq(ctx, texto, x, y)
 ctx.letterSpacing = '0px'
 }

 /**
 * Dibuja el cuerpo de la ficha (todo lo que va entre el encabezado y el pie)
 * a partir de `y` y devuelve donde termino y cuantas actividades entraron.
 *
 * Se llama dos veces: la primera mide, la segunda dibuja corrida hacia abajo
 * para que el bloque quede centrado en el espacio libre. Una ficha con dos
 * actividades no puede quedar pegada arriba con 600 px de vacio debajo.
 */
 function cuerpoFicha (ctx, e, y, tope, cuantas) {
 e = conHorasCortas(e)
 var M = HISTORIA.M
 var ancho = HISTORIA.D - M

 // Nombre del espacio. Sin paseo ni experiencias: la historia dice que
 // es, donde y cuando, y que se hace.
 ctx.fillStyle = COLOR.blanco
 ctx.font = fuente(900, 64)
 y += 54
 cortar(ctx, e.nombre, ancho, 5).forEach(function (l, i) {
 if (i) y += 72
 textoIzq(ctx, l, M, y)
 })

 // Donde y cuando
 if (e.direccion) {
 y += 84
 rotulo(ctx, 'DÓNDE', M, y)
 ctx.font = fuente(600, 38)
 ctx.fillStyle = COLOR.blanco
 cortar(ctx, e.direccion, ancho, 2).forEach(function (l) { y += 42; textoIzq(ctx, l, M, y) })
 }
 if (e.horario && e.horario.texto) {
 y += 96
 rotulo(ctx, 'CUÁNDO', M, y)
 ctx.font = fuente(600, 38)
 ctx.fillStyle = COLOR.blanco
 y += 42
 textoIzq(ctx, 'Abierto de ' + e.horario.texto, M, y)
 }

 // Programacion: hasta donde entre, y se avisa cuanto queda afuera.
 var puestas = 0
 var actividades = (e.actividades || []).filter(function (a) { return a.hora })
 if (!actividades.length) actividades = (e.actividades || []).slice(0, 3)
 if (actividades.length) {
 y += 96
 rotulo(ctx, 'PROGRAMACIÓN', M, y)
 y += 52

 // Todos los textos arrancan en el mismo lugar: una columna comun del
 // ancho de la hora mas larga que entre en el 40% del ancho (si cada
 // actividad midiera la suya, cada titulo arrancaria en otro lado).
 // Una hora mas larga ("22:30/22:45 h hasta el cierre") va sola en su
 // renglon y su texto arranca abajo, en la misma columna que los demas.
 ctx.font = fuente(700, 34)
 var maxColumna = ancho * 0.4
 var columna = 170
 actividades.forEach(function (a) {
 var w = a.hora ? ctx.measureText(a.hora).width + 34 + 24 : 0
 if (w <= maxColumna) columna = Math.max(columna, w)
 })

 for (var j = 0; j < actividades.length; j++) {
 // En la segunda pasada ya se sabe cuantas entraron: se fija ese numero
 // para que lo medido y lo dibujado no se contradigan.
 if (cuantas != null && puestas >= cuantas) break
 var a = actividades[j]
 ctx.font = fuente(700, 34)
 var aparte = !!a.hora && ctx.measureText(a.hora).width + 34 + 24 > columna
 var sangria = a.hora ? columna : 0
 ctx.font = fuente(400, 32)
 var lineas = cortar(ctx, a.titulo, ancho - sangria, 2)
 var altoBloque = (lineas.length + (aparte ? 1 : 0)) * 42 + 24
 // Reserva para el "y N actividades mas", salvo que esta sea la ultima.
 var reserva = j < (e.actividades || []).length - 1 ? 50 : 0
 if (cuantas == null && y + altoBloque + reserva > tope) break

 if (a.hora) {
 barraCanvas(ctx, M, y - 26, 30, COLOR.rosa)
 ctx.font = fuente(700, 34)
 ctx.fillStyle = COLOR.blanco
 ctx.fillText(a.hora, M + 24, y)
 }
 ctx.font = fuente(400, 32)
 ctx.fillStyle = COLOR.tenue
 var arranque = aparte ? y + 42 : y
 lineas.forEach(function (l, k) { ctx.fillText(l, M + sangria, arranque + k * 42) })
 y += altoBloque
 puestas++
 }
 var restantes = (e.actividades || []).length - puestas
 if (restantes > 0) {
 ctx.font = fuente(600, 30)
 ctx.fillStyle = COLOR.rosa
 ctx.fillText('y ' + restantes + (restantes === 1 ? ' actividad más' : ' actividades más'), M + 24, y + 12)
 y += 24
 }
 }

 return { fin: y, puestas: puestas }
 }

 function dibujarHistoria (e, logo) {
 var W = HISTORIA.W
 var H = HISTORIA.H
 var M = HISTORIA.M
 var lienzo = document.createElement('canvas')
 lienzo.width = W
 lienzo.height = H
 var ctx = lienzo.getContext('2d')

 ctx.fillStyle = COLOR.azul
 ctx.fillRect(0, 0, W, H)
 var D = HISTORIA.D

 ctx.textBaseline = 'alphabetic'

 // Encabezado, justo debajo de la zona que tapa Instagram: la marca en el
 // margen izquierdo, alineada con el resto del texto, y la fecha debajo.
 var marca = lockupCanvas(ctx, M, HISTORIA.arriba, 76)
 var yFecha = marca.fin + 44
 ctx.font = fuente(700, 36)
 ctx.fillStyle = COLOR.blanco
 textoIzq(ctx, '24.10.2026', M, yFecha)
 var inicio = yFecha + 50

 // Pie, justo encima de la zona restringida: el texto a la izquierda y el
 // logo de la Municipalidad a la derecha. Los dos arrancan a la misma
 // altura medida por la tinta —el borde de arriba de las letras mas altas
 // y el del dibujo del logo, sin su margen transparente— y el logo
 // termina justo en el margen derecho y en el limite de abajo.
 var pie = H - HISTORIA.abajo
 var altoLogo = 100
 var arribaPie = pie - altoLogo
 ctx.fillStyle = 'rgba(255,255,255,.22)'
 ctx.fillRect(M, arribaPie - 36, D - M, 2)
 var linea1 = 'Entrada libre y gratuita hasta las 00 h'
 var linea2 = 'santafeciudad.gov.ar/capitalcultural'
 ctx.font = fuente(600, 26)
 ctx.fillStyle = COLOR.tenue
 var base1 = arribaPie + ctx.measureText(linea1).actualBoundingBoxAscent
 textoIzq(ctx, linea1, M, base1)
 ctx.font = fuente(700, 26)
 // El enlace en el rosa claro: en cuerpo chico, el magenta pleno no
 // contrasta lo suficiente con el azul.
 ctx.fillStyle = COLOR.rosaClaro
 textoIzq(ctx, linea2, M, base1 + 40)
 if (logo) {
 // Hasta 100 px de alto de dibujo, sin pisar el texto.
 var tinta = tintaLogo(logo)
 var libre = (D - M) - ctx.measureText(linea2).width - 40
 var anchoLogo = Math.min(tinta.w * altoLogo / tinta.h, libre)
 var altoReal = tinta.h * anchoLogo / tinta.w
 ctx.drawImage(logo, tinta.x, tinta.y, tinta.w, tinta.h, D - anchoLogo, arribaPie, anchoLogo, altoReal)
 }
 var tope = arribaPie - 66

 // Primera pasada fuera de pantalla para medir; la segunda, centrada.
 var prueba = document.createElement('canvas').getContext('2d')
 var m = cuerpoFicha(prueba, e, 0, tope - inicio, null)
 var sobra = Math.max(0, (tope - inicio) - m.fin)
 cuerpoFicha(ctx, e, inicio + sobra * 0.42, tope, m.puestas)

 return lienzo
 }

 function comoBlob (lienzo) {
 return new Promise(function (ok) { lienzo.toBlob(ok, 'image/png') })
 }

 /**
 * Arma la historia y la comparte. En el celular abre el menu
 * nativo con la imagen (de ahi, Instagram > Historia). Si el navegador no
 * sabe compartir archivos —casi todo escritorio— la descarga y deja el
 * enlace en el portapapeles, para no perder el camino de vuelta a la ficha.
 */
 function compartirHistoria (e, raiz, boton) {
 if (boton.disabled) return
 boton.disabled = true
 avisar(raiz, 'Preparando la historia…')
 var url = enlaceDe(e.id)

 // Sin esperar las fuentes, el canvas dibuja con la tipografia de respaldo.
 var listo = document.fonts && document.fonts.load
 ? Promise.all([900, 700, 600, 400].map(function (p) { return document.fonts.load(fuente(p, 40)) })
 .concat(document.fonts.load(fuenteMarca(40))))
 : Promise.resolve()

 Promise.all([listo.catch(function () {}), cargarLogo()])
 .then(function (r) { return comoBlob(dibujarHistoria(e, r[1])) })
 .then(function (blob) {
 if (!blob) throw new Error('sin imagen')
 var nombre = e.id + '-ndlm2026-historia.png'
 var archivo = new File([blob], nombre, { type: 'image/png' })

 if (navigator.canShare && navigator.canShare({ files: [archivo] })) {
 // Sin `url`: varias apps (Instagram entre ellas) descartan el archivo
 // si llegan los dos juntos. El enlace va dentro del texto.
 return navigator.share({ files: [archivo], title: e.nombre, text: textoDe(e) + ' ' + url })
 .then(function () { avisar(raiz, '') })
 .catch(function (err) {
 if (err && err.name === 'AbortError') return avisar(raiz, '')
 descargar(blob, nombre, url, raiz)
 })
 }
 descargar(blob, nombre, url, raiz)
 })
 .catch(function () { avisar(raiz, 'No se pudo generar la imagen') })
 .then(function () { boton.disabled = false })
 }

 function descargar (blob, nombre, url, raiz) {
 var enlace = URL.createObjectURL(blob)
 var a = document.createElement('a')
 a.href = enlace
 a.download = nombre
 document.body.appendChild(a)
 a.click()
 a.remove()
 setTimeout(function () { URL.revokeObjectURL(enlace) }, 1000)
 avisar(raiz, 'Historia descargada')
 copiar(url)
 .then(function () { avisar(raiz, 'Historia descargada y enlace copiado') })
 .catch(function () {})
 }

 // ── Inicializacion por nodo ──────────────────────────────────────────────
 function iniciarEspacios (raiz) {
 if (raiz.dataset.ndlmInit === '1') return // guarda contra el doble init
 raiz.dataset.ndlmInit = '1'

 var lista = raiz.querySelector('[data-ndlm-lista]')
 var conteo = raiz.querySelector('[data-ndlm-conteo]')
 var campo = raiz.querySelector('[data-ndlm-buscador]')
 var filtros = raiz.querySelector('[data-ndlm-filtros]')
 var modal = raiz.querySelector('[data-ndlm-modal]')
 var botonMas = raiz.querySelector('[data-ndlm-mas]')
 if (!lista) return

 // Las tarjetas se pintan de a tandas: 12 son tres filas de cuatro. El
 // resto aparece con "Ver más espacios"; cambiar un filtro vuelve a 12.
 var TANDA = 12
 var mostrar = TANDA

 var estado = crearEstado()
 var espacios = []
 var ultimoFoco = null
 var debounce = null

 function coincide (e) {
 if (estado.paseo && e.paseo !== estado.paseo) return false
 if (estado.experiencia && (e.experiencias || []).indexOf(estado.experiencia) === -1) return false
 if (estado.accesibilidad && (e.accesibilidad.apoyos || []).indexOf(estado.accesibilidad) === -1) return false
 if (estado.q) {
 var q = sinTildes(estado.q)
 if (sinTildes(e.nombre).indexOf(q) === -1 && sinTildes(e.direccion || '').indexOf(q) === -1) return false
 }
 return true
 }

 function contar (visibles) {
 var total = visibles.length
 var vistos = Math.min(mostrar, total)
 var filtrado = total !== espacios.length ? ' de ' + espacios.length : ''
 var texto = total === 1
 ? '1 espacio'
 : vistos < total
 ? 'Mostrando ' + vistos + ' de ' + total + ' espacios'
 : total + ' espacios' + filtrado

 // Sin botones de paseo, un ?paseo= de la seccion de recorridos filtraria
 // en silencio y sin forma de volver atras. El chip lo hace visible.
 var chip = ''
 if (estado.paseo) {
 var conPaseo = espacios.filter(function (x) { return x.paseo === estado.paseo })[0]
 if (conPaseo) {
 chip = ' <button type="button" class="ndlm-chip" data-quitar-paseo>' +
 '<span>Paseo ' + esc(conPaseo.paseoEtiqueta) + '</span>' +
 '<span class="ndlm-chip__x" aria-hidden="true">×</span>' +
 '<span class="ndlm-oculto-visual">Quitar este filtro</span></button>'
 }
 }
 conteo.innerHTML = esc(texto) + chip
 if (botonMas) {
 botonMas.hidden = vistos >= total
 // El chevron dice "hay mas abajo"; va en lugar de la barra inclinada.
 botonMas.innerHTML = 'Ver más espacios (' + (total - vistos) + ')' + icono(ICONOS.abajo)
 }
 }

 function pintar () {
 var visibles = espacios.filter(coincide)

 if (!visibles.length) {
 lista.innerHTML = '<div class="ndlm-estado">' + parentesis('ndlm-estado__parentesis', true) +
 '<p class="ndlm-estado__titulo">No hay espacios que coincidan</p>' +
 '<p>Probá con otra búsqueda o quitá alguno de los filtros.</p></div>'
 } else {
 lista.innerHTML = visibles.slice(0, mostrar).map(tarjeta).join('')
 }
 contar(visibles)

 // Los conteos por filtro se recalculan contra los OTROS filtros activos,
 // asi el numero dice cuantos quedarian si lo tocas, no cuantos hay en total.
 if (filtros) {
 filtros.querySelectorAll('[data-filtro]').forEach(function (b) {
 var tipo = b.dataset.filtro
 var valor = b.dataset.valor
 b.setAttribute('aria-pressed', String(estado[tipo] === valor))
 var n = b.querySelector('.ndlm-pildora__n')
 if (!n || !valor) return
 var previo = estado[tipo]
 estado[tipo] = valor
 n.textContent = espacios.filter(coincide).length
 estado[tipo] = previo
 })
 }
 }

 // La tanda siguiente se agrega al final, sin repintar las que ya estan:
 // no se pierde el scroll y cada tarjeta nueva entra con un fundido corto.
 // El foco pasa a la primera nueva, asi con teclado se sigue desde ahi.
 function verMas () {
 var visibles = espacios.filter(coincide)
 var desde = mostrar
 mostrar += TANDA
 var nuevas = visibles.slice(desde, mostrar)
 if (!nuevas.length) return contar(visibles)
 var tmp = document.createElement('div')
 tmp.innerHTML = nuevas.map(tarjeta).join('')
 var primera = tmp.firstElementChild
 Array.prototype.forEach.call(tmp.children, function (t, i) {
 t.classList.add('ndlm-tarjeta--entra')
 t.style.setProperty('--ndlm-orden', i)
 })
 while (tmp.firstChild) lista.appendChild(tmp.firstChild)
 contar(visibles)
 if (primera) primera.focus({ preventScroll: true })
 }
 if (botonMas) botonMas.addEventListener('click', verMas)

 function aplicar (empujar) {
 mostrar = TANDA
 pintar()
 escribirURL(estado, modal && modal.open ? modal.dataset.id : '', empujar)
 }

 // ── Modal ──────────────────────────────────────────────────────────────
 function abrir (id, empujar) {
 var e = espacios.filter(function (x) { return x.id === id })[0]
 if (!e || !modal) return
 ultimoFoco = document.activeElement
 modal.dataset.id = id
 modal.innerHTML = contenidoModal(e)
 if (!modal.open) modal.showModal()
 if (empujar !== false) escribirURL(estado, id, true)
 var cerrar = modal.querySelector('[data-cerrar]')
 if (cerrar) cerrar.focus()
 }

 function cerrar () {
 if (modal && modal.open) modal.close()
 }

 if (modal) {
 modal.addEventListener('click', function (ev) {
 // Clic en el backdrop: el <dialog> es el target cuando se clickea afuera.
 if (ev.target === modal) return cerrar()
 if (ev.target.closest('[data-cerrar]')) return cerrar()

 var abierto = espacios.filter(function (x) { return x.id === modal.dataset.id })[0]
 if (!abierto) return
 if (ev.target.closest('[data-compartir]')) return compartirEnlace(abierto, modal)
 var boton = ev.target.closest('[data-historia]')
 if (boton) return compartirHistoria(abierto, modal, boton)
 })
 // 'close' cubre tanto Esc como close(): un solo lugar para restaurar foco.
 modal.addEventListener('close', function () {
 modal.dataset.id = ''
 modal.innerHTML = ''
 escribirURL(estado, '', false)
 if (ultimoFoco && document.contains(ultimoFoco)) ultimoFoco.focus()
 ultimoFoco = null
 })
 }

 lista.addEventListener('click', function (ev) {
 var t = ev.target.closest('.ndlm-tarjeta')
 if (t) abrir(t.dataset.id, true)
 })

 if (campo) {
 campo.addEventListener('input', function () {
 clearTimeout(debounce)
 debounce = setTimeout(function () { estado.q = campo.value.trim(); aplicar(false) }, 180)
 })
 }

 if (filtros) {
 filtros.addEventListener('click', function (ev) {
 var d = ev.target.closest('[data-desplegar]')
 if (d) {
 var abierto = d.getAttribute('aria-expanded') === 'true'
 d.setAttribute('aria-expanded', String(!abierto))
 var panel = document.getElementById(d.getAttribute('aria-controls'))
 if (panel) panel.hidden = abierto
 return
 }
 var b = ev.target.closest('[data-filtro]')
 if (!b) return
 var tipo = b.dataset.filtro
 estado[tipo] = estado[tipo] === b.dataset.valor ? '' : b.dataset.valor
 aplicar(false)
 })
 }

 // El chip del paseo activo vive junto al conteo, no en los filtros.
 if (conteo) {
 conteo.addEventListener('click', function (ev) {
 if (!ev.target.closest('[data-quitar-paseo]')) return
 estado.paseo = ''
 aplicar(false)
 })
 }

 // "Ver espacio" en el mapa del hero: baja a esta seccion y abre la ficha.
 document.addEventListener('ndlm:abrir', function (ev) {
 var id = ev.detail && ev.detail.id
 if (!id) return
 raiz.scrollIntoView({ block: 'start' })
 abrir(id, true)
 })

 // El boton Atras cierra el modal en vez de salir de la pagina.
 window.addEventListener('popstate', function () {
 var id = leerURL(estado)
 if (campo) campo.value = estado.q
 pintar()
 if (id) abrir(id, false)
 else cerrar()
 })

 // ── Carga de datos ─────────────────────────────────────────────────────
 function arrancar (datos) {
 espacios = (datos && datos.espacios) || []
 espacios.sort(function (a, b) {
 return claveOrden(a.nombre).localeCompare(claveOrden(b.nombre), 'es', { sensitivity: 'base' })
 })

 var idInicial = leerURL(estado)
 if (campo) campo.value = estado.q
 construirFiltros()
 pintar()
 if (idInicial) abrir(idInicial, false)
 raiz.dispatchEvent(new CustomEvent('ndlm:listo', { detail: { total: espacios.length } }))
 // El mapa del hero toma los mismos datos, sin volver a leerlos.
 window.NDLM = window.NDLM || {}
 window.NDLM.espacios = espacios
 document.dispatchEvent(new CustomEvent('ndlm:datos', { detail: { espacios: espacios } }))
 }

 function construirFiltros () {
 if (!filtros) return

 // El paseo ya no tiene botones propios: la seccion "Paseos y recorridos"
 // cumple esa funcion y repetirla aca duplicaba la misma decision. El
 // filtro sigue existiendo porque esos enlaces llegan con ?paseo=, y
 // cuando esta activo se muestra como un chip que se puede quitar.
 var usadas = {}
 espacios.forEach(function (e) { (e.experiencias || []).forEach(function (x) { usadas[x] = 1 }) })
 var exps = VOC_EXPERIENCIAS.entradas.filter(function (x) { return usadas[x.id] })

 var accUsados = {}
 espacios.forEach(function (e) { (e.accesibilidad.apoyos || []).forEach(function (a) { accUsados[a] = 1 }) })
 var accs = VOC_ACCESIBILIDAD.entradas.filter(function (a) {
 return a.tipo === 'apoyo' && accUsados[a.id] && DESTACADOS.indexOf(a.id) !== -1
 })

 function pildoras (tipo, items, conIcono) {
 return items.map(function (i) {
 return '<button type="button" class="ndlm-pildora" data-filtro="' + tipo + '" data-valor="' + esc(i.id) + '" aria-pressed="false">' +
 (conIcono && i.icono ? icono(i.icono, 'ndlm-pildora__icono') : '') +
 '<span class="ndlm-pildora__t">' + esc(i.etiqueta) + '</span>' +
 '<span class="ndlm-pildora__n"></span></button>'
 }).join('')
 }

 // Si la URL ya trae una experiencia, el panel arranca abierto: colapsado
 // el filtro estaria activo y escondido, sin forma de ver cual ni quitarlo.
 var abierto = !!estado.experiencia

 // Experiencias colapsadas: son 12 y ocupaban mas alto que los resultados.
 var h = '<div class="ndlm-filtro-grupo">' +
 '<p class="ndlm-filtro-titulo" id="ndlm-f-experiencia">' +
 '<button type="button" class="ndlm-desplegar" data-desplegar aria-expanded="' + abierto + '" ' +
 'aria-controls="ndlm-exp"><span class="ndlm-desplegar__signo" aria-hidden="true"></span>' +
 '<span>Experiencias</span></button></p>' +
 '<div class="ndlm-pildoras ndlm-pildoras--columna" id="ndlm-exp" role="group" ' +
 'aria-labelledby="ndlm-f-experiencia"' + (abierto ? '' : ' hidden') + '>' +
 pildoras('experiencia', exps) + '</div></div>'

 if (accs.length) {
 h += '<div class="ndlm-filtro-grupo"><p class="ndlm-filtro-titulo" id="ndlm-f-accesibilidad">Accesibilidad</p>' +
 '<div class="ndlm-pildoras ndlm-pildoras--columna" role="group" aria-labelledby="ndlm-f-accesibilidad">' +
 pildoras('accesibilidad', accs, true) + '</div></div>'
 }

 filtros.innerHTML = h
 }

 function sinDatos (err) {
 lista.innerHTML = '<div class="ndlm-estado">' + parentesis('ndlm-estado__parentesis', true) +
 '<p class="ndlm-estado__titulo">No pudimos cargar la programación</p>' +
 '<p>Probá recargar la página. Si el problema sigue, escribinos a ' +
 '<a href="mailto:nochedelosmuseos@santafeciudad.gov.ar">nochedelosmuseos@santafeciudad.gov.ar</a>.</p>' +
 // El motivo tecnico queda a la vista, en chico: quien arma la pagina
 // puede leerlo sin abrir la consola del navegador.
 '<p class="ndlm-estado__detalle">Detalle: ' + esc(err && err.message ? err.message : String(err)) + '</p></div>'
 if (window.console) console.error('[NDLM]', err)
 }

 var fuente = raiz.dataset.src
 if (fuente) {
 lista.innerHTML = '<div class="ndlm-estado">' +
 '<span class="ndlm-cargando">' + parentesis('ndlm-estado__parentesis ndlm-cargando__arco', false) + '</span>' +
 '<p>Cargando la programación…</p></div>'
 fetch(fuente, { credentials: 'same-origin' })
 .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json() })
 .then(arrancar)
 .catch(sinDatos)
 return
 }

 // Sin datos no hay lista: se dice, en vez de dejar la seccion en blanco.
 var embebido = document.getElementById('ndlm-datos')
 try {
 if (!embebido) throw new Error('falta el bloque "NDLM · Datos" (06-datos.html)')
 var datos
 try { datos = JSON.parse(embebido.textContent) } catch (e) {
 throw new Error('el bloque "NDLM · Datos" está incompleto o fue modificado al guardar (' + e.message + ')')
 }
 arrancar(datos)
 } catch (err) {
 sinDatos(err)
 }
 }

 // ── Mapa de los espacios (hero) ──────────────────────────────────────────
 /**
 * Un punto rosa por espacio sobre el mismo mapa nocturno de Gastronomia
 * (OpenFreeMap + MapLibre). Los municipales laten. Tocar un punto abre una
 * ficha breve; "Ver espacio" baja a la seccion de espacios y abre la ficha
 * completa.
 *
 * MapLibre y el estilo se piden igual que en Gastronomia, y la promesa de
 * carga es la misma (window.NDLM_MAPLIBRE): si las dos secciones estan en la
 * pagina, MapLibre se descarga una sola vez.
 */
 var MAPLIBRE = {
 js: 'https://unpkg.com/maplibre-gl@5.24.0/dist/maplibre-gl.js',
 jsSri: 'sha384-5+cfbwT0iiub6VsQAdn6yz16nr6sDiQoHx6tm4O8OVYXHYOxcffFmCJBL0dgdvGp',
 css: 'https://unpkg.com/maplibre-gl@5.24.0/dist/maplibre-gl.css',
 cssSri: 'sha384-uTttxo/aOKbdE5RlD/SPzSDoDmNvGlUYPjONi2MN/b7c9HPSvW07OIuyP7uL6jxK'
 }
 var ESTILO_MAPA = 'https://tiles.openfreemap.org/styles/positron'
 // Centro de la ciudad, para cuando todavia no hay espacios con coordenadas.
 var SANTA_FE = { centro: [-60.7068, -31.6400], zoom: 12.3 }

 var PALETA_MAPA = {
 fondo: '#182b4c', manzana: '#1b3157', verde: '#213a60', agua: '#101d33',
 edificio: '#2b436d', edificioBorde: '#344d79', calle: '#385078', avenida: '#465f86',
 autopista: '#536c94', borde: '#2b4166', limite: 'rgba(246,128,198,.35)',
 texto: '#cbd3e2', textoAgua: '#8b97b0', halo: '#182b4c'
 }

 var TEXTOS_MAPA = {
 'AttributionControl.ToggleAttribution': 'Mostrar créditos del mapa',
 'Map.Title': 'Mapa de los espacios participantes',
 'Marker.Title': 'Punto del mapa',
 'NavigationControl.ZoomIn': 'Acercar',
 'NavigationControl.ZoomOut': 'Alejar',
 'CooperativeGesturesHandler.WindowsHelpText': 'Usá Ctrl + la rueda del mouse para acercar el mapa',
 'CooperativeGesturesHandler.MacHelpText': 'Usá ⌘ + la rueda del mouse para acercar el mapa',
 'CooperativeGesturesHandler.MobileHelpText': 'Usá dos dedos para mover el mapa'
 }

 function cargarMapLibre () {
 if (window.maplibregl) return Promise.resolve(window.maplibregl)
 if (window.NDLM_MAPLIBRE) return window.NDLM_MAPLIBRE
 if (!document.querySelector('link[data-ndlm-maplibre]')) {
 var hoja = document.createElement('link')
 hoja.rel = 'stylesheet'
 hoja.href = MAPLIBRE.css
 hoja.integrity = MAPLIBRE.cssSri
 hoja.crossOrigin = 'anonymous'
 hoja.setAttribute('data-ndlm-maplibre', '')
 document.head.appendChild(hoja)
 }
 var carga = window.NDLM_MAPLIBRE = new Promise(function (ok, mal) {
 var s = document.createElement('script')
 s.src = MAPLIBRE.js
 s.integrity = MAPLIBRE.jsSri
 s.crossOrigin = 'anonymous'
 s.async = true
 s.onload = function () {
 window.maplibregl ? ok(window.maplibregl) : mal(new Error('MapLibre cargo pero no quedo disponible'))
 }
 s.onerror = function () { mal(new Error('No se pudo cargar MapLibre')) }
 document.head.appendChild(s)
 })
 carga.catch(function () { window.NDLM_MAPLIBRE = null })
 return carga
 }

 /** La misma recoloracion que Gastronomia: por tipo de capa y por patron de nombre. */
 /** Los creditos del mapa arrancan plegados: queda solo el boton (i), que
 * los abre. MapLibre los muestra desplegados al cargar; se pliegan igual
 * que cuando el usuario arrastra el mapa. */
 function plegarCreditos (mapa) {
 mapa.once('idle', function () {
 var c = mapa.getContainer().querySelector('.maplibregl-ctrl-attrib.maplibregl-compact')
 if (c) c.classList.remove('maplibregl-compact-show')
 })
 }

 function tematizarMapa (estilo) {
 var P = PALETA_MAPA
 estilo.layers = estilo.layers.filter(function (l) {
 return l.type !== 'raster' && l.type !== 'hillshade' && !/shield/.test(l.id)
 })
 estilo.layers.forEach(function (l) {
 var id = l.id
 var p = l.paint = l.paint || {}
 if (l.type === 'background') {
 p['background-color'] = P.fondo
 } else if (l.type === 'fill') {
 p['fill-color'] = /water/.test(id) ? P.agua
 : /building/.test(id) ? P.edificio
 : /park|wood|grass|landcover/.test(id) ? P.verde
 : /pier|aeroway/.test(id) ? P.fondo
 : P.manzana
 if (/building/.test(id)) p['fill-outline-color'] = P.edificioBorde
 } else if (l.type === 'line') {
 p['line-color'] = /water/.test(id) ? P.agua
 : /boundary/.test(id) ? P.limite
 : /casing/.test(id) ? P.borde
 : /dashline|pier/.test(id) ? P.fondo
 : /motorway/.test(id) ? P.autopista
 : /major/.test(id) ? P.avenida
 : P.calle
 } else if (l.type === 'symbol') {
 var agua = /water/.test(id)
 p['text-color'] = agua ? P.textoAgua : P.texto
 p['text-halo-color'] = agua ? P.agua : P.halo
 p['text-halo-width'] = 1.2
 p['text-halo-blur'] = 0
 }
 })
 return estilo
 }

 /** El punto es un <button>. Los municipales laten, cada uno desfasado. */
 function puntoEspacio (e, i) {
 var b = document.createElement('button')
 b.type = 'button'
 b.className = 'ndlm-punto' + (e.municipal ? ' ndlm-punto--municipal' : '')
 b.setAttribute('data-punto', e.id)
 b.setAttribute('aria-haspopup', 'dialog')
 b.setAttribute('aria-label', e.nombre + (e.municipal ? '. Espacio municipal' : '') + '. Ver datos')
 if (e.municipal) b.style.setProperty('--ndlm-desfase', ((i * 0.37) % 2.2).toFixed(2) + 's')
 b.innerHTML = '<span class="ndlm-punto__marca"></span>'
 return b
 }

 function contenidoPunto (e) {
 var h = '<div class="ndlm-modal__cuerpo"><div class="ndlm-modal__cabecera"><div>' +
 '<h2 class="ndlm-modal__titulo" id="ndlm-mapa-modal-titulo">' + esc(e.nombre) + '</h2>'
 if (e.paseoEtiqueta) h += '<p class="ndlm-modal__paseo">Paseo ' + esc(e.paseoEtiqueta) + '</p>'
 h += '</div><button type="button" class="ndlm-modal__cerrar" data-cerrar aria-label="Cerrar">' +
 icono(ICONOS.cerrar) + '</button></div><div class="ndlm-modal__contenido">'
 if (e.horario && e.horario.texto) {
 h += '<div class="ndlm-dato-fuerte"><p class="ndlm-dato-fuerte__rotulo">Cuándo</p><p>Abierto de ' + esc(e.horario.texto) + '</p></div>'
 }
 if (e.direccion) {
 h += '<div class="ndlm-dato-fuerte"><p class="ndlm-dato-fuerte__rotulo">Dónde</p><p>' + esc(e.direccion) + '</p></div>'
 }
 h += '</div><div class="ndlm-modal__pie">' +
 '<button type="button" class="ndlm-boton ndlm-boton--rosa" data-ver-espacio>Ver espacio</button>' +
 '</div></div>'
 return h
 }

 function iniciarMapaEspacios (hero) {
 if (hero.dataset.ndlmMapaInit === '1') return // guarda contra el doble init
 hero.dataset.ndlmMapaInit = '1'

 var contenedor = hero.querySelector('[data-ndlm-mapa-espacios]')
 var modal = hero.querySelector('[data-ndlm-mapa-modal]')
 if (!contenedor) return

 var porId = {}
 var ultimoFoco = null

 function abrirPunto (id, disparador) {
 var e = porId[id]
 if (!e || !modal) return
 // MapLibre no le da foco al pin al hacer clic: se recuerda el boton.
 ultimoFoco = disparador || document.activeElement
 modal.dataset.id = id
 modal.innerHTML = contenidoPunto(e)
 if (!modal.open) modal.showModal()
 var ver = modal.querySelector('[data-ver-espacio]')
 if (ver) ver.focus()
 }

 contenedor.addEventListener('click', function (ev) {
 var b = ev.target.closest('[data-punto]')
 if (b) abrirPunto(b.getAttribute('data-punto'), b)
 })

 if (modal) {
 modal.addEventListener('click', function (ev) {
 if (ev.target === modal || ev.target.closest('[data-cerrar]')) return modal.close()
 if (ev.target.closest('[data-ver-espacio]')) {
 var id = modal.dataset.id
 ultimoFoco = null // el foco lo toma la ficha completa
 modal.close()
 document.dispatchEvent(new CustomEvent('ndlm:abrir', { detail: { id: id } }))
 }
 })
 modal.addEventListener('close', function () {
 modal.dataset.id = ''
 modal.innerHTML = ''
 if (ultimoFoco && document.contains(ultimoFoco)) ultimoFoco.focus()
 ultimoFoco = null
 })
 }

 function sinMapa (err) {
 contenedor.innerHTML = '<p class="ndlm-mapa-esp__aviso">No pudimos cargar el mapa. ' +
 'Todos los espacios están en la lista de abajo.</p>'
 if (window.console) console.error('[NDLM]', err)
 }

 function montar (espacios) {
 var puntos = espacios.filter(function (e) { return e.coords && isFinite(e.coords.lat) && isFinite(e.coords.lng) })
 puntos.forEach(function (e) { porId[e.id] = e })
 if (!puntos.length && window.console) {
 console.warn('[NDLM] Ningun espacio tiene coordenadas: el mapa se ve sin puntos. Ver "Coordenadas" en el README.')
 }

 cargarMapLibre()
 .then(function (ml) {
 return fetch(ESTILO_MAPA)
 .then(function (r) { if (!r.ok) throw new Error('Estilo HTTP ' + r.status); return r.json() })
 .then(function (estilo) {
 var quieto = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches
 var opciones = {
 container: contenedor,
 style: tematizarMapa(estilo),
 // En una pagina larga la rueda tiene que seguir bajando la
 // pagina: el mapa se mueve con Ctrl + rueda o con dos dedos.
 cooperativeGestures: true,
 dragRotate: false,
 pitchWithRotate: false,
 touchPitch: false,
 fadeDuration: quieto ? 0 : 300,
 attributionControl: { compact: true },
 locale: TEXTOS_MAPA
 }
 if (puntos.length) {
 var limites = new ml.LngLatBounds()
 puntos.forEach(function (e) { limites.extend([e.coords.lng, e.coords.lat]) })
 opciones.bounds = limites
 opciones.fitBoundsOptions = { padding: 40, maxZoom: 15 }
 } else {
 opciones.center = SANTA_FE.centro
 opciones.zoom = SANTA_FE.zoom
 }
 contenedor.innerHTML = ''
 var mapa = new ml.Map(opciones)
 mapa.touchZoomRotate.disableRotation()
 mapa.keyboard.disableRotation()
 mapa.addControl(new ml.NavigationControl({ showCompass: false }), 'top-right')
 plegarCreditos(mapa)
 // Los municipales al final, para quedar por encima.
 puntos.filter(function (e) { return !e.municipal })
 .concat(puntos.filter(function (e) { return e.municipal }))
 .forEach(function (e, i) {
 new ml.Marker({ element: puntoEspacio(e, i), anchor: 'center' })
 .setLngLat([e.coords.lng, e.coords.lat])
 .addTo(mapa)
 })
 })
 })
 .catch(sinMapa)
 }

 // Los datos los carga la seccion de espacios; si todavia no estan, se espera.
 function conDatos (fn) {
 if (window.NDLM && window.NDLM.espacios) return fn(window.NDLM.espacios)
 document.addEventListener('ndlm:datos', function una (ev) {
 document.removeEventListener('ndlm:datos', una)
 fn(ev.detail.espacios)
 })
 }

 // MapLibre pesa ~800 KB: se pide recien cuando el mapa esta por verse.
 function cuandoSeVea (fn) {
 if (!('IntersectionObserver' in window)) return fn()
 var vigia = new IntersectionObserver(function (entradas) {
 if (!entradas.some(function (e) { return e.isIntersecting })) return
 vigia.disconnect()
 fn()
 }, { rootMargin: '300px 0px' })
 vigia.observe(contenedor)
 }

 conDatos(function (espacios) { cuandoSeVea(function () { montar(espacios) }) })
 }

 // ── Arranque ─────────────────────────────────────────────────────────────
 // Primero los espacios, que cargan los datos; despues el mapa, que los usa.
 function iniciar () {
 document.querySelectorAll('[data-ndlm-espacios]').forEach(iniciarEspacios)
 document.querySelectorAll('[data-ndlm-hero]').forEach(iniciarMapaEspacios)
 }

 window.NDLM = window.NDLM || {}
 window.NDLM.iniciar = iniciar

 if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', iniciar)
 else iniciar()

 // Elementor re-renderiza los widgets sin recargar: hay que reintentar.
 if (window.jQuery) {
 window.jQuery(window).on('elementor/frontend/init', iniciar)
 }
 window.addEventListener('elementor/frontend/init', iniciar)
})()

</script>				</div>
