<script>(function () {
 'use strict'

 var CAJAS = '.ndlm-limite'

 var REPARTE = '.ndlm-cuadricula'

 var TOPE = 5

 var PLIEGUE = 0.9

 function arrancaFuera (el) {
 var alto = window.innerHeight || document.documentElement.clientHeight
 return el.getBoundingClientRect().top > alto * PLIEGUE
 }

 function piezasDe (caja) {
 var piezas = []
 Array.prototype.forEach.call(caja.children, function (hijo) {
 if (hijo.matches && hijo.matches(REPARTE) && hijo.children.length) {
 piezas.push.apply(piezas, Array.prototype.slice.call(hijo.children))
 } else {
 piezas.push(hijo)
 }
 })
 return piezas
 }

 function entradas () {
 if (!('IntersectionObserver' in window)) return
 if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return

 var marcadas = []
 document.querySelectorAll(CAJAS).forEach(function (caja) {
 piezasDe(caja).forEach(function (pieza, i) {

 if (pieza.classList.contains('ndlm-entrada')) return
 if (!arrancaFuera(pieza)) return
 pieza.classList.add('ndlm-entrada')
 pieza.style.setProperty('--ndlm-orden', Math.min(i, TOPE))
 marcadas.push(pieza)
 })
 })

 if (!marcadas.length) return

 document.documentElement.classList.add('ndlm-anima')

 var pendientes = marcadas.slice()

 function mostrar (pieza) {
 pieza.classList.add('ndlm-entrada--visible')
 vigia.unobserve(pieza)
 var i = pendientes.indexOf(pieza)
 if (i >= 0) pendientes.splice(i, 1)
 if (!pendientes.length) {

 vigia.disconnect()
 window.removeEventListener('scroll', alMoverse)
 window.removeEventListener('resize', alMoverse)
 }
 }

 var vigia = new IntersectionObserver(function (vistas) {
 vistas.forEach(function (v) { if (v.isIntersecting) mostrar(v.target) })
 }, { rootMargin: '0px 0px -6% 0px', threshold: 0.03 })

 var pedido = 0
 function barrer () {
 pedido = 0
 var alto = window.innerHeight || document.documentElement.clientHeight
 pendientes.slice().forEach(function (pieza) {
 if (pieza.getBoundingClientRect().top < alto) mostrar(pieza)
 })
 }
 function alMoverse () {
 if (pedido) return
 pedido = requestAnimationFrame(barrer)
 }
 window.addEventListener('scroll', alMoverse, { passive: true })
 window.addEventListener('resize', alMoverse, { passive: true })

 marcadas.forEach(function (pieza) { vigia.observe(pieza) })
 }

 window.NDLM = window.NDLM || {}
 window.NDLM.entradas = entradas

 if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', entradas)
 else entradas()

 if (window.jQuery) window.jQuery(window).on('elementor/frontend/init', entradas)
 window.addEventListener('elementor/frontend/init', entradas)

})();

(function () {
 'use strict'

 var CERRAR = 'M6 6l12 12M18 6L6 18'

 function esc (s) {
 return String(s == null ? '' : s)
 .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
 .replace(/"/g, '&quot;').replace(/'/g, '&#39;')
 }

 function nombreDe (url) {
 try { return decodeURIComponent(String(url).split('/').pop().split('?')[0]) } catch (e) { return 'archivo' }
 }

 var TABLA_CRC = (function () {
 var t = new Uint32Array(256)
 for (var n = 0; n < 256; n++) {
 var c = n
 for (var k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1
 t[n] = c >>> 0
 }
 return t
 })()

 function crc32 (bytes) {
 var c = 0xffffffff
 for (var i = 0; i < bytes.length; i++) c = TABLA_CRC[(c ^ bytes[i]) & 0xff] ^ (c >>> 8)
 return (c ^ 0xffffffff) >>> 0
 }

 function armarZip (archivos) {
 var ahora = new Date()
 var hora = (ahora.getHours() << 11) | (ahora.getMinutes() << 5) | (ahora.getSeconds() >> 1)
 var fecha = ((ahora.getFullYear() - 1980) << 9) | ((ahora.getMonth() + 1) << 5) | ahora.getDate()
 var utf8 = new TextEncoder()
 var partes = []
 var central = []
 var desplazamiento = 0

 archivos.forEach(function (a) {
 var nombre = utf8.encode(a.nombre)
 var crc = crc32(a.datos)
 var tam = a.datos.length

 var local = new DataView(new ArrayBuffer(30))
 local.setUint32(0, 0x04034b50, true)
 local.setUint16(4, 20, true)
 local.setUint16(6, 0x0800, true)
 local.setUint16(8, 0, true)
 local.setUint16(10, hora, true)
 local.setUint16(12, fecha, true)
 local.setUint32(14, crc, true)
 local.setUint32(18, tam, true)
 local.setUint32(22, tam, true)
 local.setUint16(26, nombre.length, true)
 local.setUint16(28, 0, true)
 partes.push(local.buffer, nombre, a.datos)

 var dir = new DataView(new ArrayBuffer(46))
 dir.setUint32(0, 0x02014b50, true)
 dir.setUint16(4, 20, true)
 dir.setUint16(6, 20, true)
 dir.setUint16(8, 0x0800, true)
 dir.setUint16(10, 0, true)
 dir.setUint16(12, hora, true)
 dir.setUint16(14, fecha, true)
 dir.setUint32(16, crc, true)
 dir.setUint32(20, tam, true)
 dir.setUint32(24, tam, true)
 dir.setUint16(28, nombre.length, true)
 dir.setUint32(42, desplazamiento, true)
 central.push(dir.buffer, nombre)

 desplazamiento += 30 + nombre.length + tam
 })

 var tamCentral = central.reduce(function (s, p) { return s + p.byteLength }, 0)
 var fin = new DataView(new ArrayBuffer(22))
 fin.setUint32(0, 0x06054b50, true)
 fin.setUint16(8, archivos.length, true)
 fin.setUint16(10, archivos.length, true)
 fin.setUint32(12, tamCentral, true)
 fin.setUint32(16, desplazamiento, true)

 return new Blob(partes.concat(central, [fin.buffer]), { type: 'application/zip' })
 }

 function entregar (blob, nombre) {
 var url = URL.createObjectURL(blob)
 var a = document.createElement('a')
 a.href = url
 a.download = nombre
 document.body.appendChild(a)
 a.click()
 a.remove()
 setTimeout(function () { URL.revokeObjectURL(url) }, 60000)
 }

 function iniciarZip (carpeta) {
 var caja = carpeta.querySelector('[data-ndlm-zip]')
 if (!caja || !window.fetch || !window.Blob || !window.TextEncoder) return
 var boton = caja.querySelector('button')
 var aviso = caja.querySelector('[role="status"]')
 var textoBoton = boton.textContent
 caja.hidden = false

 boton.addEventListener('click', function () {
 if (boton.disabled) return
 var urls = Array.prototype.map.call(
 carpeta.querySelectorAll('.ndlm-archivo [download]'),
 function (a) { return { url: a.href, nombre: a.getAttribute('download') || nombreDe(a.href) } }
 )
 var archivos = []
 boton.disabled = true
 boton.setAttribute('aria-disabled', 'true')

 function siguiente (i) {
 if (i >= urls.length) return Promise.resolve()
 boton.textContent = 'Preparando ' + (i + 1) + ' de ' + urls.length + '…'
 return fetch(urls[i].url, { credentials: 'same-origin' })
 .then(function (r) {
 if (!r.ok) throw new Error(r.status + ' ' + urls[i].url)
 return r.arrayBuffer()
 })
 .then(function (buf) {
 archivos.push({ nombre: urls[i].nombre, datos: new Uint8Array(buf) })
 return siguiente(i + 1)
 })
 }

 aviso.textContent = 'Preparando la carpeta. Puede tardar unos segundos.'
 siguiente(0)
 .then(function () {
 entregar(armarZip(archivos), carpeta.getAttribute('data-zip') || 'carpeta.zip')
 aviso.textContent = 'Listo: la carpeta se descargó con ' + archivos.length + ' archivos.'
 })
 .catch(function (err) {
 if (window.console) console.error('[NDLM prensa]', err)
 aviso.textContent = 'No pudimos armar el .zip. Podés descargar los archivos uno por uno.'
 })
 .then(function () {
 boton.disabled = false
 boton.removeAttribute('aria-disabled')
 boton.textContent = textoBoton
 })
 })
 }

 function crearVisor () {
 var d = document.createElement('dialog')
 d.className = 'ndlm ndlm-modal ndlm-visor'
 d.setAttribute('aria-labelledby', 'ndlm-visor-titulo')
 d.innerHTML =
 '<div class="ndlm-visor__cuerpo">' +
 '<div class="ndlm-modal__cabecera">' +
 '<div>' +
 '<h2 class="ndlm-modal__titulo" id="ndlm-visor-titulo" data-titulo></h2>' +
 '<p class="ndlm-modal__paseo" data-posicion></p>' +
 '</div>' +
 '<button type="button" class="ndlm-modal__cerrar" data-cerrar>' +
 '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true" focusable="false"><path d="' + CERRAR + '"/></svg>' +
 '<span class="ndlm-oculto-visual">Cerrar</span>' +
 '</button>' +
 '</div>' +
 '<div class="ndlm-visor__escena"><img data-imagen alt=""></div>' +
 '<div class="ndlm-modal__pie ndlm-visor__pie">' +
 '<button type="button" class="ndlm-boton ndlm-boton--linea" data-paso="-1">Anterior</button>' +
 '<button type="button" class="ndlm-boton ndlm-boton--linea" data-paso="1">Siguiente</button>' +
 '<a class="ndlm-boton" data-descargar download>Descargar</a>' +
 '<span class="ndlm-visor__nombre" data-nombre></span>' +
 '</div>' +
 '</div>'
 document.body.appendChild(d)
 return d
 }

 function iniciarVisor (raiz) {
 if (typeof HTMLDialogElement === 'undefined') return
 var visor = null
 var lista = []
 var titulo = ''
 var credito = ''
 var actual = 0
 var origen = null

 function mostrar (i) {
 actual = (i + lista.length) % lista.length
 var it = lista[actual]
 var img = visor.querySelector('[data-imagen]')
 img.src = it.url
 img.alt = it.alt
 visor.querySelector('[data-titulo]').textContent = titulo
 visor.querySelector('[data-posicion]').textContent =
 (actual + 1) + ' de ' + lista.length + (credito ? ' · ' + credito : '')
 visor.querySelector('[data-nombre]').textContent = it.etiqueta
 var desc = visor.querySelector('[data-descargar]')
 desc.href = it.url
 desc.setAttribute('download', it.nombre)
 desc.innerHTML = 'Descargar<span class="ndlm-oculto-visual"> ' +
 esc(it.etiqueta || (titulo + ', ' + (actual + 1) + ' de ' + lista.length)) + '</span>'
 var unico = lista.length < 2
 visor.querySelectorAll('[data-paso]').forEach(function (b) { b.hidden = unico })
 }

 function preparar () {
 if (visor) return
 visor = crearVisor()
 visor.addEventListener('click', function (ev) {
 if (ev.target === visor || ev.target.closest('[data-cerrar]')) { visor.close(); return }
 var paso = ev.target.closest('[data-paso]')
 if (paso) mostrar(actual + Number(paso.getAttribute('data-paso')))
 })
 visor.addEventListener('keydown', function (ev) {
 if (ev.key === 'ArrowRight') { mostrar(actual + 1); ev.preventDefault() }
 if (ev.key === 'ArrowLeft') { mostrar(actual - 1); ev.preventDefault() }
 })
 visor.addEventListener('close', function () {
 visor.querySelector('[data-imagen]').removeAttribute('src')
 if (origen && origen.focus) origen.focus()
 })
 }

 raiz.addEventListener('click', function (ev) {
 var enlace = ev.target.closest('[data-ndlm-ver]')
 if (!enlace || ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.button) return
 var carpeta = enlace.closest('[data-ndlm-carpeta]')
 if (!carpeta) return
 ev.preventDefault()
 preparar()
 titulo = carpeta.querySelector('h2').textContent.trim()
 credito = carpeta.getAttribute('data-credito') || ''
 var enlaces = Array.prototype.slice.call(carpeta.querySelectorAll('[data-ndlm-ver]'))
 lista = enlaces.map(function (a) {
 var img = a.querySelector('img')

 var li = a.closest('.ndlm-archivo')
 var etiqueta = li && li.querySelector('.ndlm-archivo__etiqueta')
 var descarga = li && li.querySelector('[download]')
 return {
 url: a.href,
 nombre: (descarga && descarga.getAttribute('download')) || nombreDe(a.href),
 etiqueta: etiqueta ? etiqueta.textContent.trim() : '',
 alt: img ? img.alt : ''
 }
 })
 origen = enlace

 mostrar(Math.max(0, enlaces.indexOf(enlace)))
 if (!visor.open) visor.showModal()
 })
 }

 function iniciar () {
 document.querySelectorAll('[data-ndlm-prensa]').forEach(function (raiz) {
 if (raiz.hasAttribute('data-ndlm-init')) return
 raiz.setAttribute('data-ndlm-init', '')
 raiz.querySelectorAll('[data-ndlm-carpeta]').forEach(iniciarZip)
 iniciarVisor(raiz)
 })
 }

 if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', iniciar)
 else iniciar()

 if (window.jQuery) window.jQuery(window).on('elementor/frontend/init', iniciar)
 window.addEventListener('elementor/frontend/init', iniciar)
})()

</script>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false}]

{"timeout":1792700766,"value":{"content":"		<section class="elementor-section elementor-top-section elementor-element elementor-element-755690b elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="755690b" data-element_type="section" data-e-type="section">
